    -- already recognised above from the object's screen)
    for _,root in ipairs(frameRoots) do
        if root.Parent and object:IsDescendantOf(root) then return true end
    end
    return false
end
function trade.IsActive() return trade.active end
local nextScan,elapsed=0,0
local connection
connection=RunService.Heartbeat:Connect(function(dt)
    if not runtimeAlive then connection:Disconnect();trade.active=false;return end
    elapsed=elapsed+dt
    if elapsed<0.15 then return end
    elapsed=0
    local now=os.clock()
    if now>=nextScan then nextScan=now+2;pcall(scan) end
    pcall(update)
end)
-- a new trade window is noticed as it appears, not up to 2 seconds later
local watchedGui
local function watchGui()
    local playerGui=LocalPlayer:FindFirstChildOfClass("PlayerGui")
    if not playerGui or playerGui==watchedGui then return end
    watchedGui=playerGui
    playerGui.DescendantAdded:Connect(function(object)
        if trade.active or not runtimeAlive then return end
        local ok,name=pcall(function() return object.Name end)
        if ok and type(name)=="string" and name:find("[Tt][Rr][Aa][Dd]") and isRoot(object) then
            nextScan=0;elapsed=1
        end
    end)
end
pcall(watchGui)
LocalPlayer.ChildAdded:Connect(function(child) if child:IsA("PlayerGui") then pcall(watchGui) end end)
pcall(scan)
end,"Part at line 801")

-- Small performance log: how much time the add-on's GUI work took in the last 30 seconds
-- and the longest frame in that time, so a freeze can be told apart from the game's own lag.
;vv2Section(function()
local runtime=env.VisualsV2Runtime
local BUCKET=10
local buckets={}
local perf={}
runtime.Perf=perf
local function bucket()
    local index=math.floor(os.clock()/BUCKET)
    local current=buckets[index]
    if not current then
        current={work={},maxFrame=0}
        buckets[index]=current
        buckets[index-4]=nil
    end
    return current
end
-- the first 20 seconds after executing are also kept on their own (start-up report)
local BOOT_WINDOW=20
local boot={work={},longest=0,slow=0}
local function bootAdd(name,seconds)
    if os.clock()-bootStarted<BOOT_WINDOW then boot.work[name]=(boot.work[name] or 0)+seconds end
end
function perf.Add(name,seconds)
    local work=bucket().work
    work[name]=(work[name] or 0)+seconds
    bootAdd(name,seconds)
end
function perf.Wrap(name,callback)
    return function(...)
        local started=os.clock()
        callback(...)
        local work=bucket().work
        local spent=os.clock()-started
        work[name]=(work[name] or 0)+spent
        bootAdd(name,spent)
    end
end
function perf.BootReport()
    local list,sum={},0
    for name,seconds in pairs(boot.work) do list[#list+1]={name,seconds};sum=sum+seconds end
    table.sort(list,function(a,b) return a[2]>b[2] end)
    return {execute=runtime.ExecuteTime,total=sum,top=list,longestFrame=boot.longest,slowFrames=boot.slow,
        finished=os.clock()-bootStarted>=BOOT_WINDOW}
end
function perf.Report()
    local index=math.floor(os.clock()/BUCKET)
    local totals,longest,traded={},0,false
    for offset=0,2 do
        local entry=buckets[index-offset]
        if entry then
            for name,seconds in pairs(entry.work) do totals[name]=(totals[name] or 0)+seconds end
            if entry.maxFrame>longest then longest=entry.maxFrame end
            traded=traded or entry.trade==true
        end
    end
    local list,sum={},0
    for name,seconds in pairs(totals) do list[#list+1]={name,seconds};sum=sum+seconds end
    table.sort(list,function(a,b) return a[2]>b[2] end)
    return {total=sum,top=list,longestFrame=longest,trade=traded}
end
local connection
connection=RunService.Heartbeat:Connect(function(dt)
    if not runtimeAlive then connection:Disconnect();return end
    local current=bucket()
    if dt>current.maxFrame then current.maxFrame=dt end
    if runtime.Trade and runtime.Trade.active then current.trade=true end
    if os.clock()-bootStarted<BOOT_WINDOW then
        if dt>boot.longest then boot.longest=dt end
        if dt>0.1 then boot.slow=boot.slow+1 end
    end
end)
end,"Part at line 951")


