    local offset=0
    if humanoid.RigType==Enum.HumanoidRigType.R15 then
        offset=((tonumber(theirHumanoid.HipHeight) or 2)+theirRoot.Size.Y/2)-((tonumber(humanoid.HipHeight) or 2)+root.Size.Y/2)
    end
    local state={character=character,humanoid=humanoid,root=root,puppet=puppet,theirRoot=theirRoot,
        steps=steps,mine=mine,matched=matched,offset=offset,hidden={},connections={},firstPerson=false,parts={}}
    for _,object in ipairs(puppet:GetDescendants()) do
        if object:IsA("BasePart") and object~=theirRoot then state.parts[#state.parts+1]=object end
    end
    state.solid={theirRoot}
    for _,part in ipairs(state.parts) do state.solid[#state.solid+1]=part end
    table.insert(state.connections,RunService.Stepped:Connect(function()
        if current~=state then return end
        for _,part in ipairs(state.solid) do
            if part.CanCollide then part.CanCollide=false end
            if part.CanTouch then part.CanTouch=false end
        end
    end))
    current=state
    for _,object in ipairs(character:GetDescendants()) do hide(state,object) end
    table.insert(state.connections,character.DescendantAdded:Connect(function(object)
        -- (a joint the game puts in later is picked up the next frame, not a second later)
        if animated(object) then state.jointsDirty=true end
        task.defer(function() if current==state and object.Parent then hide(state,object) end end)
    end))
    table.insert(state.connections,humanoid.Died:Connect(function() if current==state then restore(enabled) end end))
    theirRoot.CFrame=root.CFrame*CFrame.new(0,offset,0)
    puppet.Parent=workspace.CurrentCamera or workspace
    state.weapons={}
    local function attachedToMe(display)
        for _,object in ipairs(display:GetDescendants()) do
            if object:IsA("Constraint") or object:IsA("JointInstance") or object:IsA("WeldConstraint") then
                local ends={}
                pcall(function() ends={object.Attachment0 and object.Attachment0.Parent,object.Attachment1 and object.Attachment1.Parent} end)
                pcall(function() ends[#ends+1]=object.Part0;ends[#ends+1]=object.Part1 end)
                for _,part in ipairs(ends) do
                    if typeof(part)=="Instance" and part:IsA("BasePart") and part:IsDescendantOf(character) then return part end
                end
            end
        end
    end
    local function refreshWeapons()
        local folder=workspace:FindFirstChild("WeaponDisplays")
        local seen={}
        for _,display in ipairs(folder and folder:GetChildren() or {}) do
            if display:IsA("BasePart") then
                local body=attachedToMe(display)
                if body then
                    seen[display]=true
                    local entry=state.weapons[display]
                    if not entry then
                        local copy=clone(display)
                        if copy then
                            for _,object in ipairs(copy:GetDescendants()) do
                                if object:IsA("Constraint") or object:IsA("JointInstance") or object:IsA("WeldConstraint")
                                    or object:IsA("LuaSourceContainer") then object:Destroy() end
                            end
                            copy.Anchored=true;copy.CanCollide=false;copy.CanTouch=false;copy.CanQuery=false;copy.Massless=true
                            copy.Parent=puppet
                            entry={copy=copy,body=body,hidden=display.LocalTransparencyModifier}
                            state.weapons[display]=entry
                        end
                    end
                    if entry then entry.body=body end
                end
            end
        end
        for display,entry in pairs(state.weapons) do
            if not seen[display] then
                pcall(function() entry.copy:Destroy() end)
                pcall(function() if display.Parent then display.LocalTransparencyModifier=entry.hidden or 0 end end)
                state.weapons[display]=nil
            end
        end
    end
    state.refreshWeapons=refreshWeapons
    pcall(refreshWeapons)
    local function follow()
        if current~=state then return end
        if not root.Parent or not character.Parent or LocalPlayer.Character~=character then restore();return end
        if not puppet.Parent then puppet.Parent=workspace.CurrentCamera or workspace end
        theirRoot.CFrame=root.CFrame*CFrame.new(0,state.offset,0)
        if state.jointsDirty then
            state.jointsDirty=false
            local ok,fresh=pcall(posedJoints,character)
            if ok then state.mine=fresh end
        end
        -- (every part of it, out from its root: its own joint, with your pose in it)
        local poses=state.mine
        for _,step in ipairs(state.steps) do
            local at
            if step.fixed then
                at=step.from.CFrame*step.fixed
            else
                local entry=step.entry
                local pose=IDENTITY
                if entry.posed then
                    local yours=poses[entry.key]
                    if yours then pose=yours.Transform or IDENTITY end
                end
                if step.forward then at=step.from.CFrame*entry.c0*pose*entry.c1Inverse
                else at=step.from.CFrame*entry.c1*pose:Inverse()*entry.c0Inverse end
            end
            step.part.CFrame=at
        end
        if os.clock()-(state.weaponsAt or 0)>1 then
            state.weaponsAt=os.clock();pcall(state.refreshWeapons)
            -- (your joints looked up again, in case the game has put any new ones in)
            local ok,fresh=pcall(posedJoints,character)
            if ok then state.mine=fresh end
        end
        for display,entry in pairs(state.weapons) do
            if display.Parent and entry.body.Parent then
                local theirBody=puppet:FindFirstChild(entry.body.Name)
                local base=theirBody and theirBody:IsA("BasePart") and theirBody or theirRoot
                local mine=theirBody and entry.body or root
                entry.copy.CFrame=base.CFrame*mine.CFrame:ToObjectSpace(display.CFrame)
                if display.LocalTransparencyModifier~=1 then display.LocalTransparencyModifier=1 end
            end
        end
        -- (your body stays hidden even when the camera's fading puts it back)
        for object in pairs(state.hidden) do
            if object.Parent and object.LocalTransparencyModifier~=1 then object.LocalTransparencyModifier=1 end
        end
        -- first person: the copy goes see-through like your own body would
        local camera=workspace.CurrentCamera
        local head=character:FindFirstChild("Head")
        local close=camera and head and (camera.CFrame.Position-head.Position).Magnitude<1.5 or false
        if close~=state.firstPerson then
            state.firstPerson=close
            for _,part in ipairs(state.parts) do pcall(function() part.LocalTransparencyModifier=close and 1 or 0 end) end
        end
    end
    local bound=pcall(function() RunService:BindToRenderStep(STEP,Enum.RenderPriority.Camera.Value+5,function() pcall(follow) end) end)
    if not bound then table.insert(state.connections,RunService.RenderStepped:Connect(function() pcall(follow) end)) end
    follow()
    -- their animations, through the add-on's animation player (kept on every life)
    if type(runtime.SetAnimationOverride)=="function" then
        pcall(runtime.SetAnimationOverride,template.animations and table.clone(template.animations) or nil)
    end
    stats.applied=stats.applied+1
    return true
end

-- ---------------------------------------------------------------- their weapons, effect and pet
-- Copy Their Weapons, Effect & Pet: while the account you're showing is in the server with you,
-- their knife, gun, knife effect and pet are picked for you in Visual Weapons/Effects (looked at
-- every 2 seconds, so a change of theirs is followed). Each only with its toggle there on; you're
-- told which to turn on. Your own picks come back when it's switched off (or Visual Avatar is).
-- (MMV: only the gun, as Visual Weapons there only has the scopes)
local copy={on=C("vv2VisualAvatarCopyItems",false)==true,userId=nil,saved={},applied={},told={},run=0,
    roles=nil,rolesAt=-math.huge,
    mmv=game.GameId==10413186812 or game.GameId==10769671266 or game.PlaceId==93017634738276 or game.PlaceId==81374640397860}
local COPY_KINDS={
    {kind="Knife",word="knife",label="Knives"},
    {kind="Gun",word="gun",label="Guns"},
    {kind="Effects",word="effect",label="Effects"},
    {kind="Pets",word="pet",label="Pets"},
}
function copy.visuals(kind)
    if copy.mmv and kind~="Gun" then return nil end
    if kind=="Effects" then
        local effects=runtime.ClientKnifeEffects
        return effects and {get=effects.GetState,select=effects.Select,catalog=effects.Catalog or {}}
    elseif kind=="Pets" then
        local pets=runtime.ClientPets
        return pets and {get=pets.GetState,select=pets.Select,catalog=pets.Catalog or {}}
    end
    local skins=runtime.ClientWeaponSkins
    return skins and {get=function() return skins.GetState(kind) end,select=function(id) return skins.Select(kind,id) end,
        catalog=skins.Catalog and skins.Catalog[kind] or {}}
end
function copy.name(kind,id)
    local visuals=copy.visuals(kind)
    local entry=visuals and visuals.catalog[id]
    return type(entry)=="table" and tostring(entry.name or entry.label or id) or tostring(id)
end
function copy.tools(plr)
    local list={}
    for _,container in ipairs({plr.Character,plr:FindFirstChildOfClass("Backpack")}) do
        if container then
            for _,tool in ipairs(container:GetChildren()) do if tool:IsA("Tool") then list[#list+1]=tool end end
        end
    end
    return list
end
function copy.toolKind(tool)
    local name=tool.Name:lower()
    local item=tostring(tool:GetAttribute("ItemType") or ""):lower()
    if name:find("knife",1,true) or item=="knife" then return "Knife" end
    if name:find("gun",1,true) or name:find("scope",1,true) or item=="gun" then return "Gun" end
end
-- (the knife or gun shown on their body: the game points to it from their character, else
-- it's the one of that kind in WeaponDisplays held on to their body)
function copy.display(plr,kind)
    local character=plr.Character
    if not character then return nil end
    local reference=character:FindFirstChild("DisplayRef"..kind)
    if reference and reference:IsA("ObjectValue") and reference.Value and reference.Value.Parent then return reference.Value end
    for _,name in ipairs({kind.."Display",kind.."Holster"}) do
        local object=character:FindFirstChild(name)
        if object and not object:IsA("Tool") then return object end
    end
    local folder=workspace:FindFirstChild("WeaponDisplays")
    for _,display in ipairs(folder and folder:GetChildren() or {}) do
        if display.Name:lower():find(kind:lower(),1,true) then
            local objects={display}
            for _,object in ipairs(display:GetDescendants()) do objects[#objects+1]=object end
            for _,object in ipairs(objects) do
                local ends={}
                pcall(function() ends={object.Part0,object.Part1} end)
                pcall(function() ends[#ends+1]=object.Attachment0 and object.Attachment0.Parent;ends[#ends+1]=object.Attachment1 and object.Attachment1.Parent end)
                for _,part in pairs(ends) do
                    if typeof(part)=="Instance" and part:IsDescendantOf(character) then return display end
                end
            end
        end
    end
end
-- (the game's own player data, when it says what they have equipped)
function copy.gameData(plr)
    if os.clock()-copy.rolesAt>4 then
        copy.rolesAt=os.clock()
        local ok,result=pcall(function()
            local remote=game:GetService("ReplicatedStorage"):FindFirstChild("GetPlayerData",true)
            if remote and remote:IsA("RemoteFunction") then return remote:InvokeServer() end
        end)
        if ok and type(result)=="table" then copy.roles=result end
    end
    local info=type(copy.roles)=="table" and copy.roles[plr.Name]
    return type(info)=="table" and info or nil
end
function copy.identify(kind,object)
    if typeof(object)~="Instance" then return nil end
    local visuals=copy.visuals(kind)
    if not visuals then return nil end
    for _,target in ipairs({object,object.Parent}) do
        if typeof(target)=="Instance" then
            for _,name in ipairs({"ItemID","WeaponID","ItemName"}) do
                local value=target:GetAttribute(name)
                if value~=nil and visuals.catalog[tostring(value)] then return tostring(value) end
            end
        end
    end
    local originals=runtime.OriginalVisuals
    if originals and type(originals.Identify)=="function" then
        local ok,id=pcall(originals.Identify,kind,object)
        if ok and id and visuals.catalog[id] then return id end
    end
end
function copy.detect(plr)
    local found={}
    local info=copy.gameData(plr)
    if info then
        for key,value in pairs(info) do
            local name=type(key)=="string" and key:lower() or ""
            local kind=(name=="effect" or name=="knifeeffect") and "Effects" or name=="pet" and "Pets"
                or name=="knife" and "Knife" or name=="gun" and "Gun" or nil
            local visuals=kind and copy.visuals(kind)
            if visuals and type(value)=="string" and visuals.catalog[value] then found[kind]=value end
        end
    end
    -- (their knife and gun: the one in their hands or backpack, else the one on their body)
    local knives={}
    for _,tool in ipairs(copy.tools(plr)) do
        local kind=copy.toolKind(tool)
        if kind=="Knife" then knives[#knives+1]=tool end
        if kind and not found[kind] then found[kind]=copy.identify(kind,tool) end
    end
    for _,kind in ipairs({"Knife","Gun"}) do
        if not found[kind] then found[kind]=copy.identify(kind,copy.display(plr,kind)) end
    end
    -- (their effect: on their knife)
    if not found.Effects then
        for _,tool in ipairs(knives) do
            found.Effects=copy.identify("Effects",tool)
            if found.Effects then break end
        end
        if not found.Effects then found.Effects=copy.identify("Effects",copy.display(plr,"Knife")) end
    end
    if not found.Pets then found.Pets=copy.identify("Pets",plr.Character and plr.Character:FindFirstChild("Pet")) end
    return found
end
-- (your own picks back, unless you've picked something else since)
function copy.restore()
    for kind,id in pairs(copy.saved) do
        local visuals=copy.visuals(kind)
        if visuals then
            local ok,_,selected=pcall(visuals.get)
            if ok and selected==copy.applied[kind] then pcall(visuals.select,id) end
        end
    end
    table.clear(copy.saved);table.clear(copy.applied);table.clear(copy.told)
end
function copy.stop()
    copy.run=copy.run+1
    copy.userId=nil
    copy.restore()
end
function copy.step(run,userId)
    local plr=Players:GetPlayerByUserId(userId)
    if not plr then
        if not copy.told.absent then
            copy.told.absent=true
            notify("that account isn't in this server, so its weapons, effect and pet can't be copied")
        end
        return
    end
    copy.told.absent=nil
    local found=copy.detect(plr)
    if run~=copy.run then return end
    local copied,needed,words={},{},{}
    for _,spec in ipairs(COPY_KINDS) do
        local id=found[spec.kind]
        local visuals=id and copy.visuals(spec.kind)
        if visuals then
            local ok,on,selected=pcall(visuals.get)
            if ok and not on then
                if copy.told[spec.kind]~=id then
                    copy.told[spec.kind]=id
                    needed[#needed+1]=(copy.mmv and spec.kind=="Gun") and "Matrixscope / Voidscope" or spec.label
                    words[#words+1]=spec.word
                end
            elseif ok and copy.applied[spec.kind]~=id then
                if copy.saved[spec.kind]==nil then copy.saved[spec.kind]=selected or "None" end
                local selectedOk,accepted=pcall(visuals.select,id)
                if selectedOk and accepted~=false then
                    copy.applied[spec.kind]=id;copy.told[spec.kind]=nil
                    copied[#copied+1]=spec.word.." ("..copy.name(spec.kind,id)..")"
                end
            end
        end
    end
    if #copied>0 then notify("copied "..plr.DisplayName.."'s "..table.concat(copied,", ")) end
    if #needed>0 then
        notify("turn on "..table.concat(needed,", ").." in Visual Weapons/Effects to copy "..plr.DisplayName.."'s "..table.concat(words,", "))
    end
end
function copy.start(userId)
    if not copy.on or not enabled or not userId then copy.stop();return end
    if copy.userId==userId then return end
    copy.stop()
    copy.userId=userId
    local run=copy.run
    task.spawn(function()
        while copy.run==run and copy.on and enabled and runtimeAlive do
            local ok,problem=pcall(copy.step,run,userId)
            if not ok then stats.lastError=tostring(problem) end
            task.wait(2)
        end
    end)
end

local function load(reason)
    token=token+1
    local mine=token
    if not enabled then restore();copy.stop();return end
    task.spawn(function()
        local userId,why=resolve(target)
        if mine~=token then return end
        if not userId then notify(why);return end
        copy.start(userId)
        local character=LocalPlayer.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        if not humanoid then return end
        local template,problem=buildTemplate(userId,humanoid.RigType)
        if mine~=token or not enabled then return end
        if not template then stats.lastError=problem;notify(problem);return end
        local label=target..(tostring(userId)~=target and " ("..userId..")" or "")
        local ok,applied,err=pcall(apply,template,label)
        if not ok or applied==false then
            stats.lastError=tostring(ok and err or applied);notify(stats.lastError)
        elseif reason=="user" then notify("showing "..label) end
    end)
end

section:AddTextBox("Username/user ID",function(text)
    text=tostring(text or ""):gsub("^%s+",""):gsub("%s+$","")
    if text=="" or text==target then return end
    target=text
    SetCfg("vv2VisualAvatarTarget",target)
    if enabled then load("user") end
end)
local toggle=addToggle(section,"Visual Avatar",enabled,function(value)
    enabled=value
    SetCfg("vv2VisualAvatarEnabled",value)
    load(value and "user" or nil)
end)
local copyToggle=addToggle(section,"Copy Their Weapons, Effect & Pet",copy.on,function(value)
    copy.on=value
    SetCfg("vv2VisualAvatarCopyItems",value)
    if not value or not enabled then copy.stop();return end
    task.spawn(function()
        local userId=resolve(target)
        if userId and copy.on and enabled then copy.start(userId) end
    end)
end)
section:AddParagraph("Copy Their Weapons, Effect & Pet","While they're in the server with you, their knife, gun, knife effect and pet are picked for you in Visual Weapons/Effects. Each one needs its toggle there on.")
local respawn=LocalPlayer.CharacterAdded:Connect(function(character)
    restore(enabled)
    if not enabled then return end
    -- put straight back on as soon as your new character has a body (it waited up to 4.3
    -- seconds for the game to finish loading your own avatar before; whatever of yours comes
    -- after is hidden as it's put on, and new joints are picked up the next frame)
    local deadline=os.clock()+10
    while enabled and LocalPlayer.Character==character and os.clock()<deadline do
        local humanoid=character:FindFirstChildOfClass("Humanoid")
        if character.Parent and humanoid and humanoid.Health>0 and character:FindFirstChild("HumanoidRootPart") then break end
        task.wait()
    end
    if enabled and LocalPlayer.Character==character then load() end
end)
runtime.VisualAvatar={Load=load,Restore=restore,GetState=function() return enabled,target,current~=nil end,
    GetCopied=function() return table.clone(copy.applied),copy.userId end,
    Detect=function(plr) return copy.detect(plr) end,
    GetDiagnostics=function() local report=table.clone(stats);report.showing=current~=nil;report.hidden=0
        if current then for _ in pairs(current.hidden) do report.hidden=report.hidden+1 end;report.joints=current.matched;report.parts=#current.steps end
        report.copied=table.clone(copy.applied)
        return report end}
runtime.RegisterReset(function()
    toggle:Set(false);copyToggle:Set(false)
    enabled=false;copy.on=false
    token=token+1
    restore()
    copy.stop()
    target=""
    if not runtimeAlive then
        respawn:Disconnect()
        for _,template in pairs(templates) do pcall(function() template.model:Destroy() end) end
        table.clear(templates)
    end
end)
end,"Section \"Visual Avatar\"")

-- Big buttons (Speed Glitch, Trick Shoot): ODH's big-button design from the add-on
-- template (white, 90% see-through, Jura text, rounded corners and the turning gradient
-- outline). Their size can be changed. All the add-on's buttons (big ones and bind ones)
-- take their gradient from the UI customization picked in ODH's Settings (all 3 of its
-- Secondary Variant colours), unless Miscellaneous' Custom Big Button Gradient gives them a
-- 3-colour gradient of your own; bind buttons on or ready like the big buttons, off a little
-- darker. Each big button
-- keeps its saved spot and follows Lock Big Button POS in Miscellaneous. Each section's
-- Hide Button Text hides the words on its buttons.
;vv2Section(function()
local runtime=env.VisualsV2Runtime
local GRADIENT=ColorSequence.new({
    ColorSequenceKeypoint.new(0,Color3.new(0.0784314,0.0784314,0.0784314)),
    ColorSequenceKeypoint.new(0.75,Color3.new(0.0784314,0.0784314,0.54902)),
    ColorSequenceKeypoint.new(1,Color3.new(0.470588,0.156863,0.470588)),
})
-- Miscellaneous can give every big button (these and Bomb Jump's) a gradient of 3 colours
-- of your own instead of its usual one
local style={
    enabled=C("vv2BigButtonGradientEnabled",false)==true,
    colors={
        C("vv2BigButtonGradient1",Color3.fromRGB(20,20,20)),
        C("vv2BigButtonGradient2",Color3.fromRGB(20,20,140)),
        C("vv2BigButtonGradient3",Color3.fromRGB(120,40,120)),
    },
    tracked=setmetatable({}, {__mode="k"}),
}
for index,color in ipairs(style.colors) do
    if typeof(color)~="Color3" then style.colors[index]=GRADIENT.Keypoints[math.min(index,#GRADIENT.Keypoints)].Value end
end
function style.Custom()
    return ColorSequence.new({
        ColorSequenceKeypoint.new(0,style.colors[1]),
        ColorSequenceKeypoint.new(0.5,style.colors[2]),
        ColorSequenceKeypoint.new(1,style.colors[3]),
    })
end
-- ODH's Settings: the UI customization picked there (its files are in the executor's
-- workspace, Ixry Shizuka/customs/ui_customizations, on Delta in Delta's own folder; found
-- even if a part of it is written another way). Its three Secondary Variant colours make the
-- gradient (its Secondary ones for a customization without them), even when they're all the
-- same colour. ODH's own big buttons are copied when they show those colours; which
-- customization is picked is read off ODH's own buttons and menu (the customization whose
-- colours they show) or ODH's saved settings.
style.settings={gradient=nil,name=nil}
style.listeners={}
local THEME_FOLDERS={"Ixry Shizuka/customs/ui_customizations","Ixry Shizuka/customs/ui-customizations",
    "Ixry Shizuka/customs/ui customizations","Ixry Shizuka/customs/UI Customizations","Ixry Shizuka/customs/UI_Customizations"}
local themePlace={folder=nil,root="Ixry Shizuka",scannedAt=-math.huge}
local HttpService=game:GetService("HttpService")
local function hexColor(value)
    if type(value)~="string" then return nil end
    local hex=value:match("^%s*#?(%x%x%x%x%x%x)%s*$")
    if not hex then return nil end
    return Color3.fromRGB(tonumber(hex:sub(1,2),16),tonumber(hex:sub(3,4),16),tonumber(hex:sub(5,6),16)),hex:upper()
end
local function hexOf(color)
    return string.format("%02X%02X%02X",math.floor(color.R*255+0.5),math.floor(color.G*255+0.5),math.floor(color.B*255+0.5))
end
-- a group's colours in their order ("#1. ...", "#2. ...", "#3. ...")
local function orderedColors(group)
    if type(group)~="table" then return nil end
    local list={}
    for key,value in pairs(group) do
        local color=hexColor(value)
        if color then
            local index=tonumber(tostring(key):match("^%s*#?%s*(%d+)")) or 99
            list[#list+1]={index=index,key=tostring(key),color=color}
        end
    end
    if #list<2 then return nil end
    table.sort(list,function(a,b) if a.index~=b.index then return a.index<b.index end return a.key<b.key end)
    local colors={}
    for index,entry in ipairs(list) do colors[index]=entry.color end
    return colors
end
local function sequenceOf(colors)
    if not colors or #colors<2 then return nil end
    -- (spread like ODH's own gradient when there are as many colours as it has)
    local template=GRADIENT.Keypoints
    local points={}
    for index,color in ipairs(colors) do
        local time=#colors==#template and template[index].Time or (index-1)/(#colors-1)
        points[#points+1]=ColorSequenceKeypoint.new(time,color)
    end
    return ColorSequence.new(points)
end
-- the colours of a gradient (or a list of colours) as a set
local function colorSet(source)
    local set,count={},0
    local list=source
    if typeof(source)=="ColorSequence" then
        list={}
        for _,point in ipairs(source.Keypoints) do list[#list+1]=point.Value end
    end
    for _,color in ipairs(list or {}) do
        local hex=hexOf(color)
        if not set[hex] then set[hex]=true;count=count+1 end
    end
    return {set=set,count=count}
end
-- the same colours (every one of the smaller set in the other; one colour all the way
-- through, as some customizations have, only that very colour)
local function sameColors(a,b)
    if not a or not b or a.count<1 or b.count<1 then return false end
    if a.count==1 or b.count==1 then
        if a.count~=b.count then return false end
        return b.set[next(a.set)]==true
    end
    local common=0
    for hex in pairs(a.set) do if b.set[hex] then common=common+1 end end
    return common>=math.min(a.count,b.count)
end
-- (plain white or black all the way through: what an outline shows with no gradient given it)
local function bare(colors)
    if not colors or colors.count~=1 then return false end
    local hex=next(colors.set)
    return hex=="FFFFFF" or hex=="000000"
end
local TEMPLATE_SET=colorSet(GRADIENT)
local GOLD_SET=colorSet({Color3.fromRGB(255,215,0),Color3.fromRGB(255,140,0),Color3.fromRGB(184,134,11)})
local function groupNamed(data,wanted)
    for key,value in pairs(data) do
        if type(key)=="string" and key:lower():gsub("[^%a]","")==wanted then return value end
    end
end
local function fileApi()
    local listFiles=type(listfiles)=="function" and listfiles or env.listfiles
    local readFile=type(readfile)=="function" and readfile or env.readfile
    local isFolder=type(isfolder)=="function" and isfolder or env.isfolder
    return listFiles,readFile,isFolder
end
local function plainName(text) return (tostring(text or ""):lower():gsub("[^%a]","")) end
local function lastPart(path) return (tostring(path):gsub("[/\\]+$","")):match("([^/\\]+)$") or tostring(path) end
-- (a folder's .json files)
local function jsonFiles(folder)
    local listFiles=fileApi()
    if type(listFiles)~="function" then return {} end
    local ok,entries=pcall(listFiles,folder)
    if not ok or type(entries)~="table" then return {} end
    local list={}
    for _,path in ipairs(entries) do
        if type(path)=="string" and path:lower():sub(-5)==".json" then list[#list+1]=path end
    end
    return list
end
-- (the folders straight inside one)
local function subfolders(folder)
    local listFiles,_,isFolder=fileApi()
    if type(listFiles)~="function" then return {} end
    local ok,entries=pcall(listFiles,folder)
    if not ok or type(entries)~="table" then return {} end
    local base=(folder:gsub("\\","/"):gsub("/+$",""))
    local list,seen={},{}
    local function add(path)
        local key=path:lower()
        if not seen[key] then seen[key]=true;list[#list+1]=path end
    end
    for index,entry in ipairs(entries) do
        if index>400 then break end
        if type(entry)=="string" then
            local path=entry:gsub("\\","/")
            local inside=base=="" or path:lower():sub(1,#base+1)==base:lower().."/"
            local rest=inside and (base=="" and path or path:sub(#base+2)) or nil
            local first=rest and rest:match("^([^/]+)/")
            if first then add((base~="" and base.."/" or "")..first)
            elseif type(isFolder)=="function" then
                local okFolder,folderLike=pcall(isFolder,entry)
                if okFolder and folderLike==true then add(entry) end
            end
        end
    end
    return list
end
-- where the customizations are: the usual names first, then ODH's folder (any with "shizuka"
-- in its name), its customs folder and the ui customizations folder in that, however written
local function usualThemeFolder()
    for _,folder in ipairs(THEME_FOLDERS) do
        if #jsonFiles(folder)>0 then return folder,"Ixry Shizuka" end
    end
end
local function scanThemeFolder()
    local roots={"Ixry Shizuka"}
    for _,top in ipairs(subfolders("")) do
        if plainName(lastPart(top)):find("shizuka",1,true) and top~="Ixry Shizuka" then roots[#roots+1]=top end
    end
    for _,root in ipairs(roots) do
        for _,customs in ipairs(subfolders(root)) do
            if plainName(lastPart(customs)):find("custom",1,true) then
                for _,folder in ipairs(subfolders(customs)) do
                    if plainName(lastPart(folder)):find("uicustom",1,true) and #jsonFiles(folder)>0 then return folder,root end
                end
            end
        end
    end
    return nil
end
local function readThemes()
    local list={}
    local _,readFile=fileApi()
    if type(readFile)~="function" then return list end
    -- (the folder found before; while it has none, looked for again: the usual names each time,
    -- the whole workspace at most every 15 s)
    local files=themePlace.folder and jsonFiles(themePlace.folder) or {}
    if #files==0 then
        local folder,root=usualThemeFolder()
        if not folder and os.clock()-themePlace.scannedAt>=15 then
            themePlace.scannedAt=os.clock()
            folder,root=scanThemeFolder()
        end
        if folder then themePlace.folder,themePlace.root=folder,root;files=jsonFiles(folder) end
    end
    style.themeFolder=themePlace.folder
    for _,path in ipairs(files) do
        if type(path)=="string" and path:lower():sub(-5)==".json" then
            local okRead,text=pcall(readFile,path)
            if okRead and type(text)=="string" and #text<200000 then
                local okJson,data=pcall(function() return HttpService:JSONDecode(text) end)
                if okJson and type(data)=="table" then
                    local entry={name=path:match("([^/\\]+)%.[Jj][Ss][Oo][Nn]$") or path,data=data,colors={}}
                    entry.secondary=orderedColors(groupNamed(data,"secondary"))
                    entry.variant=orderedColors(groupNamed(data,"secondaryvariant"))
                    -- (our buttons': its Secondary Variant, all three; its Secondary for one without it)
                    entry.gradient=entry.variant or entry.secondary
                    entry.gradientSet=colorSet(entry.gradient)
                    entry.secondarySet=colorSet(entry.secondary)
                    entry.variantSet=colorSet(entry.variant)
                    for _,group in pairs(data) do
                        if type(group)=="table" then
                            for _,value in pairs(group) do
                                local _,hex=hexColor(value)
                                if hex then entry.colors[hex]=true end
                            end
                        end
                    end
                    if entry.gradient then list[#list+1]=entry end
                end
            end
        end
    end
    return list
end
-- every colour ODH's menu shows right now (none of the add-on's own things, none of
-- Roblox's own menus), and the gradients in it
local OUR_PREFIXES={"visualsv2","vv2_","vv2 "}
local function ours(name)
    name=name:lower()
    for _,prefix in ipairs(OUR_PREFIXES) do if name:sub(1,#prefix)==prefix then return true end end
    return false
end
local ROBLOX_GUIS={RobloxGui=true,RobloxPromptGui=true,RobloxLoadingGUI=true,RobloxNetworkPauseNotification=true,
    TopBarApp=true,InGameMenu=true,PlayerList=true,ExperienceChat=true,BubbleChat=true,PurchasePromptApp=true,
    DevConsoleMaster=true,CoreScriptLocalization=true,FoundationOverlay=true,ThemeProvider=true,TeleportGui=true,
    HeadsetDisconnectedDialog=true,Chat=true,TouchGui=true,BubbleChatContainer=true}
local function guiRoots()
    local roots={}
    local function add(root)
        if typeof(root)~="Instance" then return end
        for _,existing in ipairs(roots) do if existing==root then return end end
        roots[#roots+1]=root
    end
    local hidden=type(gethui)=="function" and gethui or env.gethui
    if type(hidden)=="function" then local ok,root=pcall(hidden);if ok then add(root) end end
    pcall(function() add(game:GetService("CoreGui")) end)
    add(LocalPlayer:FindFirstChildOfClass("PlayerGui"))
    return roots
end
-- (ODH's own big buttons, wherever they were seen: its template's look, a see-through
-- button with a gradient outline)
local bigButtonsSeen=setmetatable({}, {__mode="k"})
local function looksBig(button)
    if not button:IsA("GuiButton") or ours(button.Name) then return false end
    local transparency=button.BackgroundTransparency
    if transparency<0.8 or transparency>0.97 then return false end
    local stroke=button:FindFirstChildOfClass("UIStroke")
    if not stroke or stroke.Thickness<0.8 or stroke.Thickness>3 then return false end
    return stroke:FindFirstChildOfClass("UIGradient")~=nil
end
local function menuColors()
    local seen,found,gradients={},false,{}
    local walked={}
    local total=15000
    local function add(color) if typeof(color)=="Color3" then seen[hexOf(color)]=true end end
    -- (walked by hand, so whole subtrees of ours are left out, each menu with its own share)
    -- (a few hundred at a time, a frame apart, so looking never makes the game hitch)
    local sinceRest=0
    local function walk(object,budget)
        local stack={object}
        while #stack>0 and budget>0 and total>0 do
            local current=table.remove(stack)
            budget=budget-1;total=total-1
            sinceRest=sinceRest+1
            if sinceRest>=400 then sinceRest=0;task.wait() end
            if walked[current] or (current~=object and ours(current.Name)) then
                -- (skipped with everything inside it)
            else
                walked[current]=true
                if current:IsA("GuiObject") then
                    found=true
                    if current:IsA("GuiButton") and looksBig(current) then bigButtonsSeen[current]=true end
                    add(current.BackgroundColor3)
                    if current:IsA("ImageLabel") or current:IsA("ImageButton") then add(current.ImageColor3) end
                elseif current:IsA("UIStroke") then add(current.Color)
                elseif current:IsA("UIGradient") then
                    for _,point in ipairs(current.Color.Keypoints) do add(point.Value) end
                    if #gradients<400 then gradients[#gradients+1]=colorSet(current.Color) end
                end
                for _,child in ipairs(current:GetChildren()) do stack[#stack+1]=child end
            end
        end
    end
    for _,root in ipairs(guiRoots()) do
        local okChildren,children=pcall(function() return root:GetChildren() end)
        -- (in the game's own PlayerGui only the shared containers add-ons use: the game's own
        -- menus are huge and not ODH's)
        local gameGui=root:IsA("PlayerGui")
        for _,gui in ipairs(okChildren and children or {}) do
            pcall(function()
                if ours(gui.Name) or ROBLOX_GUIS[gui.Name] or gui.Name:sub(1,6)=="Roblox" then return end
                if gameGui and gui.Name:sub(1,1)~="@" then return end
                if gui:IsA("LayerCollector") or gui:IsA("Folder") then walk(gui,6000) end
            end)
            if total<=0 then break end
        end
    end
    return seen,found,gradients
end
-- ODH's own big buttons (in the shared storage, not ours or another add-on's usual one): the
-- gradients they show now
local function odhButtonGradients()
    local list={}
    local buttons={}
    for _,root in ipairs(guiRoots()) do
        pcall(function()
            local storageGui=root:FindFirstChild("@BBStorage")
            if not storageGui then return end
            for _,button in ipairs(storageGui:GetChildren()) do
                if not ours(button.Name) and button:IsA("GuiButton") then buttons[button]=true end
            end
        end)
    end
    for button in pairs(bigButtonsSeen) do
        if button.Parent then buttons[button]=true else bigButtonsSeen[button]=nil end
    end
    for button in pairs(buttons) do
        pcall(function()
            local stroke=button:FindFirstChildOfClass("UIStroke")
            local gradient=stroke and stroke:FindFirstChildOfClass("UIGradient") or button:FindFirstChildOfClass("UIGradient")
            if gradient then
                local colors=colorSet(gradient.Color)
                if colors.count>=1 and not sameColors(colors,TEMPLATE_SET) and not sameColors(colors,GOLD_SET) then
                    list[#list+1]={sequence=gradient.Color,colors=colors}
                end
            end
        end)
    end
    return list
end
-- the customization ODH saved as picked: a settings file of ODH's that names one of them
-- (looked through at most every 15 seconds)
local saved={at=-math.huge,pick=nil}
local function savedPick(themes)
    if os.clock()-saved.at<15 then
        for _,theme in ipairs(themes) do if theme.name==saved.pick then return theme end end
        return nil
    end
    saved.at=os.clock();saved.pick=nil
    local listFiles=type(listfiles)=="function" and listfiles or env.listfiles
    local readFile=type(readfile)=="function" and readfile or env.readfile
    local isFolder=type(isfolder)=="function" and isfolder or env.isfolder
    if type(listFiles)~="function" or type(readFile)~="function" then return nil end
    local found,checked={},0
    local function look(folder,depth)
        local ok,files=pcall(listFiles,folder)
        if not ok or type(files)~="table" then return end
        for _,path in ipairs(files) do
            checked=checked+1
            if checked>200 then return end
            local lower=type(path)=="string" and path:lower() or ""
            local okFolder,folderLike=false,false
            if type(isFolder)=="function" then okFolder,folderLike=pcall(isFolder,path) end
            if plainName(path):find("uicustomization",1,true) and lower:match("%.json$") then
                -- (the customizations themselves)
            elseif okFolder and folderLike==true then
                if depth<3 then look(path,depth+1) end
            elseif lower:match("%.json$") or lower:match("%.txt$") or lower:match("%.cfg$") or lower:match("%.ini$") or not lower:match("%.%w+$") then
                local okRead,text=pcall(readFile,path)
                if okRead and type(text)=="string" and #text<100000 then
                    for _,theme in ipairs(themes) do
                        local name=theme.name
                        if text==name or text:find('"'..name..'"',1,true) or text:find("'"..name.."'",1,true)
                            or text:find(name..".json",1,true) then
                            found[theme]=true
                        end
                    end
                end
            end
        end
    end
    look(themePlace.root or "Ixry Shizuka",0)
    local pick,count=nil,0
    for theme in pairs(found) do pick=theme;count=count+1 end
    if count==1 then saved.pick=pick.name;return pick end
    return nil
end
style.themeDiagnostics={}
-- (ODH's own things can show a customization's Secondary Variant or its Secondary)
local function shows(colors,theme) return sameColors(colors,theme.variantSet) or sameColors(colors,theme.secondarySet) end
local function pickTheme(themes)
    style.themeDiagnostics={themes=#themes,scores={}}
    -- (no customizations to pick from: ODH's own big buttons are still looked for, to copy)
    if #themes==0 then
        if next(bigButtonsSeen)==nil and os.clock()-(style.lookedAt or -math.huge)>15 then
            style.lookedAt=os.clock()
            menuColors()
        end
        return nil
    end
    local function only(matches)
        local pick,count=nil,0
        for theme in pairs(matches) do pick=theme;count=count+1 end
        return count==1 and pick or nil
    end
    -- (ODH's own big buttons showing one's colours)
    local fromButtons={}
    for _,candidate in ipairs(odhButtonGradients()) do
        for _,theme in ipairs(themes) do
            if shows(candidate.colors,theme) then fromButtons[theme]=true end
        end
    end
    local pick=only(fromButtons)
    if pick then style.themeDiagnostics.by="odh buttons";return pick end
    local seen,found,gradients=menuColors()
    style.themeDiagnostics.menuFound=found
    -- (a gradient in ODH's menu in one's colours)
    local hits={}
    local best,bestHits,tied=nil,0,false
    for _,theme in ipairs(themes) do
        local count=0
        for _,colors in ipairs(gradients) do if not bare(colors) and shows(colors,theme) then count=count+1 end end
        hits[theme]=count
        if count>bestHits then best,bestHits,tied=theme,count,false elseif count==bestHits and count>0 then tied=true end
    end
    if best and not tied then style.themeDiagnostics.by="menu gradients";return best end
    -- (the colours that tell one customization from the others)
    local shared={}
    for _,theme in ipairs(themes) do
        for hex in pairs(theme.colors) do shared[hex]=(shared[hex] or 0)+1 end
    end
    local tie=false
    best,bestHits=nil,0
    for _,theme in ipairs(themes) do
        local score=0
        for hex in pairs(theme.colors) do
            if seen[hex] and shared[hex]==1 and hex~="000000" and hex~="FFFFFF" then score=score+1 end
        end
        style.themeDiagnostics.scores[theme.name]=score
        if score>bestHits then best,bestHits,tie=theme,score,false
        elseif score==bestHits and score>0 then tie=true end
    end
    if best and bestHits>=2 and not tie then style.themeDiagnostics.by="menu";return best end
    -- (ODH's saved settings naming one)
    local fromFile=savedPick(themes)
    if fromFile then style.themeDiagnostics.by="settings file";return fromFile end
    if (tie or tied) and style.settings.name then
        for _,theme in ipairs(themes) do if theme.name==style.settings.name then return theme end end
    end
    -- (ODH's menu couldn't be seen at all and there's only the one customization: that one)
    if not found and #themes==1 then style.themeDiagnostics.by="only one";return themes[1] end
    return nil
end
local function restyleAll()
    for gradient,default in pairs(style.tracked) do
        if gradient.Parent then pcall(function() gradient.Color=style.Sequence(default) end) else style.tracked[gradient]=nil end
    end
    for _,listener in ipairs(style.listeners) do pcall(listener) end
end
local function sequenceKey(sequence)
    if typeof(sequence)~="ColorSequence" then return "" end
    local parts={}
    for _,point in ipairs(sequence.Keypoints) do parts[#parts+1]=string.format("%.3f:%s",point.Time,hexOf(point.Value)) end
    return table.concat(parts,",")
end
local theme=nil
local function apply()
    -- ODH's own big buttons showing the picked customization's Secondary Variant are copied
    -- exactly (the system's gradient as it shows); otherwise that customization's Secondary
    -- Variant, all three colours (with none picked, ODH's own big buttons as they show)
    local mirrored=nil
    local candidates=odhButtonGradients()
    for _,candidate in ipairs(candidates) do
        if theme and sameColors(candidate.colors,theme.gradientSet) then mirrored=candidate.sequence;break end
    end
    if not mirrored and not theme then
        for _,candidate in ipairs(candidates) do
            if not bare(candidate.colors) then mirrored=candidate.sequence;break end
        end
    end
    local gradient=mirrored or (theme and sequenceOf(theme.gradient)) or nil
    local signature=sequenceKey(gradient).."|"..tostring(theme and theme.name)
    if signature==style.settings.signature then return end
    style.settings={gradient=gradient,name=theme and theme.name or nil,mirrored=mirrored~=nil,signature=signature}
    restyleAll()
end
local function refreshTheme()
    local ok,themes=pcall(readThemes)
    if not ok then style.themeDiagnostics={error=tostring(themes)};return end
    theme=pickTheme(themes)
end
-- (ODH's own buttons are looked at every second, the customizations every 3 seconds, so a
-- change in Settings shows on ours straight away)
task.spawn(function()
    task.wait(1)
    local last=-math.huge
    while runtimeAlive do
        if os.clock()-last>=3 then last=os.clock();pcall(refreshTheme) end
        pcall(apply)
        task.wait(1)
    end
end)
-- the sequence a button shows: the custom one when it's on, else the Settings one, else the
-- button's usual one
function style.Sequence(default)
    if style.enabled then return style.Custom() end
    return style.settings.gradient or default or GRADIENT
end
-- (a gradient a little darker, for a bind button that's switched off)
function style.Dim(sequence)
    if typeof(sequence)~="ColorSequence" then return nil end
    local points={}
    for _,point in ipairs(sequence.Keypoints) do
        local color=point.Value
        points[#points+1]=ColorSequenceKeypoint.new(point.Time,Color3.new(color.R*0.6,color.G*0.6,color.B*0.6))
    end
    return ColorSequence.new(points)
end
-- a bind button's, matching the big buttons: switched on (or ready, for one that isn't
-- switched) exactly the big buttons' gradient (Settings' or your custom one), switched off the
-- same a little darker (with no customization picked and the custom gradient off: its usual
-- colours)
function style.BindSequence(active,default)
    local main=style.enabled and style.Custom() or style.settings.gradient
    if active then return main or default end
    return style.Dim(main) or default
end
function style.OnChange(listener) if type(listener)=="function" then style.listeners[#style.listeners+1]=listener end end
function style.Track(gradient,default)
    style.tracked[gradient]=default or GRADIENT
    pcall(function() gradient.Color=style.Sequence(default) end)
end
local function restyle() restyleAll() end
function style.SetEnabled(value)
    style.enabled=value==true;SetCfg("vv2BigButtonGradientEnabled",style.enabled);restyle()
end
function style.SetColor(index,color)
    if typeof(color)~="Color3" or not style.colors[index] then return end
    style.colors[index]=color;SetCfg("vv2BigButtonGradient"..index,color);restyle()
end
function style.Reset()
    style.enabled=false
    style.colors={Color3.fromRGB(20,20,20),Color3.fromRGB(20,20,140),Color3.fromRGB(120,40,120)}
    restyle()
end
runtime.BigButtonStyle=style
-- Hide Button Text (each section with buttons has one): the words on those buttons hidden,
-- kept so when a button is rebuilt
local textHidden={}
local textApplied=setmetatable({}, {__mode="k"})
local function applyText(button,hidden)
    local alpha=hidden and 1 or 0
    pcall(function()
        if button:IsA("TextButton") or button:IsA("TextLabel") then button.TextTransparency=alpha end
        local label=button:FindFirstChild("@Text")
        if label and label:IsA("TextLabel") then label.TextTransparency=alpha end
    end)
end
local function applyAllText()
    local roots={}
    local hidden=type(gethui)=="function" and gethui or env.gethui
    if type(hidden)=="function" then local ok,root=pcall(hidden);if ok and typeof(root)=="Instance" then roots[#roots+1]=root end end
    pcall(function() roots[#roots+1]=game:GetService("CoreGui") end)
    roots[#roots+1]=LocalPlayer:FindFirstChildOfClass("PlayerGui")
    for _,root in ipairs(roots) do
        pcall(function()
            for _,container in ipairs(root:GetChildren()) do
                if container.Name=="@BBStorage" or container.Name=="@bindstorage" then
                    for _,button in ipairs(container:GetChildren()) do
                        local wanted=textHidden[button.Name]
                        if wanted~=nil and textApplied[button]~=wanted then
                            textApplied[button]=wanted
                            applyText(button,wanted)
                        end
                    end
                end
            end
        end)
    end
end
runtime.ButtonText={
    SetHidden=function(ids,hidden)
        for _,id in ipairs(ids) do textHidden[id]=hidden==true end
        applyAllText()
    end,
    IsHidden=function(id) return textHidden[id]==true end,
}
task.spawn(function()
    while runtimeAlive do
        task.wait(0.3)
        if next(textHidden) then pcall(applyAllText) end
    end
end)
local STORAGE="@BBStorage"
local buttons={}
local spinner
local function roots()
    local list={}
    local function add(root)
        if typeof(root)~="Instance" then return end
        for _,existing in ipairs(list) do if existing==root then return end end
        list[#list+1]=root
    end
    local hidden=type(gethui)=="function" and gethui or env.gethui
    if type(hidden)=="function" then local ok,root=pcall(hidden);if ok then add(root) end end
    pcall(function() add(game:GetService("CoreGui")) end)
    add(LocalPlayer:FindFirstChildOfClass("PlayerGui"))
    return list
end
local function storage()
    local list=roots()
    local parent=list[1]
    if parent then
        local ok,existing=pcall(function() return parent:FindFirstChild(STORAGE) end)
        if ok and typeof(existing)=="Instance" and existing:IsA("LayerCollector") then return existing end
    end
    local gui=Instance.new("ScreenGui")
    gui.Name=STORAGE
    gui.ResetOnSpawn=false
    gui.IgnoreGuiInset=true
    pcall(function() gui.ScreenInsets=Enum.ScreenInsets.None end)
    if not (parent and pcall(function() gui.Parent=parent end) and gui.Parent) then
        gui.Parent=LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui")
    end
    return gui
end
-- (a copy left by an earlier run would sit on top of the new one and swallow presses)
local function removeStale(id,keep)
    for _,root in ipairs(roots()) do
        pcall(function()
            for _,container in ipairs(root:GetChildren()) do
                if container.Name==STORAGE then
                    for _,child in ipairs(container:GetChildren()) do
                        if child.Name==id and child~=keep then child:Destroy() end
                    end
                end
            end
        end)
    end
end
local function spin()
    if spinner then return end
    spinner=RunService.RenderStepped:Connect(function()
        if not runtimeAlive then spinner:Disconnect();spinner=nil;return end
        for _,record in pairs(buttons) do
            local gradient=record.gradient
            if gradient and record.button.Visible then gradient.Rotation=(gradient.Rotation+1)%360 end
        end
    end)
end
local function readPosition(key,fallback)
    local saved=key and C(key,nil)
    if type(saved)=="table" then
        local function n(value,default)
            value=tonumber(value)
            return value and value==value and value~=math.huge and value~=-math.huge and value or default
        end
        return UDim2.new(n(saved.xs or saved.XS,fallback.X.Scale),n(saved.xo or saved.XO,fallback.X.Offset),
            n(saved.ys or saved.YS,fallback.Y.Scale),n(saved.yo or saved.YO,fallback.Y.Offset))
    end
    return fallback
end
local function savePosition(key,position)
    if key then SetCfg(key,{xs=position.X.Scale,xo=position.X.Offset,ys=position.Y.Scale,yo=position.Y.Offset}) end
end
local function sizeOf(width)
    width=math.clamp(tonumber(width) or 140,50,300)
    return UDim2.fromOffset(width,width*0.375),math.max(9,math.floor(24*width/200+0.5))
end

runtime.BigButtons={}
-- options: text, onClick, isLocked (function), positionKey, default (UDim2), size (width)
function runtime.BigButtons.Create(id,options)
    local old=buttons[id]
    if old then old.Destroy() end
    local record={connections={},default=options.default or UDim2.new(0.5,0,0.5,0),positionKey=options.positionKey}
    local button=Instance.new("TextButton")
    button.Name=id
    button.AnchorPoint=Vector2.new(0.5,0.5)
    button.Position=readPosition(options.positionKey,record.default)
    button.BackgroundColor3=Color3.fromRGB(255,255,255)
    button.BackgroundTransparency=0.9
    button.BorderSizePixel=0
    button.Font=Enum.Font.Jura
    button.Text=tostring(options.text or "")
    button.TextColor3=Color3.fromRGB(255,255,255)
    button.TextWrapped=true
    button.ClipsDescendants=true
    button.AutoButtonColor=false
    button.ZIndex=5
    record.button=button
    record.width=math.clamp(tonumber(options.size) or 140,50,300)
    button.Size,button.TextSize=sizeOf(record.width)
    Instance.new("UICorner",button).CornerRadius=UDim.new(0,5)
    local stroke=Instance.new("UIStroke")
    stroke.Color=Color3.fromRGB(255,255,255)
    stroke.Thickness=1.5
    stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
    stroke.Parent=button
    local gradient=Instance.new("UIGradient")
    gradient.Parent=stroke
    style.Track(gradient,GRADIENT)
    record.gradient=gradient
    local ripple=Instance.new("Frame")
    ripple.Name="@ripple"
    ripple.BackgroundColor3=Color3.fromRGB(0,155,255)
    ripple.BackgroundTransparency=0.5
    ripple.ZIndex=4
    ripple.Size=UDim2.fromOffset(0,0)
    ripple.AnchorPoint=Vector2.new(0.5,0.5)
    ripple.Visible=false
    ripple.Parent=button
    Instance.new("UICorner",ripple).CornerRadius=UDim.new(1,0)
    local sound=Instance.new("Sound")
    sound.SoundId="rbxassetid://3868133279"
    ButtonAudio:Register(sound,0.5)
    sound.Parent=button

    local tweenInfo=TweenInfo.new(0.2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out)
    local pressInput,dragInput,dragStart,startPosition
    local moved=false
    local function locked() return type(options.isLocked)=="function" and options.isLocked()==true end
    local function sameInput(input)
        if not pressInput then return false end
        if input==pressInput then return true end
        -- (a mouse press ends with a new input object; a touch keeps its own)
        return pressInput.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1
    end
    table.insert(record.connections,button.InputBegan:Connect(function(input)
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        if pressInput then return end
        pressInput=input;moved=false;dragStart=input.Position;startPosition=button.Position
        local size,textSize=sizeOf(record.width*1.1)
        TweenService:Create(button,tweenInfo,{Size=size,TextSize=textSize}):Play()
        local corner=button.AbsolutePosition
        ripple.Position=UDim2.fromOffset(input.Position.X-corner.X,input.Position.Y-corner.Y)
        ripple.Size=UDim2.fromOffset(0,0);ripple.BackgroundTransparency=0.5;ripple.Visible=true
        pcall(function() sound:Play() end)
        TweenService:Create(ripple,TweenInfo.new(0.5,Enum.EasingStyle.Sine,Enum.EasingDirection.Out),
            {Size=UDim2.fromOffset(300,300),BackgroundTransparency=1}):Play()
    end))
    table.insert(record.connections,button.InputChanged:Connect(function(input)
        if input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch then dragInput=input end
    end))
    table.insert(record.connections,UserInputService.InputChanged:Connect(function(input)
        if not pressInput or (input~=dragInput and input~=pressInput) or locked() then return end
        local delta=input.Position-dragStart
        if delta.Magnitude>7 then moved=true end
        if moved then
            button.Position=UDim2.new(startPosition.X.Scale,startPosition.X.Offset+delta.X,startPosition.Y.Scale,startPosition.Y.Offset+delta.Y)
        end
    end))
    table.insert(record.connections,UserInputService.InputEnded:Connect(function(input)
        if not sameInput(input) then return end
        pressInput=nil
        local size,textSize=sizeOf(record.width)
        TweenService:Create(button,tweenInfo,{Size=size,TextSize=textSize}):Play()
        if moved and not locked() then
            savePosition(record.positionKey,button.Position)
        elseif not moved and button.Visible and type(options.onClick)=="function" then
            task.spawn(function()
                local ok,err=pcall(options.onClick)
                if not ok then warn("[Visuals V2] "..id..": "..tostring(err)) end
            end)
        end
    end))
    button.Parent=storage()
    removeStale(id,button)
    function record.SetText(text) button.Text=tostring(text or "") end
    function record.SetSize(width)
        record.width=math.clamp(tonumber(width) or record.width,50,300)
        if not pressInput then button.Size,button.TextSize=sizeOf(record.width) end
    end
    function record.SetVisible(value) button.Visible=value==true;if not button.Visible then pressInput=nil end end
    function record.ResetPosition()
        button.Position=record.default
        savePosition(record.positionKey,record.default)
    end
    function record.Alive() return button.Parent~=nil and buttons[id]==record end
    function record.Destroy()
        for _,connection in ipairs(record.connections) do pcall(function() connection:Disconnect() end) end
        table.clear(record.connections)
        pcall(function() button:Destroy() end)
        if buttons[id]==record then buttons[id]=nil end
    end
    buttons[id]=record
    spin()
    return record
end
runtime.RegisterReset(function()
    if runtimeAlive then return end
    for _,record in pairs(buttons) do pcall(record.Destroy) end
end)
