vv2Features.GetDiagnostics=function()
    local result={alive=alive,runtimeAlive=runtimeAlive,lastFailure=lastFailure,
        lastJumpAgo=lastJumpAt and math.floor((os.clock()-lastJumpAt)*10)/10 or nil,buttons={}}
    if vv2Features.State then
        local ok,state=pcall(vv2Features.State)
        if ok then result.state=state end
    end
    for id,spec in pairs(buttonSpecs) do
        local button=liveButton(id)
        local info={wanted=spec.wanted,live=button~=nil,built=spec.built or 0,error=spec.error}
        if button then pcall(function() info.path=button:GetFullName();info.visible=button.Visible end) end
        result.buttons[id]=info
    end
    return result
end

-- build the saved buttons now, then keep them in place
vv2Spawn(function()
    for id in pairs(buttonSpecs) do pcall(ensureButton,id) end
    while alive and runtimeAlive do
        task.wait(1)
        for id in pairs(buttonSpecs) do pcall(ensureButton,id) end
    end
end)

vv2Features.Close=function()
    if not alive then return end
    alive=false
    for record in pairs(pending) do
        if record.thread and type(task.cancel)=="function" then pcall(task.cancel,record.thread) end
        pending[record]=nil
    end
    -- every step is protected so one failing control can't leave old buttons behind
    for _,controller in ipairs(vv2Controls) do pcall(function() controller:Set(false) end) end
    for id in pairs(buttonSpecs) do pcall(removeButton,id) end
    for id in pairs(BBSystem.Buttons) do pcall(DeleteBigButton,id) end
    for id in pairs(BindableButtons.Buttons) do pcall(BindableButtons.DeleteBButton,id) end
    pcall(function() RootMaid:Destroy() end)
end
runtime.VV2BombJump=vv2Features
runtime.RegisterReset(function()
    if runtimeAlive then
        -- the settings file was reset: switch Bomb Jump's options off but keep it working
        for _,controller in ipairs(vv2Controls) do pcall(function() controller:Set(false) end) end
        for id,spec in pairs(buttonSpecs) do spec.wanted=false; pcall(removeButton,id) end
        for _,hook in ipairs(resetHooks) do pcall(hook) end
        table.clear(savedPositions)
        return
    end
    vv2Features.Close()
end)
end,"Section \"Bomb Jump Clutch / Gold Bomb Jump+\"")

;vv2Section(function()
-- Bomb Fling (Fun Bomb by lzzzx, reworked): flings players with your deployed Fake Bomb.
-- Changes from Fun Bomb:
--  * no freeze when a fling starts: bombs are tracked as they appear instead of searching
--    the whole map (several times a second) for them
--  * a bomb is only deployed when there is none, one request at a time, with a growing
--    wait after a failed try, so the toy isn't equipped and unequipped over and over
--  * "no bomb" is only reported after deploying one really failed
--  * the bomb is thrown the way the game itself throws it (its Remote told where: at your
--    feet, and 50, as the game's own toy and Bomb Jump send it; Fun Bomb's empty throw never
--    made one) the way it will end up nearest you (see throwWay), checked to be yours, and
--    carried along just under you between flings so it stays yours (see CARRY_DEPTH); one given
--    to someone else is replaced by a new one taken out, once the toy can be thrown again
--  * the bomb goes on them the way Reset Player (aux0on) puts you on them: every frame after
--    the physics step, touched against them. It's laid flat, biggest face down, and works its
--    way slowly from just above their head down to their feet, over and over, sent down at full
--    power and spinning about the upright. (Reset Player's other trick, setting the bomb's
--    physics replication root to theirs, stopped it flinging at all.)
--  * moving players: the bomb rides along a little ahead of where you see them (see
--    LEAD_TRIES), round their turn, through their weaving and up where hoppers are (see
--    predictAhead, HOP_MARGIN); standing ones have it right on them
--  * the Fake Bomb can only be thrown every 22 s (Bomb Jump's throws count too): while it can't,
--    you're told how long is left instead of a throw that puts out nothing
local runtime=env.VisualsV2Runtime
local ReplicatedStorage=game:GetService("ReplicatedStorage")
local section=mainTab:AddSection("Bomb Fling","Utilities")
local POWER=50000
local MIN_DURATION,MAX_DURATION=1,4
local LOOP_DELAY=2.5
local settings={
    duration=math.clamp(tonumber(C("bombFlingDuration",MIN_DURATION)) or MIN_DURATION,MIN_DURATION,MAX_DURATION),
    auraDistance=math.clamp(tonumber(C("bombFlingAuraStuds",15)) or 15,5,50),
}
local selectedPlayers,whitelist={},{}
local loops={}
local alive=true
local stats={deploys=0,deployFailures=0,flings=0,hits=0,lastError=nil}

local function notify(text,seconds) pcall(shared.Notify,text,seconds or 2) end
-- Fling report: what happens in each fling, to work out what to change. Lines are stamped with
-- the server's clock (the same on every player's screen, so they line up with the test target
-- logger run on another account), the last REPORT_LINES are kept, and Copy Fling Report copies
-- them (and saves them to a file).
local REPORT_LINES=2000
local reportLines,reportNames={},{}
local function serverTime()
    local ok,value=pcall(function() return workspace:GetServerTimeNow() end)
    return ok and tonumber(value) or os.clock()
end
local function note(text)
    reportLines[#reportLines+1]=("%.3f %s"):format(serverTime()%1000,text)
    if #reportLines>REPORT_LINES then table.remove(reportLines,1) end
end
-- (players by number, not by name)
local function reportName(plr)
    if not reportNames[plr] then
        local count=0
        for _ in pairs(reportNames) do count=count+1 end
        reportNames[plr]="P"..(count+1)
    end
    return reportNames[plr]
end
local function receiveAge(part)
    local ok,age=pcall(function() return part.ReceiveAge end)
    return ok and tonumber(age) or -1
end
local function isWhitelisted(plr) return whitelist[plr.UserId]==true end
local function rootOf(plr)
    local character=plr and plr.Character
    return character and (character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Torso") or character:FindFirstChild("Head"))
end
local function aliveCharacter(plr)
    local character=plr and plr.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    return humanoid and humanoid.Health>0 and character or nil
end

-- roles: tools first (instant), then the game's own player data, fetched in the background
local roleData,roleFetchedAt,roleFetching=nil,-math.huge,false
local function refreshRoles()
    if roleFetching or os.clock()-roleFetchedAt<3 then return end
    roleFetching=true
    task.spawn(function()
        local ok,result=pcall(function()
            local remote=ReplicatedStorage:FindFirstChild("GetPlayerData",true)
            if remote and remote:IsA("RemoteFunction") then return remote:InvokeServer() end
        end)
        if ok and type(result)=="table" then roleData=result end
        roleFetchedAt=os.clock();roleFetching=false
    end)
end
local function hasTool(plr,word)
    for _,container in ipairs({plr.Character,plr:FindFirstChildOfClass("Backpack")}) do
        if container then
            for _,tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and tool.Name:lower():find(word,1,true) then return true end
            end
        end
    end
    return false
end
local function byRole(roles,word)
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LocalPlayer and not isWhitelisted(plr) and aliveCharacter(plr) and hasTool(plr,word) then return plr end
    end
    refreshRoles()
    if type(roleData)=="table" then
        for name,info in pairs(roleData) do
            if type(info)=="table" and roles[info.Role] and not info.Killed and not info.Dead then
                local plr=Players:FindFirstChild(tostring(name))
                if plr and plr~=LocalPlayer and not isWhitelisted(plr) and aliveCharacter(plr) then return plr end
            end
        end
    end
end
local function findMurderer() return byRole({Murderer=true},"knife") end
local function findSheriff() return byRole({Sheriff=true,Hero=true},"gun") end

-- ---------------------------------------------------------------- bombs
local bombs={}
local ownBomb=nil
local lastDeploy={at=-math.huge,position=nil}
local function inCharacterOrTool(object)
    local current=object.Parent
    for _=1,8 do
        if not current or current==workspace then return false end
        if current:IsA("Tool") or current:IsA("Accessory") or current:FindFirstChildOfClass("Humanoid") then return true end
        current=current.Parent
    end
    return false
end
-- (what Fun Bomb counts as a thrown bomb: FakeBomb by its name or its model's, or a loose
-- Handle that isn't part of anyone's character, tool or hat)
local function bombLike(part)
    if not part:IsA("BasePart") or part.Anchored then return false end
    local name=part.Name:lower()
    local parent=part.Parent
    local parentName=parent and parent.Name:lower() or ""
    if not (name:find("fakebomb",1,true) or parentName:find("fakebomb",1,true) or name=="bomb" or parentName=="bomb"
        or name=="handle") then return false end
    return not inCharacterOrTool(part)
end
-- (a bomb counts as fallen out of the world only right at the map's own fall limit: it had to be
-- 25 studs above it, so on maps built close to that limit every bomb counted as gone). With no
-- real limit (anti-void scripts, ODH's among them, set it to NaN or -inf) there's nothing to fall
-- out of: a NaN limit made every bomb count as gone, so none thrown was ever kept.
local function fallLimit()
    local ok,limit=pcall(function() return workspace.FallenPartsDestroyHeight end)
    if not ok or type(limit)~="number" or limit~=limit or math.abs(limit)==math.huge then return nil end
    return limit
end
local function unusableWhy(part)
    if not part or not part.Parent then return "it was removed" end
    if not part:IsDescendantOf(workspace) then return "it was moved out of the map" end
    if part.Anchored then return "it's anchored" end
    local ok,y=pcall(function() return part.Position.Y end)
    if not ok or y~=y then return "its position can't be read" end
    local limit=fallLimit()
    if limit and y<=limit+2 then return ("it's at the map's fall limit (height %d, limit %d)"):format(math.floor(y),math.floor(limit)) end
    return nil
end
local function usable(part)
    return unusableWhy(part)==nil
end
local function owned(part)
    -- 0 means this client is simulating the part (it's ours to move)
    local ok,age=pcall(function() return part.ReceiveAge end)
    return not ok or age==0
end
local function consider(part)
    if bombs[part] or not bombLike(part) then return end
    bombs[part]=os.clock()
    -- the first new bomb right where we just deployed one is ours
    if lastDeploy.position and os.clock()-lastDeploy.at<2.5 and (not ownBomb or not usable(ownBomb)) then
        local ok,distance=pcall(function() return (part.Position-lastDeploy.position).Magnitude end)
        if ok and distance<45 then ownBomb=part end
    end
end
local watch=workspace.DescendantAdded:Connect(function(object)
    if alive and object:IsA("BasePart") then task.defer(consider,object) end
end)
local unwatch=workspace.DescendantRemoving:Connect(function(object)
    if bombs[object] then bombs[object]=nil end
    if object==ownBomb then
        ownBomb=nil
        note(("BOMB gone (it went off), %.0f s after the last throw"):format(os.clock()-lastDeploy.at))
    end
end)
-- (bombs already out when the add-on starts: one pass, a slice per frame)
task.spawn(function()
    local ok,list=pcall(workspace.GetDescendants,workspace)
    if not ok then return end
    local started=os.clock()
    for index,object in ipairs(list) do
        if not alive then return end
        if object:IsA("BasePart") then consider(object) end
        if index%300==0 and os.clock()-started>0.003 then task.wait();started=os.clock() end
    end
end)
-- The Fake Bomb the game has just thrown, found however it turns up: the toy's own Handle
-- copied out into the map (the same size, with the toy's Fuse / Beep sounds and smoke inside
-- it), or anything named like a bomb. From just before a throw, everything that turns up near
-- you is looked at (and looked at again as it settles), and so is everything loose in the map
-- near you that wasn't there before the throw. Shared with Firefly Protection's particle helper.
local recentParts={}
local recentWatch=workspace.DescendantAdded:Connect(function(object)
    if alive and object:IsA("BasePart") then recentParts[object]=os.clock() end
end)
local function bombSignature(tool)
    local signature={names={},size=nil}
    local handle=tool and tool:FindFirstChild("Handle")
    if handle and handle:IsA("BasePart") then
        signature.size=handle.Size
        for _,child in ipairs(handle:GetChildren()) do signature.names[child.Name]=true end
    end
    return signature
end
local function bombScore(part,signature)
    local score=0
    pcall(function()
        local name=part.Name:lower()
        local parentName=part.Parent and part.Parent~=workspace and part.Parent.Name:lower() or ""
        if name:find("bomb",1,true) or parentName:find("bomb",1,true) then score=score+2 end
        if name=="handle" then score=score+1 end
        if signature and signature.size and (part.Size-signature.size).Magnitude<0.2 then score=score+3 end
        local shared=0
        for _,child in ipairs(part:GetChildren()) do
            if signature and signature.names[child.Name] then shared=shared+1 end
        end
        if shared>=2 then score=score+3 end
        if part:FindFirstChild("Fuse") or part:FindFirstChild("Beep") then score=score+2 end
        if not part.Anchored then score=score+1 end
    end)
    return score
end
local function describePart(part,score)
    local ok,text=pcall(function()
        local size=part.Size
        return ("%s %.1fx%.1fx%.1f%s (%d)"):format(part.Name,size.X,size.Y,size.Z,part.Anchored and " fixed" or "",score)
    end)
    return ok and text or "?"
end
local ThrownBomb={lastSeen=nil}
-- (just before throwing: what's already out there, and what the toy looks like)
function ThrownBomb.Begin(tool,from)
    local before={}
    for _,child in ipairs(workspace:GetChildren()) do before[child]=true end
    for part in pairs(recentParts) do if os.clock()-recentParts[part]>5 then recentParts[part]=nil end end
    return {before=before,signature=bombSignature(tool),from=from,at=os.clock()}
end
-- (the best new candidate near where it was thrown or near you, or nil)
function ThrownBomb.Find(watch,radius)
    radius=radius or 35
    local mine=rootOf(LocalPlayer)
    local best,bestScore=nil,2
    local seen={}
    local function look(part)
        if seen[part] or (watch.skip and watch.skip[part]) or not part.Parent or not part:IsDescendantOf(workspace) or inCharacterOrTool(part) then return end
        seen[part]=true
        local ok,position=pcall(function() return part.Position end)
        if not ok then return end
        local near=(watch.from and (position-watch.from).Magnitude<radius) or (mine and (position-mine.Position).Magnitude<radius)
        if not near then return end
        local score=bombScore(part,watch.signature)
        watch.seen=watch.seen or {}
        if score>=1 and #watch.seen<4 then watch.seen[#watch.seen+1]=describePart(part,score) end
        if score>bestScore then best,bestScore=part,score end
    end
    for part,at in pairs(recentParts) do
        if at>=watch.at-0.05 then look(part) end
    end
    for _,child in ipairs(workspace:GetChildren()) do
        if not watch.before[child] then
            if child:IsA("BasePart") then look(child)
            elseif child:IsA("Model") or child:IsA("Folder") or child:IsA("Tool") then
                for _,inner in ipairs(child:GetDescendants()) do if inner:IsA("BasePart") then look(inner) end end
            end
        end
    end
    ThrownBomb.lastSeen=watch.seen and table.concat(watch.seen,", ") or "nothing new near you"
    return best
end
ThrownBomb.Score=bombScore
ThrownBomb.Signature=bombSignature
local function nearestOwnedBomb(anyOwner,within,signature)
    local root=rootOf(LocalPlayer)
    if not root then return nil end
    local best,bestDistance=nil,within or 60
    for part in pairs(bombs) do
        if usable(part) and (anyOwner or owned(part)) and (not signature or bombScore(part,signature)>=3) then
            local distance=(part.Position-root.Position).Magnitude
            if distance<bestDistance then best,bestDistance=part,distance end
        elseif not part.Parent then bombs[part]=nil end
    end
    return best
end

local function findBombTool()
    for _,container in ipairs({LocalPlayer.Character,LocalPlayer:FindFirstChildOfClass("Backpack")}) do
        if container then
            for _,tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and tool.Name:lower():gsub("%s","")=="fakebomb" then return tool end
            end
        end
    end
end
local function toyRemote()
    local remotes=ReplicatedStorage:FindFirstChild("Remotes")
    local extras=remotes and remotes:FindFirstChild("Extras")
    local remote=extras and extras:FindFirstChild("ReplicateToy")
    return remote and remote:IsA("RemoteFunction") and remote or nil
end

-- (the game lets the Fake Bomb be thrown once every 22 s, as Bomb Jump counts it; a throw before
-- then puts out nothing)
local THROW_COOLDOWN=22
local throwReadyAt=0
local function cooldownLeft()
    local left=throwReadyAt-os.clock()
    local bombJump=runtime.VV2BombJump
    if bombJump and type(bombJump.State)=="function" then
        local ok,state=pcall(bombJump.State)
        if ok and type(state)=="table" and tonumber(state.cooldownLeft) then left=math.max(left,tonumber(state.cooldownLeft)) end
    end
    return math.max(0,left)
end
local deploying=false
local backoffUntil,failures=0,0
local function failDeploy(reason)
    failures=failures+1
    stats.deployFailures=stats.deployFailures+1
    stats.lastError=reason
    backoffUntil=os.clock()+math.min(8,0.75*2^(failures-1))
    note("TAKEOUT failed: "..tostring(reason))
    return nil,reason
end
-- Takes out a Fake Bomb (thrown just in front of you) and waits until it turns up. One at a
-- time; a failure waits longer before the next try.
-- (how far the nearest other player is from a spot)
local function nearestOther(position)
    local nearest=math.huge
    for _,plr in ipairs(Players:GetPlayers()) do
        local root=plr~=LocalPlayer and rootOf(plr)
        if root then nearest=math.min(nearest,(root.Position-position).Magnitude) end
    end
    return nearest
end
-- The way to throw it so it ends up nearest you. The game throws the Fake Bomb the way you face
-- (where it's told to throw it hardly matters), and it flies and rolls some 20 studs or more
-- before it stops; it's then given to whoever it's nearest. Thrown the way you faced the player
-- about to be flung, it went to them. So of eight ways round you, the one where it stops (at a
-- wall, or some 20 studs out) furthest from everyone else for how far it is from you.
local THROW_REACH=22
local function throwWay(from)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignore={}
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr.Character then ignore[#ignore+1]=plr.Character end
    end
    params.FilterDescendantsInstances=ignore
    local best,bestScore=Vector3.new(0,0,-1),-math.huge
    for step=0,7 do
        local angle=step*math.pi/4
        local way=Vector3.new(math.cos(angle),0,math.sin(angle))
        local reach=THROW_REACH
        local ok,hit=pcall(function() return workspace:Raycast(from,way*reach,params) end)
        if ok and hit then reach=math.max(0,(hit.Position-from).Magnitude-1) end
        local score=math.min(nearestOther(from+way*reach),200)-reach
        if score>bestScore then best,bestScore=way,score end
    end
    return best
end
local function deployBomb()
    if deploying then
        local deadline=os.clock()+3
        while deploying and os.clock()<deadline do task.wait(0.05) end
        if ownBomb and usable(ownBomb) then return ownBomb end
        return nil,stats.lastError or "the bomb is still being deployed"
    end
    if os.clock()<backoffUntil then return nil,stats.lastError or "waiting before trying again" end
    local waitLeft=cooldownLeft()
    if waitLeft>0.05 then return nil,("the Fake Bomb can be thrown again in %d s"):format(math.ceil(waitLeft)) end
    local character=aliveCharacter(LocalPlayer)
    local root=rootOf(LocalPlayer)
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    if not character or not root or not humanoid then return nil,"you are not alive" end
    deploying=true
    local result,reason
    local ok,err=pcall(function()
        local tool=findBombTool()
        if not tool then
            local remote=toyRemote()
            if remote then pcall(function() remote:InvokeServer("FakeBomb") end) end
            local deadline=os.clock()+1.5
            repeat task.wait(0.05);tool=findBombTool() until tool or os.clock()>deadline
        end
        if not tool then result,reason=failDeploy("you don't have the Fake Bomb toy");return end
        local throw=tool:FindFirstChild("Remote")
        if not (throw and throw:IsA("RemoteEvent")) then throw=tool:FindFirstChildWhichIsA("RemoteEvent",true) end
        if not throw then result,reason=failDeploy("the Fake Bomb has no Remote");return end
        local backpack=LocalPlayer:FindFirstChildOfClass("Backpack")
        local held=character:FindFirstChildOfClass("Tool")
        if held==tool then held=nil end
        -- (thrown the way it ends up nearest you: see throwWay. You're turned that way for the
        -- throw, a tenth of a second, then back.)
        local way=throwWay(root.Position)
        local position=root.Position+way*4-Vector3.new(0,3,0)
        lastDeploy.at,lastDeploy.position=os.clock(),position
        stats.deploys=stats.deploys+1
        note(("TAKEOUT thrown, nearest other player %.0f studs from where it should stop"):format(nearestOther(root.Position+way*THROW_REACH)))
        local thrownWatch=ThrownBomb.Begin(tool,position)
        local facing=root.CFrame-root.CFrame.Position
        local autoRotate=humanoid.AutoRotate
        pcall(function()
            humanoid.AutoRotate=false
            root.CFrame=CFrame.lookAt(root.Position,root.Position+way)
        end)
        -- in hand (as long as Bomb Jump keeps it there, or until the bomb shows up), thrown the
        -- way the game throws it, then back with what you held back in your hand
        pcall(function() tool.Parent=character end)
        task.wait(0.1)
        pcall(function() throw:FireServer(CFrame.lookAt(position,position+way),50) end)
        local inHand=os.clock()+0.5
        repeat task.wait(0.03) until (ownBomb and usable(ownBomb)) or os.clock()>inHand
        pcall(function()
            if root.Parent then root.CFrame=CFrame.new(root.Position)*facing end
            humanoid.AutoRotate=autoRotate
        end)
        pcall(function() if tool.Parent==character then tool.Parent=backpack or tool.Parent end end)
        if held and held.Parent and held.Parent~=character then pcall(function() humanoid:EquipTool(held) end) end
        -- (and Increase Inventory's Auto Get Tools puts your toys back in their slots)
        local tools=runtime.AutoGetTools
        if tools and type(tools.RequestOrder)=="function" then pcall(tools.RequestOrder) end
        local deadline=os.clock()+3
        -- (one that was found but couldn't be kept, and why, for the notice)
        local passedOver=nil
        repeat
            if not (ownBomb and usable(ownBomb)) then
                local found=ThrownBomb.Find(thrownWatch)
                if found and usable(found) then ownBomb=found;bombs[found]=bombs[found] or os.clock()
                elseif found then passedOver=describePart(found,bombScore(found,thrownWatch.signature)).." was passed over: "..tostring(unusableWhy(found)) end
            end
            if ownBomb and usable(ownBomb) then break end
            task.wait(0.05)
        until os.clock()>deadline
        if not (ownBomb and usable(ownBomb)) then
            local found=nearestOwnedBomb()
            if found then ownBomb=found end
        end
        if not (ownBomb and usable(ownBomb)) then
            -- (what was near you goes in the diagnostics, not the notice)
            stats.lastSeen=tostring(ThrownBomb.lastSeen)..(passedOver and ("; "..passedOver) or "")
            result,reason=failDeploy("the throw put out no bomb (the Fake Bomb may still be on its 22 s cooldown)");return
        end
        throwReadyAt=lastDeploy.at+THROW_COOLDOWN
        failures=0
        note(("TAKEOUT got %s %.0f studs from you, ra=%.2f"):format(describePart(ownBomb,bombScore(ownBomb,thrownWatch.signature)),
            (ownBomb.Position-root.Position).Magnitude,receiveAge(ownBomb)))
        result=ownBomb
    end)
    deploying=false
    if not ok then return failDeploy(tostring(err)) end
    return result,reason
end
local function getBomb()
    if ownBomb and usable(ownBomb) then return ownBomb end
    -- (the one Firefly Protection keeps out as a particle helper: Bomb Fling comes first)
    local protection=runtime.FireflyProtection
    if protection and type(protection.CurrentBomb)=="function" then
        local ok,shared=pcall(protection.CurrentBomb)
        if ok and typeof(shared)=="Instance" and usable(shared) then ownBomb=shared;bombs[shared]=bombs[shared] or os.clock();return shared end
    end
    local found=nearestOwnedBomb()
    if found then ownBomb=found;return found end
    -- (a Fake Bomb lying right by you that the game hasn't handed you yet, like one just
    -- thrown: it soon will)
    found=nearestOwnedBomb(true,20,bombSignature(findBombTool()))
    if found then ownBomb=found;return found end
    return deployBomb()
end

-- ---------------------------------------------------------------- flinging
local flingQueue={}
local flinging=false
local lastMissingNotice=-math.huge
-- (touched against their root and head every frame, as Reset Player (aux0on) does, so the hit
-- registers straight away; but not for the first TOUCH_DELAY seconds of a fling, or of a new bomb
-- in one. In the test logs about one fling in 25 lost its bomb a quarter of a second in, always
-- right at the start, the game removing it before it had even reached the target's screen; a
-- touch told to the game while it still has the bomb lying by you may be what does it)
local TOUCH_DELAY=0.2
local touchInterest=firetouchinterest or env.firetouchinterest
local function touch(a,b)
    if type(touchInterest)~="function" or not (a and b) then return end
    pcall(touchInterest,a,b,0)
    pcall(touchInterest,a,b,1)
end
-- (their speed from where they've been over the last quarter second: the speed the game sends
-- for a flung player can read 0)
local function measure(track,position,now)
    track[#track+1]={at=now,position=position}
    while #track>2 and now-track[2].at>=0.25 do table.remove(track,1) end
    local first=track[1]
    return now-first.at>=0.05 and (position-first.position)/(now-first.at) or Vector3.zero
end
-- Where a moving player will be, from their last second (PATH_TIME): round the arc if they're
-- turning steadily one way, as round a circle; if they're weaving, halfway between straight on
-- and the middle of where they've been heading; otherwise straight on. Tried in simulation on
-- straight runs, circles, zig-zags and random turns, with the lead 0.12 s out either way and their
-- position jittering 0.2 studs, they were touched 1.1 s in on average with 4% not touched in 4 s.
-- Following every turn as if it went on (as the test before this did) took 3.3 s, with 62% not
-- touched: a zig-zag's turn carried on for half a second throws the bomb 6 to 8 studs to one
-- side, as the test target's log showed. Round the arc goes at most ARC_LIMIT radians: someone
-- circling at 3 to 4 radians a second (as the test target did) turns further than the 1.4 it used
-- to be in the time the bomb is ahead, and the bomb lagged behind them round the circle; at 2.2,
-- simulation touched a 4 radians a second circle in about a second, and did no worse on straight
-- runs, zig-zags or random turns. (Weaving was led three quarters of the way along to straight on
-- for one test, a replay of the logs having promised it on them 18% of the time against 11%; on
-- the target's screen it moved half a stud and was on them no more often, so it's back halfway,
-- as simulation prefers.)
local PATH_TIME=1
local ARC_LIMIT=2.2
-- Every other player's last MOTION_TIME seconds (where they were, which way they were going and
-- how fast they were rising), kept all the time for the ones within FAR_AWAY studs, so a fling
-- knows from its start whether they're weaving, turning or hopping (or still flying from the last
-- fling) instead of finding out a second in.
local MOTION_TIME=1.5
-- (further off than this, someone isn't on the map with you: flung off it, or in the lobby)
local FAR_AWAY=1000
local motion={}
-- (when each player's present character turned up, for the report: a bomb has gone a third of a
-- second into a fling right after someone was flung, and they may have just come back)
local born={}
local tracker=RunService.Heartbeat:Connect(function()
    if not alive or not runtimeAlive then return end
    local now=os.clock()
    local mine=rootOf(LocalPlayer)
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LocalPlayer then
            local root=rootOf(plr)
            if root and (not born[plr] or born[plr].root~=root) then born[plr]={root=root,at=now} end
            local list=motion[plr]
            if root and root.Parent and (not mine or (root.Position-mine.Position).Magnitude<FAR_AWAY) then
                if not list or list.root~=root then list={root=root};motion[plr]=list end
                local position,velocity=root.Position,root.AssemblyLinearVelocity
                -- (rising speed: the one the game sends, or from where they were a tenth of a
                -- second ago when that reads 0)
                local rise=velocity.Y
                if math.abs(rise)<1 then
                    for index=#list,1,-1 do
                        local entry=list[index]
                        if now-entry.at>=0.1 then rise=(position.Y-entry.position.Y)/(now-entry.at);break end
                    end
                end
                list[#list+1]={at=now,position=position,velocity=Vector3.new(velocity.X,0,velocity.Z),rise=rise}
                while #list>1 and now-list[1].at>MOTION_TIME do table.remove(list,1) end
            elseif list then
                motion[plr]=nil
            end
        end
    end
end)
local leaving=Players.PlayerRemoving:Connect(function(plr) motion[plr]=nil;born[plr]=nil end)
-- (how they've really moved over the last moment, by the tracker: the speed the game sends for a
-- flung player can read 0)
local function movedVelocity(history,now)
    local last=history and history[#history]
    if not last or now-last.at>0.1 then return Vector3.zero end
    for index=#history-1,1,-1 do
        local entry=history[index]
        if last.at-entry.at>=0.15 then return (last.position-entry.position)/(last.at-entry.at) end
    end
    return Vector3.zero
end
-- (faster than anyone runs or falls, as a fling tells someone's been flung: see flungNow)
local function flying(velocity)
    return velocity.Magnitude>100 or Vector3.new(velocity.X,0,velocity.Z).Magnitude>45
end
-- Hopping: two take-offs or more (starting to rise faster than HOP_RISE) in the last 1.5 s. A
-- hopper is mostly in the air, so the bomb isn't put where they'd land (as for one jump: the test
-- logs showed it 3 to 6 studs under them then) but kept at one height, just over their soles at
-- the top of a jump (HOP_MARGIN clear, sweeping HOP_SWEEP either way; how high a jump goes is
-- their Humanoid's), so every hop brings their head and body up into it as it's sent down. Lower,
-- at their chest as they stand (as it was), the top of each hop took their feet over it and they
-- came down onto it: sent down, a bomb under their feet holds them up like a step, and the test
-- target hopped on it again and again. Kept clear of their feet, no hop landed on it in
-- simulation and it was in a hopper's body 49 to 77% of the time (a sweep from over their head
-- down to over their feet, "crashing down" on them, was in it only 35 to 59% of the time, and
-- landed under them just the same with their floor taken too low); someone who jumps now and then
-- is still followed along their jump. Where their root stands is the higher of where it last was
-- when they landed (the lowest it's been in the last HOP_LANDED seconds) and over the floor right
-- under them: each alone has been too low, and too low the bomb is back under their feet. The
-- lowest of a whole second lagged behind someone hopping up onto higher ground (the test target
-- landed on it again, the bomb 3 to 10 studs under them); the floor found under them was once 5 to
-- 6 studs too low for a whole fling; and someone hopping in place can look to land 4 to 5 studs
-- lower than they do (twice, your screen and theirs agreed on the top of each hop but not the
-- bottom; running hoppers' landings agreed), so for them it's never taken lower than the top of
-- their hop less what a jump rises.
local HOP_RISE=20
local HOP_MARGIN=0.5
local HOP_SWEEP=0.5
local HOP_LANDED=0.6
-- (how high a jump takes them when their Humanoid can't be read: Roblox's own)
local HOP_JUMP=7.2
local function hopping(history,now)
    local count,below=0,false
    for _,entry in ipairs(history) do
        if now-entry.at<=1.5 then
            if entry.rise>=HOP_RISE then
                if below then count=count+1 end
                below=false
            else
                below=true
            end
        end
    end
    return count>=2
end
-- (the height their root stands at: the lowest it's been in the last HOP_LANDED seconds, but,
-- given what a jump rises, never lower than the top of their hop less that; or nil)
local function standingHeight(history,now,rise)
    local lowest,highest=nil,nil
    for _,entry in ipairs(history) do
        if now-entry.at<=HOP_LANDED then
            local y=entry.position.Y
            lowest,highest=math.min(lowest or y,y),math.max(highest or y,y)
        end
    end
    if lowest and rise then return math.max(lowest,highest-rise) end
    return lowest
end
-- (how high a jump takes their root, from their Humanoid's settings, or nil)
local function jumpRise(character)
    local ok,rise=pcall(function()
        local humanoid=character:FindFirstChildOfClass("Humanoid")
        if humanoid.UseJumpPower then return humanoid.JumpPower^2/(2*workspace.Gravity) end
        return humanoid.JumpHeight
    end)
    return ok and tonumber(rise) and rise>0 and rise or nil
end
local function headingOf(velocity) return math.atan2(velocity.Z,velocity.X) end
local function wrapAngle(angle) return (angle+math.pi)%(2*math.pi)-math.pi end
-- (how fast they turned between two entries, in radians a second, counting only while moving)
local function turnBetween(path,from,to)
    local net,first,last,previous=0,nil,nil,nil
    for index=from,to do
        local entry=path[index]
        if entry.velocity.Magnitude>=2 then
            if previous then net=net+wrapAngle(headingOf(entry.velocity)-headingOf(previous.velocity)) end
            previous=entry
            first=first or entry
            last=entry
        end
    end
    if not first or last.at-first.at<0.15 then return nil end
    return net/(last.at-first.at)
end
-- (turning steadily one way, as round a circle: over the last 0.6 s, both halves turning the same
-- way at much the same rate. The rate, or nil.)
local function steadyTurn(path,now)
    local start=nil
    for index=#path,1,-1 do
        if now-path[index].at<=0.6 then start=index else break end
    end
    if not start or #path-start<8 or now-path[start].at<0.48 then return nil end
    local middle=math.floor((start+#path)/2)
    local early,late=turnBetween(path,start,middle),turnBetween(path,middle,#path)
    if not early or not late or early*late<=0 then return nil end
    local small,big=math.min(math.abs(early),math.abs(late)),math.max(math.abs(early),math.abs(late))
    if big<0.5 or small<0.4*big then return nil end
    return (early+late)/2
end
-- (weaving: within the last second, a turn of 0.4 rad or more one way, then one the other way)
local function weaving(path,now)
    local turns,run,previous={},0,nil
    for _,entry in ipairs(path) do
        if now-entry.at<=PATH_TIME and entry.velocity.Magnitude>=2 then
            if previous then
                local change=wrapAngle(headingOf(entry.velocity)-headingOf(previous.velocity))
                if math.abs(change)>1e-4 then
                    if run==0 or (change>0)==(run>0) then
                        run=run+change
                    else
                        if math.abs(run)>=0.4 then turns[#turns+1]=run end
                        run=change
                    end
                end
            end
            previous=entry
        end
    end
    if math.abs(run)>=0.4 then turns[#turns+1]=run end
    for index=2,#turns do
        if (turns[index]>0)~=(turns[index-1]>0) then return true end
    end
    return false
end
-- (the middle of where they've been over the last 0.8 s, carried on that long at the pace they've
-- been making overall)
local function middleAhead(path,now,current,lead)
    local sumX,sumZ,count,first,last=0,0,0,nil,nil
    for _,entry in ipairs(path) do
        if now-entry.at<=0.8 then
            sumX,sumZ,count=sumX+entry.position.X,sumZ+entry.position.Z,count+1
            first=first or entry
            last=entry
        end
    end
    if count<3 or last.at-first.at<0.2 then return nil end
    local span=last.at-first.at
    local reach=lead+span/2
    return Vector3.new(sumX/count+(last.position.X-first.position.X)/span*reach,current.Y,
        sumZ/count+(last.position.Z-first.position.Z)/span*reach)
end
-- (how far someone going that fast and turning that fast gets in that long: round the arc)
local function wayAhead(horizontal,turn,seconds)
    local angle=turn*seconds
    if math.abs(angle)<0.05 then return horizontal*seconds end
    local heading=math.atan2(horizontal.Z,horizontal.X)+angle/2
    local chord=2*horizontal.Magnitude/math.abs(turn)*math.sin(math.abs(angle)/2)
    return Vector3.new(math.cos(heading),0,math.sin(heading))*chord
end
-- (where they'll be that long on, and which way it was worked out)
local function predictAhead(path,now,current,horizontal,lead)
    local turn=steadyTurn(path,now)
    if turn then
        turn=math.clamp(turn,-ARC_LIMIT/lead,ARC_LIMIT/lead)
        return current+wayAhead(horizontal,turn,lead),"turn",turn
    end
    local straight=current+horizontal*lead
    if weaving(path,now) then
        local middle=middleAhead(path,now,current,lead)
        if middle then return (straight+middle)/2,"weave",0 end
    end
    return straight,"straight",0
end
-- (flung: going far faster than anyone runs, or well off the height they started at)
local FLUNG_SPEED=140
local function flungNow(targetRoot,startY,measured)
    return targetRoot.AssemblyLinearVelocity.Magnitude>FLUNG_SPEED or Vector3.new(measured.X,0,measured.Z).Magnitude>45
        or measured.Magnitude>100 or math.abs(targetRoot.Position.Y-startY)>25
end
-- (the bomb laid flat, its biggest face down: its thinnest side turned to point up)
local function flatRotation(bomb)
    local ok,size=pcall(function() return bomb.Size end)
    if not ok or typeof(size)~="Vector3" then return CFrame.identity,1 end
    if size.X<=size.Y and size.X<=size.Z then return CFrame.Angles(0,0,math.pi/2),size.X end
    if size.Z<=size.X and size.Z<=size.Y then return CFrame.Angles(math.pi/2,0,0),size.Z end
    return CFrame.identity,size.Y
end
-- (how far the top of their head and the soles of their feet are above / below their root,
-- from their body parts only, so hats don't count)
local function bodySpan(character,targetRoot)
    local top,bottom=nil,nil
    for _,part in ipairs(character:GetChildren()) do
        if part:IsA("BasePart") then
            local ok,y,half=pcall(function() return part.Position.Y-targetRoot.Position.Y,part.Size.Y/2 end)
            if ok then
                top=math.max(top or -math.huge,y+half)
                bottom=math.min(bottom or math.huge,y-half)
            end
        end
    end
    return top or 2.5,bottom or -3
end
local PASS_TIME=0.5
-- Moving players: Roblox sends physics only about 20 times a second and shows other players a
-- good while behind where they are on their own screen, so the bomb rides along with a moving
-- player a little ahead of where you see them, to be on them where they really are: your ping
-- plus LEAD_BASE seconds ahead, give or take LEAD_TRIES, staying on each a while (the bomb takes
-- about a third of a second to reach their screen). On the flung player's own screen, in all four
-- test sessions that logged it, it took about 0.56 s ahead to be right on them (put 0.45 s ahead,
-- runners saw it 1 to 3 studs behind them). It used to learn how far from each fling, and that
-- let it wander off to 0.25 s and to 0.8 s, where moving players were flung 60% and 31% of the
-- time against 90% at 0.4-0.5 s, so it stays put now. Where a moving player will be is worked
-- out three ways (see predictAhead).
-- (It can't be welded on: a weld you make exists only on your screen, and welded to them the
-- bomb would stop being yours to send. Attaching it like Reset Player, sweeping it back and
-- forth ahead of them and leaving it in their path all flung less.)
local LEAD_BASE=0.5
local LEAD_TRIES={0,0.1,-0.1}
local LEAD_DWELL=0.45
-- (a moving player gets at least this long, so every distance is tried)
local MOVING_TIME=1.5
local function pingSeconds()
    local ok,value=pcall(function() return LocalPlayer:GetNetworkPing() end)
    return ok and tonumber(value) or 0.1
end
local function baseLead() return math.clamp(pingSeconds(),0,0.4)+LEAD_BASE end
-- (the floor under a spot, ignoring players and the bomb)
local function floorBelow(position,ignore)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances=ignore
    local ok,result=pcall(function() return workspace:Raycast(position+Vector3.new(0,2,0),Vector3.new(0,-60,0),params) end)
    return ok and result and result.Position.Y or nil
end
-- Keeping the bomb yours. What the test logs showed: the game gives a loose bomb to the player
-- nearest it, only that player's moves of it reach anyone else, and a bomb that's yours flings a
-- player the moment it reaches them on their screen. Every miss was a bomb that wasn't yours:
-- one thrown ahead of you flew off and was given to the player it rolled nearest (the one about
-- to be flung), and one left lying where you'd been went to whoever came by; after that it moved
-- only on your screen. And your screen can't tell while you move it: it then always says it's
-- yours. So it's thrown at your feet, only used once it's been watched a moment untouched and
-- found yours, and carried along just under you between flings (below the floor, out of
-- sight), so it stays the bomb nearest you wherever you go.
local CARRY_DEPTH=5
-- (the bomb last found yours, and kept so since)
local verified=nil
-- (the carry's push test: see carry)
local CARRY_CHECK=1.5
local carryTest,nextCarryTest,carryFails=nil,0,0
-- Yours if your own game moves it: pushed up and left alone a few frames, it rises. One that
-- someone else moves only goes where the game sends it (your screen doesn't move it itself, as
-- the test target's log showed: a bomb sent at 32768 studs a second stayed put on it between
-- updates), so it doesn't rise. It's put back, stopped, after either way (so the push itself
-- isn't then taken for it moving). One that didn't rise with nothing coming in for it from the
-- game is stuck in something rather than someone else's (a bomb thrown by you, no one else within
-- 80 studs, failed it for 22 s in a public server): it's tried again in the clear over you, and
-- left there if it rises.
local function pushYours(bomb)
    local ok,before=pcall(function() return bomb.CFrame end)
    if not ok then return false end
    local function rises(from)
        pcall(function() bomb.AssemblyLinearVelocity=Vector3.new(0,30,0) end)
        for _=1,3 do RunService.Heartbeat:Wait() end
        if not usable(bomb) then return false end
        return (bomb.Position-from.Position).Magnitude>0.3 and receiveAge(bomb)<=0.03
    end
    local yours=rises(before)
    local restore=before
    local mine=rootOf(LocalPlayer)
    if not yours and usable(bomb) and receiveAge(bomb)<=0.03 and mine then
        local clear=mine.CFrame*CFrame.new(0,6,0)
        pcall(function() bomb.CFrame=clear;bomb.AssemblyLinearVelocity=Vector3.zero end)
        RunService.Heartbeat:Wait()
        yours=rises(clear)
        if yours then restore=clear end
    end
    pcall(function()
        bomb.CFrame=restore
        bomb.AssemblyLinearVelocity=Vector3.zero;bomb.AssemblyAngularVelocity=Vector3.zero
    end)
    return yours
end
-- (watched for up to that long without being touched: yours once nothing has come in for it
-- from the game for a few frames and it's either moving under your own game, or, lying still,
-- passes the push test)
local function watchYours(bomb,seconds)
    local started,quiet=os.clock(),0
    repeat
        if not usable(bomb) then return false end
        if receiveAge(bomb)>0.03 then quiet=0 else quiet=quiet+1 end
        if quiet>=6 then
            local ok,speed=pcall(function() return bomb.AssemblyLinearVelocity.Magnitude end)
            if ok and speed>1 then return true end
            return pushYours(bomb)
        end
        RunService.Heartbeat:Wait()
    until os.clock()-started>seconds
    return false
end
-- (a new bomb taken out in place of the one there is, once the toy can be thrown again: nil if
-- it can't be yet, or none came out)
local function takeOutAnother()
    if cooldownLeft()>0.05 then return nil end
    local previous=ownBomb
    ownBomb=nil
    local fresh=deployBomb()
    if not fresh then ownBomb=previous end
    return fresh
end
local function runFling(target)
    local targetRoot=rootOf(target)
    if not targetRoot or not aliveCharacter(target) then return false,"no target" end
    if not rootOf(LocalPlayer) then return false,"you are not alive" end
    local label=reportName(target)
    -- (too far off to be on the map with you, or still flying from the last fling, by the speed
    -- the game sends or by how fast they really move: left alone. In the test logs those flings
    -- only counted the last one again, and sent the bomb thousands of studs after them, where one
    -- was lost; two started on someone still sliding off at 50 studs a second)
    do
        local away=(targetRoot.Position-rootOf(LocalPlayer).Position).Magnitude
        if away>FAR_AWAY then
            note(("SKIP %s out of reach (%.0f studs away)"):format(label,away))
            return false,"out of reach"
        end
        local velocity,seen=targetRoot.AssemblyLinearVelocity,movedVelocity(motion[target],os.clock())
        if flying(velocity) or flying(seen) then
            note(("SKIP %s already flung (%.0f studs/s, %.0f studs away)"):format(label,
                math.max(velocity.Magnitude,seen.Magnitude),away))
            return false,"already flung"
        end
    end
    local bomb,reason=getBomb()
    -- (a carried one is pushed first, to be sure it's still yours)
    if bomb and bomb==verified and not pushYours(bomb) then
        note(("CHECK %s the carried bomb isn't yours any more (nearest other player %.0f studs from it, ra=%.2f)"):format(
            label,nearestOther(bomb.Position),receiveAge(bomb)))
        verified=nil
    end
    -- (not known to be yours yet: watched a moment first; one given to someone else is
    -- replaced by a new one taken out, once the toy can be thrown again)
    if bomb and bomb~=verified then
        local yours=watchYours(bomb,os.clock()-lastDeploy.at<3 and 1.2 or 0.4)
        note(("CHECK %s %s ra=%.2f"):format(label,yours and "yours" or "not yours",receiveAge(bomb)))
        if yours then
            verified=bomb
        else
            local another=takeOutAnother()
            local anotherYours=another~=nil and watchYours(another,1.2)
            if another then note(("CHECK %s new one %s"):format(label,anotherYours and "yours" or "not yours")) end
            if anotherYours then
                bomb,verified=another,another
            else
                bomb=nil
                local wait=cooldownLeft()
                reason="the bomb was given to another player (it's nearer them)"
                    ..(wait>0.05 and (", a new one can be taken out in %d s"):format(math.ceil(wait)) or "")
            end
        end
    end
    if not bomb then
        if os.clock()-lastMissingNotice>8 then lastMissingNotice=os.clock();notify("Bomb Fling: "..tostring(reason),3) end
        note(("SKIP %s %s"):format(label,tostring(reason)))
        return false,reason
    end
    stats.flings=stats.flings+1
    do
        local mine=rootOf(LocalPlayer)
        local velocity=targetRoot.AssemblyLinearVelocity
        -- (how long their character has been about, and whether it has a spawn ForceField)
        local since=born[target] and born[target].root==targetRoot and os.clock()-born[target].at or -1
        local shielded=target.Character and target.Character:FindFirstChildOfClass("ForceField") and 1 or 0
        note(("START %s dist=%.0f speed=%.1f ping=%dms duration=%d lead=%.2f spawned=%.1fs ff=%d"):format(label,
            mine and (targetRoot.Position-mine.Position).Magnitude or -1,Vector3.new(velocity.X,0,velocity.Z).Magnitude,
            math.floor(pingSeconds()*1000),settings.duration,baseLead(),since,shielded))
    end
    -- (sent down that fast, a physics step carries it far past the map's fall limit before it's
    -- put back on them: no limit while it flings, as Reset Player does)
    local previousLimit=nil
    pcall(function() previousLimit=workspace.FallenPartsDestroyHeight;workspace.FallenPartsDestroyHeight=0/0 end)
    local started=os.clock()
    local touchFrom=started+TOUCH_DELAY
    local startY=targetRoot.Position.Y
    local hit=false
    local rotation,thickness=flatRotation(bomb)
    local top,bottom=bodySpan(target.Character,targetRoot)
    local passStarted=os.clock()
    local spin=math.random()*math.pi*2
    -- (where they've been over the last moment: see measure)
    local track={}
    local limit=settings.duration
    local lastSample=-math.huge
    local ok,err=pcall(function()
        while os.clock()-started<limit and alive and runtimeAlive do
            if not usable(bomb) then
                -- gone (it went off): another one taken out straight away, and on with that
                note(("REPLACE %s gone: %s"):format(label,tostring(unusableWhy(bomb))))
                local another=takeOutAnother()
                if not (another and watchYours(another,1.2)) then break end
                bomb,verified=another,another
                rotation,thickness=flatRotation(bomb)
                touchFrom=os.clock()+TOUCH_DELAY
            end
            if not targetRoot.Parent or not aliveCharacter(target) then note(("GONE %s (died or left)"):format(label));break end
            -- (put there after each physics step, as Reset Player does)
            RunService.Heartbeat:Wait()
            if not targetRoot.Parent or not usable(bomb) then continue end
            local now=os.clock()
            local current=targetRoot.Position
            local measured=measure(track,current,now)
            if flungNow(targetRoot,startY,measured) then
                hit=true
                note(("HIT %s after %.2fs"):format(label,now-started))
                break
            end
            -- from just above the top of their head down to their feet, then again from the top
            local progress=(now-passStarted)/PASS_TIME
            if progress>=1 then
                passStarted=now;progress=0
                if target.Character then top,bottom=bodySpan(target.Character,targetRoot) end
            end
            -- (the speed the game sends for them, unless it says they're still while they move)
            local velocity=targetRoot.AssemblyLinearVelocity
            local horizontal=Vector3.new(velocity.X,0,velocity.Z)
            local measuredHorizontal=Vector3.new(measured.X,0,measured.Z)
            if horizontal.Magnitude<1 and measuredHorizontal.Magnitude>3 then horizontal=measuredHorizontal end
            if horizontal.Magnitude>80 then horizontal=horizontal.Unit*80 end
            local verticalSpeed=velocity.Y
            if math.abs(verticalSpeed)<1 and math.abs(measured.Y)>3 then verticalSpeed=measured.Y end
            -- moving: a little ahead of where you see them, by the distance being tried
            local moving=horizontal.Magnitude>2
            if moving then limit=math.max(limit,MOVING_TIME) end
            local lead=baseLead()+LEAD_TRIES[math.floor((now-started)/LEAD_DWELL)%#LEAD_TRIES+1]
            local history=motion[target] or {}
            local predicted,how,turn=current,"still",0
            if moving then predicted,how,turn=predictAhead(history,now,current,horizontal,lead) end
            local ignore={bomb}
            if target.Character then ignore[#ignore+1]=target.Character end
            if LocalPlayer.Character then ignore[#ignore+1]=LocalPlayer.Character end
            -- hopping: just over where their soles get to at the top of a jump, sweeping HOP_SWEEP
            -- either way (see HOP_MARGIN)
            local hop=false
            if hopping(history,now) then
                local jump=jumpRise(target.Character)
                local standing=standingHeight(history,now,not moving and jump or nil)
                -- (or over the floor right under them, if that's higher)
                local floorY=floorBelow(current,ignore)
                if floorY then standing=math.max(standing or floorY-bottom,floorY-bottom) end
                if standing then
                    hop=true
                    local clear=standing+(jump or HOP_JUMP)+bottom+thickness/2+HOP_SWEEP+HOP_MARGIN
                    predicted=Vector3.new(predicted.X,clear,predicted.Z)
                end
            end
            -- jumping or falling: along the arc, but never below the floor under them
            if not hop and math.abs(verticalSpeed)>2 then
                local rise=verticalSpeed*lead-0.5*workspace.Gravity*lead*lead
                local lowest=nil
                local floorY=floorBelow(predicted,ignore)
                if floorY then lowest=floorY-bottom end
                predicted=predicted+Vector3.new(0,rise,0)
                if lowest and predicted.Y<lowest then predicted=Vector3.new(predicted.X,lowest,predicted.Z) end
            end
            -- (a small circle round them too, so a little off to one side still crosses the body)
            spin=spin+0.9
            local around=Vector3.new(math.cos(spin)*0.5,0,math.sin(spin)*0.5)
            local height=hop and HOP_SWEEP*(1-2*progress) or (top+thickness/2)+((bottom+thickness/2)-(top+thickness/2))*progress
            local position=predicted+around+Vector3.new(0,height,0)
            -- (spun about the upright, so its big face stays down and the spin throws them sideways)
            pcall(function()
                bomb.CFrame=CFrame.new(position)*rotation
                bomb.AssemblyLinearVelocity=Vector3.new(0,-POWER,0)
                bomb.AssemblyAngularVelocity=Vector3.new(0,POWER,0)
            end)
            local head=target.Character and target.Character:FindFirstChild("Head")
            if now>=touchFrom then
                for _=1,5 do
                    touch(bomb,targetRoot)
                    if head then touch(bomb,head) end
                end
            end
            -- (for the report: where the bomb was put, from them as you see them, along the way
            -- they're moving, or the way they face standing still)
            if now-lastSample>=0.05 then
                lastSample=now
                local look=targetRoot.CFrame.LookVector
                local forward=horizontal.Magnitude>0.5 and horizontal.Unit or Vector3.new(look.X,0,look.Z)
                forward=forward.Magnitude>0.01 and forward.Unit or Vector3.new(0,0,-1)
                local offset=position-current
                note(("S %s ahead=%.1f side=%.1f up=%.1f speed=%.1f lead=%.2f %s%s turn=%.1f moved=%.0f"):format(label,
                    offset:Dot(forward),offset:Dot(Vector3.new(-forward.Z,0,forward.X)),offset.Y,horizontal.Magnitude,
                    moving and lead or 0,how,hop and "+hop" or "",turn,measured.Magnitude))
            end
        end
    end)
    local endedAt=os.clock()
    note(("END %s hit=%d after %.2fs%s"):format(label,hit and 1 or 0,endedAt-started,ok and "" or (" error: "..tostring(err))))
    -- (flung after the fling ended, too late to be seen in it: watched a moment longer)
    if not hit and targetRoot.Parent then
        task.spawn(function()
            local after={}
            while os.clock()-endedAt<3 and targetRoot.Parent and alive do
                if flungNow(targetRoot,startY,measure(after,targetRoot.Position,os.clock())) then
                    note(("LATEHIT %s %.2fs after the end"):format(label,os.clock()-endedAt))
                    break
                end
                task.wait(0.05)
            end
        end)
    end
    -- (straight back under you and stopped, before the fall limit is put back. Left lying on
    -- them, the game gave it to them a fifth of a second after every miss in the test logs,
    -- and the next flings went on with a bomb only your screen moved. It's pushed to see it's
    -- still yours only once it's been back under you a moment: see carry)
    if bomb and usable(bomb) then pcall(function()
        local mine=rootOf(LocalPlayer)
        if mine then
            if bomb.CanCollide then bomb.CanCollide=false end
            bomb.CFrame=mine.CFrame*CFrame.new(0,-CARRY_DEPTH,0)
        end
        bomb.AssemblyLinearVelocity=Vector3.zero;bomb.AssemblyAngularVelocity=Vector3.zero
    end) end
    carryTest,nextCarryTest=nil,os.clock()+0.5
    if previousLimit~=nil then
        pcall(function()
            local current=workspace.FallenPartsDestroyHeight
            if current~=current then workspace.FallenPartsDestroyHeight=previousLimit end
        end)
    end
    if not ok then stats.lastError=tostring(err) end
    if hit then stats.hits=stats.hits+1 end
    return hit
end
-- (carried along just under you between flings: see CARRY_DEPTH. Not while Firefly Protection
-- holds it as its particle helper. Every CARRY_CHECK seconds it's given the push test, left
-- alone a few frames; failing twice, it's no longer counted yours.)
local carry=RunService.Heartbeat:Connect(function()
    local bomb=verified
    if flinging or not alive or not runtimeAlive or not bomb or bomb~=ownBomb then carryTest=nil;return end
    if not usable(bomb) then verified,carryTest=nil,nil;return end
    local protection=runtime.FireflyProtection
    if protection and type(protection.CurrentBomb)=="function" then
        local ok,held=pcall(protection.CurrentBomb)
        if ok and held==bomb then carryTest=nil;return end
    end
    local mine=rootOf(LocalPlayer)
    if not mine then return end
    local now=os.clock()
    if carryTest then
        carryTest.frames=carryTest.frames+1
        if carryTest.frames<3 then return end
        local ok,moved=pcall(function() return (bomb.Position-carryTest.from).Magnitude end)
        carryTest=nil
        if ok and moved>0.3 and receiveAge(bomb)<=0.03 then
            carryFails=0
        else
            carryFails=carryFails+1
            note(("CARRY the bomb didn't rise when pushed (%d), nearest other player %.0f studs from it, ra=%.2f"):format(
                carryFails,nearestOther(bomb.Position),receiveAge(bomb)))
            if carryFails>=2 then
                verified,carryFails=nil,0
                pcall(function() bomb.AssemblyLinearVelocity=Vector3.zero end)
                note("CARRY lost: someone else moves the bomb now")
                return
            end
        end
    elseif now>=nextCarryTest then
        nextCarryTest=now+CARRY_CHECK
        local ok,from=pcall(function() return bomb.Position end)
        if ok then
            carryTest={from=from,frames=0}
            pcall(function() bomb.AssemblyLinearVelocity=Vector3.new(0,30,0) end)
            return
        end
    end
    pcall(function()
        if bomb.CanCollide then bomb.CanCollide=false end
        bomb.CFrame=mine.CFrame*CFrame.new(0,-CARRY_DEPTH,0)
        bomb.AssemblyLinearVelocity=Vector3.zero
        bomb.AssemblyAngularVelocity=Vector3.zero
    end)
end)
-- Flings run one after another from a queue on their own thread, so pressing a button
-- never waits on (or freezes for) a fling.
local function pump()
    if flinging then return end
    flinging=true
    task.spawn(function()
        while #flingQueue>0 and alive and runtimeAlive do
            local target=table.remove(flingQueue,1)
            if target and target.Parent and target~=LocalPlayer and not isWhitelisted(target) then
                local ok,err=pcall(runFling,target)
                if not ok then stats.lastError=tostring(err) end
            end
        end
        flinging=false
    end)
end
local function fling(target)
    if not target or target==LocalPlayer or isWhitelisted(target) then return end
    for _,queued in ipairs(flingQueue) do if queued==target then return end end
    if #flingQueue>=12 then return end
    flingQueue[#flingQueue+1]=target
    pump()
end
local function others()
    local list={}
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LocalPlayer and not isWhitelisted(plr) and aliveCharacter(plr) then list[#list+1]=plr end
    end
    return list
end
local function startLoop(key,body)
    if loops[key] then loops[key]=nil end
    local token={}
    loops[key]=token
    task.spawn(function()
        while loops[key]==token and alive and runtimeAlive do
            local ok,err=pcall(body)
            if not ok then stats.lastError=tostring(err) end
            -- (waits for the queued flings to finish before going round again)
            while flinging and loops[key]==token do task.wait(0.1) end
            task.wait(LOOP_DELAY)
        end
    end)
end
local function stopLoop(key) loops[key]=nil end
runtime.ThrownBomb=ThrownBomb
runtime.BombFling={Fling=fling,GetBomb=getBomb,
    -- (the bomb Bomb Fling threw and still has out, for Firefly Protection to keep as a particle)
    OwnBomb=function() return ownBomb and usable(ownBomb) and ownBomb or nil end,
    -- (so Firefly Protection never takes a bomb for a firefly)
    IsBomb=function(part) return bombs[part]~=nil or part==ownBomb end,
    -- (the nearest Fake Bomb that's yours to move, for Firefly Protection to take: one like your
    -- toy, within that many studs of you)
    NearestOwnedBomb=function(within) return nearestOwnedBomb(false,within,bombSignature(findBombTool())) end,
    GetDiagnostics=function()
    local count=0
    for _ in pairs(bombs) do count=count+1 end
    local copy=table.clone(stats);copy.tracked=count;copy.ownBomb=ownBomb and ownBomb:GetFullName() or nil
    copy.queue=#flingQueue;copy.flinging=flinging;copy.reportLines=#reportLines;copy.verified=verified~=nil and verified==ownBomb
    return copy
end}

