-- MMV keeps every one of its settings apart from MM2's (MM2's Knife Shield and MMV's Gun
-- Shield, say, no longer switch each other off), starting from what they were before. Every
-- toggle starts off on a clean install; MMV's sliders start at ring 2 out at speed 2 and the
-- Shield Distance at 2 (right against your body).
local MMV_OWN={
    -- (toggles: MMV's own key, and the shared one it was in before)
    shield={"fireflyMMV_GunShield","fireflyProtectShield"},
    ring={"fireflyMMV_RingAura","fireflyProtectRing"},
    mouse={"fireflyMMV_FollowMouse","fireflyProtectMouse"},
    autoJar={"fireflyMMV_AutoJar","fireflyProtectAutoJar"},
    fakeBomb={"fireflyMMV_FakeBomb","fireflyProtectFakeBomb"},
    -- (sliders: MMV's own key, the shared one, where that used to start, MMV's start)
    ringDistance={"fireflyMMVRingDistance","fireflyRingDistance",3,2},
    ringSpeed={"fireflyMMVRingSpeed","fireflyRingSpeed",3,2},
}
function MMV_OWN.key(field) local entry=MMV_OWN[field];return isMMV and entry[1] or entry[2] end
function MMV_OWN.default(field) local entry=MMV_OWN[field];return isMMV and entry[4] or entry[3] end
function MMV_OWN.read(field)
    local key,old,oldDefault,default=table.unpack(MMV_OWN[field])
    if not isMMV then return C(old,oldDefault) end
    local own=C(key)
    if own~=nil then return own end
    local previous=C(old)
    if previous~=nil and previous~=oldDefault and type(previous)==type(default) then return C(key,previous) end
    return C(key,default)
end
-- (a toggle: MMV's own, else what it was in the shared one, else off)
function MMV_OWN.toggle(field)
    local key,old=MMV_OWN[field][1],MMV_OWN[field][2]
    if not isMMV then return C(old,false)==true end
    local own=C(key)
    if own~=nil then return own==true end
    return C(key,C(old)==true)==true
end
-- MMV's Shield Distance: 2 is right against your body (where it was closest before), down to 1
-- for up to a stud closer still (never inside your torso), up to 3 for a stud off; one saved
-- further out than that (it went to 5 before) comes back as 3
local SHIELD_MAX=3
function MMV_OWN.shieldDistance()
    local own=tonumber(C("fireflyMMV_ShieldDistance"))
    if own then return math.clamp(own,1,SHIELD_MAX) end
    local gap=tonumber(C("fireflyMMVShieldGap"))
    if not gap then
        local old=tonumber(C("fireflyShieldGap"))
        if old and old~=0.1 then gap=old end
    end
    return math.clamp(tonumber(C("fireflyMMV_ShieldDistance",gap and math.clamp(gap+2,1,SHIELD_MAX) or 2)) or 2,1,SHIELD_MAX)
end
-- MM2's Knife Interception: it stops a knife 10 studs out along the knife's path from the one it's
-- at (its furthest row; never past the knife itself), and it guards everyone within 6 studs of
-- you, you among them. Both fixed. (Knives are seen from 60 studs, further past 14.)
local INTERCEPT_STUDS=14
local INTERCEPT_STOP,INTERCEPT_AREA=10,6
local settings={
    shield=MMV_OWN.toggle("shield"),
    intercept=not isMMV and C("fireflyProtectIntercept",false)==true,
    -- (MM2's third: Hidden Knife Interception)
    sky=not isMMV and C("fireflyProtectHidden",false)==true,
    ring=isMMV and MMV_OWN.toggle("ring") or C("fireflyProtectRing",C("fireflyProtectShuffle",false)==true)==true,
    mouse=MMV_OWN.toggle("mouse"),
    autoJar=MMV_OWN.toggle("autoJar"),
    -- (the Fake Bomb as a particle helper: MMV only, taken out of MM2)
    fakeBomb=isMMV and MMV_OWN.toggle("fakeBomb") or false,
    -- (MMV: the Gold Bomb kept out too, and the shield turned to the murderer as well)
    goldBomb=isMMV and C("fireflyMMV_GoldBomb",false)==true or false,
    murdererShield=isMMV and C("fireflyMMV_MurdererShield",false)==true or false,
    distance=math.clamp(tonumber(C("fireflyProtectDistance",2.2)) or 2.2,1,4),
    interceptArea=INTERCEPT_AREA,
    interceptStop=INTERCEPT_STOP,
    -- (how far out from you knives are stopped: twice as far as it first was, fixed)
    blockScale=isMMV and 1 or 2,
    ringDistance=math.clamp(tonumber(MMV_OWN.read("ringDistance")) or MMV_OWN.default("ringDistance"),1,8),
    ringSpeed=math.clamp(tonumber(MMV_OWN.read("ringSpeed")) or MMV_OWN.default("ringSpeed"),0,10),
    shieldDistance=isMMV and MMV_OWN.shieldDistance() or 2,
    -- (MM2's Firefly Ring Speed: 1 to 5, 2 being the speed it was fixed at before)
    mm2RingSpeed=not isMMV and math.clamp(tonumber(C("fireflyMM2RingSpeed",2)) or 2,1,5) or 2,
    -- (Fake Bomb Spin Speed: how fast the Fake Bomb turns over your head, in turns a second,
    -- 1 to 5; MMV only)
    bombSpin=isMMV and math.clamp(tonumber(C("fireflyMMV_FakeBombSpin",1)) or 1,1,5) or 1,
}
settings.shieldGap=settings.shieldDistance-2
-- (taken out: Protect Selected User; the Interception Distance and Area sliders, now fixed; Show
-- Interception Area with its colour and transparency; MM2's Fake Bomb Spin Speed. What they saved
-- goes from the settings file)
for _,key in ipairs({"fireflyProtectUserIntercept","fireflyProtectUserShield","fireflyProtectUser",
    "fireflyInterceptArea","fireflyInterceptStop","fireflyInterceptAreaShow","fireflyInterceptAreaColor",
    "fireflyInterceptAreaAlpha","fireflyFakeBombSpin"}) do SetCfg(key,nil) end
local JAR_COOLDOWN=16       -- (the same as Firefly Clutch's timer: from opening it to ready again)
local FOLLOW=20             -- how quickly a shield turns to a moving attacker
-- MMV's Gun Shield: the original's 5 x 5 square (shield v13), 0.52 apart, centred at your
-- middle (SHIELD_HEIGHT 0); how far off your body is the Shield Distance slider
local SHIELD={rows=5,columns=5,spacing=0.52,height=0}
local MMV_FAR=80            -- a gun holder behind a wall this far away: just the ring aura
local MAX_FIREFLIES=90
local NEAR=40               -- a murderer this close is shielded against even behind a wall
local RANGE=200             -- further than this an attacker isn't a danger yet
local MURDERER_RANGE=250    -- (MMV) a murderer in sight this close gets the bombs turned to them
local MOUSE_RANGE=50        -- how far from you the mouse swarm may go
local LIFT=Vector3.new(0,0.6,0)
local MARK="VisualsV2_Firefly"
local fireflies={}
local list={}
local loop,placeLoop,watchAdded,watchRemoved,autoLoop
local knives={}
local smoothDirection=nil
-- (MMV, the murderer and the one with the gun both after you: the way the bombs face, turned to
-- the murderer on their own while the fireflies stay on the gun)
local smoothBombDirection=nil
local murdererNotice=-math.huge
local diagnostics={fireflies=0,owned=0,threat="none",mode="idle",active=false,intercepts=0,jarUses=0,jarAttempts=0,skippedSlots=0,knivesDone=0}

-- (MMV's Protect Against Murderer works with the bombs: only while one of them is on)
local function murdererGuard() return isMMV and settings.murdererShield and (settings.fakeBomb or settings.goldBomb) or false end
local function protecting() return settings.shield or settings.intercept or settings.sky or settings.ring or settings.mouse or murdererGuard() end
-- (MMV: the bombs are only used while the Gun Shield or Protect Against Murderer is on)
local function bombsActive() return not isMMV or settings.shield or murdererGuard() end
-- (Use Fake Bomb As Particle Helper on its own keeps the status up, saying what it needs, as
-- does MMV's Protect Against Murderer without a bomb)
local function active() return protecting() or settings.autoJar or settings.fakeBomb or settings.goldBomb or (isMMV and settings.murdererShield) end
local function owned(part)
    local ok,age=pcall(function() return part.ReceiveAge end)
    return not ok or age==0
end
local function myRoot()
    local character=LocalPlayer.Character
    return character and character:FindFirstChild("HumanoidRootPart"),character
end
local function hasTool(plr,word)
    for _,container in ipairs({plr.Character,plr:FindFirstChildOfClass("Backpack")}) do
        if container then
            for _,tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and tool.Name:lower():find(word,1,true) then return true end
            end
        end
    end
    return false
end
local function role(plr)
    for _,name in ipairs({"Role","CurrentRole"}) do
        local value=plr:GetAttribute(name)
        if type(value)=="string" then return value:lower() end
    end
end
local function aliveRoot(plr)
    local character=plr.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local root=character and character:FindFirstChild("HumanoidRootPart")
    if root and humanoid and humanoid.Health>0 then return root,character end
end
-- MM2's own round data says who the murderer is too (asked in the background, every few
-- seconds, so nothing waits on it)
local ReplicatedStorage=game:GetService("ReplicatedStorage")
local roundMurderer,roundCheckedAt,roundChecking=false,-math.huge,false
local roundData=nil
local function refreshRound()
    if isMMV or roundChecking or os.clock()-roundCheckedAt<3 then return end
    roundChecking=true
    task.spawn(function()
        local ok,data=pcall(function()
            local remote=ReplicatedStorage:FindFirstChild("GetPlayerData",true)
            if remote and remote:IsA("RemoteFunction") then return remote:InvokeServer() end
        end)
        if ok and type(data)=="table" then
            roundData=data
            local mine=data[LocalPlayer.Name]
            roundMurderer=type(mine)=="table" and mine.Role=="Murderer" and not mine.Dead and not mine.Killed or false
        end
        roundCheckedAt=os.clock();roundChecking=false
    end)
end
local function iHaveKnife() return role(LocalPlayer)=="murderer" or hasTool(LocalPlayer,"knife") or roundMurderer end
-- (MM2: a round is on while someone has the knife)
local function roundOn()
    if isMMV then return false end
    if roundMurderer then return true end
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LocalPlayer and (role(plr)=="murderer" or hasTool(plr,"knife")) then return true end
    end
    return false
end
-- the other players who could hurt you: knives (MM2) or guns (MMV), nearest first
local function attackers(root,except)
    local found={}
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LocalPlayer and plr~=except then
            local other=aliveRoot(plr)
            if other then
                local threat
                if isMMV then threat=hasTool(plr,"gun") or role(plr)=="sheriff" or role(plr)=="hero"
                else threat=role(plr)=="murderer" or hasTool(plr,"knife") end
                if threat then found[#found+1]={player=plr,root=other,distance=(other.Position-root.Position).Magnitude} end
            end
        end
    end
    table.sort(found,function(a,b) return a.distance<b.distance end)
    return found
end
local function clutchBusy()
    local clutch=runtime.FireflyClutch
    if not clutch or type(clutch.Busy)~="function" then return false end
    local ok,busy=pcall(clutch.Busy)
    return ok and busy==true
end

-- ---------------------------------------------------------------- the fireflies
local jar={usedAt=-math.huge,spawnedAt=-math.huge,busy=false,waitingEnabled=false,enabledBack=false,hooked=setmetatable({}, {__mode="k"}),
    respawnAt=os.clock()}
local function inCharacterOrTool(object)
    local current=object.Parent
    for _=1,8 do
        if not current or current==workspace then return false end
        if current:IsA("Tool") or current:IsA("Accessory") or current:FindFirstChildOfClass("Humanoid") then return true end
        local name=current.Name:lower()
        if name=="weapondisplays" or name=="throwingknife" or name:sub(1,9)=="visualsv2" then return true end
        current=current.Parent
    end
    return false
end
-- (whatever the jar moves a firefly with is held off while protection moves it, so nothing
-- pulls against it; given back when protection lets go)
local MOVERS={BodyPosition="MaxForce",BodyVelocity="MaxForce",BodyGyro="MaxTorque",BodyAngularVelocity="MaxTorque",
    BodyForce="Force",BodyThrust="Force"}
local CONSTRAINT_MOVERS={AlignPosition=true,AlignOrientation=true,LinearVelocity=true,AngularVelocity=true,VectorForce=true}
local function calm(part)
    local saved=fireflies[part]
    if not saved then return end
    saved.movers=saved.movers or {}
    for _,child in ipairs(part:GetChildren()) do
        if not saved.movers[child] then
            local property=MOVERS[child.ClassName]
            if property then
                local ok,value=pcall(function() return child[property] end)
                if ok and value~=nil then
                    saved.movers[child]={property,value}
                    pcall(function() child[property]=Vector3.zero end)
                end
            elseif CONSTRAINT_MOVERS[child.ClassName] then
                local ok,value=pcall(function() return child.Enabled end)
                if ok then saved.movers[child]={"Enabled",value};pcall(function() child.Enabled=false end) end
            end
        end
    end
end
local function uncalm(part)
    local saved=fireflies[part]
    if not saved or not saved.movers then return end
    for mover,value in pairs(saved.movers) do
        pcall(function() if mover.Parent then mover[value[1]]=value[2] end end)
    end
    saved.movers=nil
end
local function track(part)
    if fireflies[part] or #list>=MAX_FIREFLIES or not part.Parent then return end
    fireflies[part]={collide=part.CanCollide,anchored=part.Anchored}
    list[#list+1]=part
    jar.spawnedAt=os.clock()
    pcall(function() part:SetAttribute(MARK,true);part.CanCollide=false end)
    -- (massless, as the original shield makes them, so they never drag on anything)
    pcall(function() fireflies[part].massless=part.Massless;part.Massless=true end)
end
local offsets=setmetatable({}, {__mode="k"})
local blocking=setmetatable({}, {__mode="k"})
local offsetAnchor=setmetatable({}, {__mode="k"})
local pinned=setmetatable({}, {__mode="k"})
-- Use Fake Bomb As Particle Helper: one of your Fake Bombs kept out (thrown out by itself
-- whenever none is and the toy is ready, putting back what you held; or the one you throw),
-- never solid on your screen, so it can't push you, and held whether or not the game lets your
-- client move it. It isn't one of the fireflies: it floats over your head, tumbling, carried
-- along with you every frame as they are (straight to you after a teleport). MM2: until a knife
-- is thrown at you, when it's put ahead of the fireflies, still, its broad side to the knife.
-- MMV: the whole time the shield is up (Gun Shield, Protect Against Murderer) it's in the
-- middle of the shield, its broad side to them, every firefly in a closed frame round it (with
-- no bomb out, the shield as it always is); a knife at you, every bomb out waiting where it
-- would hit you. MMV's Use Gold Bomb As Particle Helper keeps Gold Bombs out the same way beside
-- it (Gold Bomb Jump off meanwhile).
-- Not with MM2's Hidden Knife Interception. Bomb Jump Clutch is off while this is on (not
-- as the MM2 murderer, when it's left alone, nor with Hidden Knife Interception); Bomb Fling
-- comes first: while it flings, the bomb is its, and afterwards it's taken back if it's still out.
-- (the ways of throwing it: "remote", its Remote told to put it right in front of your feet,
-- Bomb Jump's way; "tap", the toy pressed and let go in your hand, the way you throw it
-- yourself; "screen", a tap on the screen where nothing on it is, with the toy in your hand,
-- never on a touch screen. Tried in turn (see throwOrder; for the Gold Bomb, the way that last
-- brought one first), until one brings a bomb. Never given up on.)
-- (each toy: its own cooldown, shared by every bomb thrown with it; MMV's Gold Bomb is ready
-- again 5 s after a throw, so several of it can be out at once. For the Gold Bomb, the way that
-- last worked with it is kept between sessions; the Fake Bomb keeps its fixed order)
local function newKit(config)
    local saved=config.wayKey and C(config.wayKey) or nil
    if saved~="tap" and saved~="remote" and saved~="screen" then saved=nil end
    return {name=config.name,toolName=config.toolName,toy=config.toy,cooldown=config.cooldown,readyAt=0,failures=0,
        wayKey=config.wayKey,way=saved}
end
local FAKE_KIT=newKit({name="Fake Bomb",toolName="fakebomb",toy="FakeBomb",cooldown=22})
local GOLD_KIT=newKit({name="Gold Bomb",toolName="goldbomb",toy="GoldBomb",cooldown=5,wayKey="fireflyMMV_GoldBombWay"})
-- (one slot for each bomb kept out: the Fake Bomb, and in MMV up to three Gold Bombs (three
-- bombs at most in all: the Fake Bomb takes one of the places when it's on))
local MAX_BOMBS=3
local function newSlot(config)
    return {part=nil,collide=nil,deploying=false,checkAt=0,name=config.name,kit=config.kit,setting=config.setting,index=config.index or 1}
end
local fakeBomb=newSlot({name="Fake Bomb",kit=FAKE_KIT,setting="fakeBomb"})
local goldBombs={}
for index=1,MAX_BOMBS do goldBombs[index]=newSlot({name="Gold Bomb",kit=GOLD_KIT,setting="goldBomb",index=index}) end
local SLOTS={fakeBomb}
for _,slot in ipairs(goldBombs) do SLOTS[#SLOTS+1]=slot end
local function slotWanted(slot)
    if not settings[slot.setting] then return false end
    if slot.kit==GOLD_KIT then return slot.index<=MAX_BOMBS-(settings.fakeBomb and 1 or 0) end
    return true
end
-- (a bomb being thrown: one at a time, the toy in your hand meanwhile)
local function bombThrowing()
    for _,slot in ipairs(SLOTS) do if slot.deploying then return true end end
    return false
end
-- (a part one of the other bombs has, or had, or one that turned up while another bomb was being
-- thrown: that one's. Bombs are thrown one at a time, each until it's found, so a Gold Bomb
-- landing is never taken for the Fake Bomb, nor the other way round)
local appeared=setmetatable({}, {__mode="k"})
local function otherBomb(slot,part)
    for _,other in ipairs(SLOTS) do
        if other~=slot then
            if other.part==part or other.last==part or other.found==part then return true end
            local at=appeared[part]
            if at and other.throwAt and at>=other.throwAt-0.05 then return true end
        end
    end
    return false
end
-- The ways of throwing it, in turn until one brings a bomb: MM2, its Remote told to put it right
-- in front of your feet (Bomb Jump's and Bomb Fling's way: you're the nearest one, so the game
-- hands it to you), then the toy pressed and let go in your hand; MMV the other way round (a tap
-- there hands you the bomb), except MMV's Gold Bomb: its Remote first, the way Gold Bomb Jump
-- throws it at once (a tap with it in hand doesn't bring one, so the toy sat in your hand for a
-- second before every throw). A tap on the screen where nothing on it is last, never on a touch
-- screen (a mouse click there takes your joystick and jump button away, so you can't move).
-- For the Gold Bomb, whichever way last brought one goes first.
local function touchOnly()
    local ok,touch=pcall(function() return UserInput.TouchEnabled and not UserInput.MouseEnabled end)
    return ok and touch==true
end
local function throwOrder(kit)
    local order=isMMV and {"tap","remote"} or {"remote","tap"}
    if kit==GOLD_KIT then order={"remote","tap"} end
    if not touchOnly() then order[#order+1]="screen" end
    local way=kit and kit.way
    local at=way and table.find(order,way)
    if at and at>1 then table.remove(order,at);table.insert(order,1,way) end
    return order
end
-- (a bomb that's still out: in the map, and not right at its fall limit. It had to be 25 studs
-- above that limit, so on maps built close to it every bomb that was found counted as gone, and
-- none was ever kept: the bombs in MM2, and in MMV on some maps)
-- With no real limit (anti-void scripts set it to NaN or -inf) there's nothing to fall out of.
local function bombAlive(part)
    if not part or not part.Parent or not part:IsDescendantOf(workspace) then return false end
    local ok,y=pcall(function() return part.Position.Y end)
    if not ok or y~=y then return false end
    local limit=workspace.FallenPartsDestroyHeight
    if type(limit)~="number" or limit~=limit or math.abs(limit)==math.huge then return true end
    return y>limit+2
end
-- (why a bomb isn't still out, for the status)
local function bombGoneWhy(part)
    if typeof(part)~="Instance" then return "nothing was found" end
    local why="it's gone"
    pcall(function()
        if not part.Parent then why="it was removed"
        elseif not part:IsDescendantOf(workspace) then why="it was moved out of the map (into "..part.Parent.Name..")"
        else
            local limit=workspace.FallenPartsDestroyHeight
            if limit==limit and math.abs(limit)~=math.huge and part.Position.Y<=limit+2 then why=("it fell out of the map (height %d, the map's limit is %d)"):format(math.floor(part.Position.Y),math.floor(limit)) end
        end
    end)
    return why
end
-- (what a part is, in short: its name and size)
local function describeBomb(part)
    local text="?"
    pcall(function()
        local size=part.Size
        text=("%s %.1fx%.1fx%.1f"):format(part.Name,size.X,size.Y,size.Z)
    end)
    return text
end
local function bombFlinging()
    local fling=runtime.BombFling
    if not fling or type(fling.GetDiagnostics)~="function" then return false end
    local ok,diagnosis=pcall(fling.GetDiagnostics)
    return ok and type(diagnosis)=="table" and (diagnosis.flinging==true or (tonumber(diagnosis.queue) or 0)>0)
end
-- (which bombs are out, for the status)
local function countBombs()
    local golds=0
    for _,slot in ipairs(goldBombs) do if slot.part then golds=golds+1 end end
    diagnostics.fakeBomb=fakeBomb.part~=nil
    diagnostics.goldBomb=golds>0;diagnostics.goldBombs=golds
end
local function releaseBomb(slot)
    if not slot then
        for _,each in ipairs(SLOTS) do releaseBomb(each) end
        return
    end
    local part=slot.part
    slot.part=nil;slot.pose=nil;slot.owned=nil;slot.notOursSince=nil;slot.guess=nil
    countBombs()
    if part then
        offsets[part]=nil;offsetAnchor[part]=nil;pinned[part]=nil
        if slot.collide~=nil then pcall(function() part.CanCollide=slot.collide end) end
    end
    slot.collide=nil
end
-- (kept out from now on, whether or not the game lets your client move it: one it keeps to
-- itself is held all the same, but then it only moves on your screen, and the status says so)
local function adoptBomb(slot,part)
    if slot.part==part then return end
    -- (never both slots holding the same one)
    for _,other in ipairs(SLOTS) do if other~=slot and other.part==part then return end end
    releaseBomb(slot)
    slot.part=part;slot.last=part
    countBombs()
    local ok,collide=pcall(function() return part.CanCollide end)
    slot.collide=ok and collide or nil
    pcall(function() part.CanCollide=false;part.AssemblyLinearVelocity=Vector3.zero end)
end
local function forget(part)
    local saved=fireflies[part]
    if not saved then return end
    uncalm(part)
    fireflies[part]=nil
    offsets[part]=nil;offsetAnchor[part]=nil;pinned[part]=nil
    local index=table.find(list,part)
    if index then table.remove(list,index) end
    if part.Parent then pcall(function() part.CanCollide=saved.collide;part:SetAttribute(MARK,nil) end) end
    if part.Parent and saved.massless~=nil then pcall(function() part.Massless=saved.massless end) end
end
-- (nothing that is a bomb, a toy, a weapon or a coin is ever taken for a firefly)
local NOT_FIREFLY={"coin","bullet","knife","shell","bomb","handle","gun","toy","balloon","pet","visualsv2"}
local function notFirefly(part)
    local named=part.Name:lower():find("firefl",1,true)~=nil
    local current=part
    for _=1,5 do
        if not current or current==workspace then break end
        local name=current.Name:lower()
        if named then
            -- (a real firefly: only a bomb around it rules it out)
            if name:find("bomb",1,true) then return true end
        else
            for _,word in ipairs(NOT_FIREFLY) do if name:find(word,1,true) then return true end end
        end
        current=current.Parent
    end
    local bombFling=runtime.BombFling
    if bombFling and type(bombFling.IsBomb)=="function" then
        local ok,bomb=pcall(bombFling.IsBomb,part)
        if ok and bomb then return true end
    end
    return false
end
-- (a part on its own: nothing welded or hinged to another part, and not a piece of
-- something big like a door that swings; moving one of those can fling you. A firefly's
-- own mover, tied to nothing else, doesn't count.)
-- (body parts by name, so a ragdoll or a body left behind is never taken either)
local BODY_PARTS={}
for _,name in ipairs({"head","torso","uppertorso","lowertorso","humanoidrootpart","lefthand","righthand","leftfoot","rightfoot",
    "leftlowerarm","rightlowerarm","leftupperarm","rightupperarm","leftlowerleg","rightlowerleg","leftupperleg","rightupperleg",
    "left arm","right arm","left leg","right leg"}) do BODY_PARTS[name]=true end
local function onItsOwn(part)
    -- (never anything of a player: their body, what's worn or welded on them)
    if BODY_PARTS[part.Name:lower()] then return false end
    for _,plr in ipairs(Players:GetPlayers()) do
        local character=plr.Character
        if character and part:IsDescendantOf(character) then return false end
    end
    -- (each check on its own, so one the game can't answer doesn't skip the others)
    local okAssembly,assembly=pcall(function() return part.AssemblyRootPart end)
    if okAssembly and assembly and assembly~=part then return false end
    -- (only things that hold it to another part count: welds, hinges, ropes, springs... A
    -- mover that pulls it about, like the jar's own one that keeps the fireflies with you,
    -- doesn't; nor does anything joining it to your own character, or to something that isn't
    -- out in the world, like the jar back in your backpack)
    local okJoints,jointed=pcall(function()
        local mine=LocalPlayer.Character
        for _,joint in ipairs(part:GetJoints()) do
            local other=nil
            if joint:IsA("JointInstance") or joint:IsA("WeldConstraint") or joint:IsA("RigidConstraint") then
                other=joint.Part0==part and joint.Part1 or joint.Part0
            elseif joint:IsA("HingeConstraint") or joint:IsA("BallSocketConstraint") or joint:IsA("RopeConstraint")
                or joint:IsA("RodConstraint") or joint:IsA("SpringConstraint") or joint:IsA("PrismaticConstraint")
                or joint:IsA("CylindricalConstraint") or joint:IsA("PlaneConstraint") or joint:IsA("UniversalConstraint") then
                local a,b=joint.Attachment0,joint.Attachment1
                local pa,pb=a and a.Parent,b and b.Parent
                other=(pa==part and pb) or (pb==part and pa) or nil
            end
            if other and other~=part and other:IsA("BasePart") and other:IsDescendantOf(workspace)
                and not (mine and other:IsDescendantOf(mine)) then return true end
        end
        return false
    end)
    if okJoints and jointed then return false end
    local okModel,inBig=pcall(function()
        local model=part:FindFirstAncestorOfClass("Model")
        if not model or model==workspace then return false end
        -- (a body, even one without its Humanoid any more)
        if model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Head") or model:FindFirstChildWhichIsA("Humanoid",true) then return true end
        local pieces=0
        for _,child in ipairs(model:GetDescendants()) do
            if child:IsA("BasePart") and child~=part then
                pieces=pieces+1
                local size=child.Size
                if pieces>60 or math.max(size.X,size.Y,size.Z)>2.5 then return true end
            end
        end
        return false
    end)
    if okModel and inBig then return false end
    return true
end
local function consider(part)
    if not part:IsA("BasePart") or fireflies[part] then return end
    local name=part.Name:lower()
    local named=name:find("firefl",1,true)~=nil
    -- MM2's fireflies are all called Firefly; only MMV's jar gives unnamed glowing bits
    if not named and not isMMV then return end
    if notFirefly(part) then return end
    local root=myRoot()
    if not root then return end
    local recent=os.clock()-jar.usedAt<(isMMV and 14 or 12)
    if not named and not recent then return end
    if part.Anchored or inCharacterOrTool(part) then return end
    local size=part.Size
    if math.max(size.X,size.Y,size.Z)>(named and 2.5 or 1.2) or math.min(size.X,size.Y,size.Z)<0.02 then return end
    if not onItsOwn(part) then return end
    -- (MMV's jar gives loose glowing bits: anything small that isn't part of a model of its own)
    if not named then
        local model=part:FindFirstAncestorOfClass("Model")
        if model and model~=workspace and (model:FindFirstChildOfClass("Humanoid") or (model.PrimaryPart and model.PrimaryPart~=part)) then return end
        -- (and none of the toy's own pieces: a jar bit has nothing inside it but light and effects)
        for _,child in ipairs(part:GetChildren()) do
            if child:IsA("DataModelMesh") and not part:IsA("MeshPart") and child:IsA("SpecialMesh") and child.MeshId~="" then return end
            if child:IsA("JointInstance") or child:IsA("WeldConstraint") or child:IsA("TouchTransmitter") then return end
        end
    end
    local ok,distance=pcall(function() return (part.Position-root.Position).Magnitude end)
    if not ok or distance>(named and 30 or 40) then return end
    -- (someone else's fireflies are theirs to move, not ours)
    if named and not recent and not owned(part) then return end
    track(part)
end
-- the jar's cap: while it's out (a few seconds after the jar opens) it goes along with the
-- fireflies (only on your screen if the game doesn't let you move it)
local caps={}
local CAP_NAMES={handle2=true,lid=true,jarlid=true,jarcap=true,cap=true,cork=true}
local function considerCap(part)
    if caps[part] or fireflies[part] or not part:IsA("BasePart") or not CAP_NAMES[part.Name:lower()] then return end
    -- (only one that turns up right as your jar opens, right next to you, small, and loose:
    -- nothing else that happens to be called that, like a piece of a door)
    if os.clock()-jar.usedAt>3 then return end
    if inCharacterOrTool(part) or not onItsOwn(part) then return end
    local size=part.Size
    if math.max(size.X,size.Y,size.Z)>1.5 then return end
    local bombFling=runtime.BombFling
    if bombFling and type(bombFling.IsBomb)=="function" then
        local okBomb,bomb=pcall(bombFling.IsBomb,part)
        if okBomb and bomb then return end
    end
    local root=myRoot()
    local ok,distance=pcall(function() return (part.Position-root.Position).Magnitude end)
    if not ok or distance>8 then return end
    local count=0
    for _ in pairs(caps) do count=count+1 end
    if count>=2 then return end
    caps[part]={collide=part.CanCollide}
    pcall(function() part.CanCollide=false;part.LocalTransparencyModifier=0 end)
end
local function forgetCap(part)
    local saved=caps[part]
    if not saved then return end
    caps[part]=nil
    if part.Parent then pcall(function() part.CanCollide=saved.collide end) end
end
local function hookJar(tool)
    if not tool:IsA("Tool") or tool.Name~="Fireflies" or jar.hooked[tool] then return end
    jar.hooked[tool]=true
    -- (opened by you or by Firefly Clutch: its cooldown starts now; the auto use keeps its own time)
    tool.Activated:Connect(function()
        if jar.busy then return end
        jar.usedAt=os.clock();jar.waitingEnabled=true;jar.enabledBack=false
    end)
    -- (you taking the jar out yourself: the auto use keeps away from it for a while)
    tool.Equipped:Connect(function() if not jar.busy then jar.userAt=os.clock() end end)
    -- (the game switches the jar off while it recharges: back on means it's ready)
    tool:GetPropertyChangedSignal("Enabled"):Connect(function()
        if tool.Enabled and jar.waitingEnabled then jar.enabledBack=true end
    end)
end
local function jarTool()
    for _,container in ipairs({LocalPlayer.Character,LocalPlayer:FindFirstChildOfClass("Backpack")}) do
        local tool=container and container:FindFirstChild("Fireflies")
        if tool and tool:IsA("Tool") then hookJar(tool);return tool end
    end
end
local function jarReady(tool)
    if not tool or tool.Enabled==false then return false end
    if os.clock()<(jar.retryAt or 0) then return false end
    if jar.enabledBack then return true end
    -- (16 s like Firefly Clutch's timer, or longer once the jar has shown it needs longer)
    return os.clock()-jar.usedAt>=(jar.cooldown or JAR_COOLDOWN)
end
-- Uses the jar for you: taken out (hidden on your screen), opened, and held until the
-- fireflies are out (the jar takes a moment; putting it away sooner stops it), with the
-- jar's animations kept still; then back to exactly what you were holding (nothing, if you
-- held nothing). Opened again every 0.35 s while it doesn't open (it may be a moment from
-- ready), for at most 2.4 s. If you're using the jar yourself, or take out a tool of your
-- own meanwhile, it's left to you.
local HOLD=4.5
local function useJar()
    if jar.busy then return end
    local root,character=myRoot()
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    local backpack=LocalPlayer:FindFirstChildOfClass("Backpack")
    local tool=jarTool()
    if not root or not humanoid or humanoid.Health<=0 or not backpack or not jarReady(tool) then return end
    if tool.Parent~=backpack or os.clock()-(jar.userAt or -math.huge)<6 then return end
    jar.busy=true
    diagnostics.jarAttempts=diagnostics.jarAttempts+1
    task.spawn(function()
        runtime.FireflyAutoUseAt=os.clock()   -- (Firefly Clutch leaves this use alone)
        local held=nil
        for _,child in ipairs(character:GetChildren()) do
            if child:IsA("Tool") and child~=tool then held=child;break end
        end
        local hidden={}
        for _,part in ipairs(tool:GetDescendants()) do
            if part:IsA("BasePart") then hidden[part]=part.LocalTransparencyModifier;part.LocalTransparencyModifier=1 end
        end
        -- every animation that starts while the jar is in hand plays at zero weight (it still
        -- runs, so the jar works as usual, but nobody sees it); the jar's own one is stopped
        -- once the fireflies are out
        local stilled={}
        local opened=false
        local lastOpen,openedAt=nil,nil
        local animator=humanoid:FindFirstChildOfClass("Animator")
        local jarAnimation=tool:FindFirstChildWhichIsA("Animation")
        local function jarTrack(trackObject)
            local animation=trackObject.Animation
            return animation and jarAnimation and animation.AnimationId==jarAnimation.AnimationId
        end
        local function markOpened()
            if not opened then opened=true;openedAt=lastOpen or os.clock() end
        end
        local function still(trackObject)
            if jarTrack(trackObject) then markOpened()
            elseif trackObject.Priority==Enum.AnimationPriority.Core then return end
            stilled[trackObject]=true
            pcall(function() trackObject:AdjustWeight(0,0) end)
        end
        local watcher=animator and animator.AnimationPlayed:Connect(still)
        local disabled=tool:GetPropertyChangedSignal("Enabled"):Connect(function() if not tool.Enabled then markOpened() end end)
        local before=jar.spawnedAt
        local function out() return jar.spawnedAt>before end
        -- (you taking out another tool while the jar is in hand: it's yours, the jar stops)
        local switched=false
        local switchWatch=character.ChildAdded:Connect(function(child)
            if child:IsA("Tool") and child~=tool and child~=held then switched=true end
        end)
        local function putBack()
            if switched then return end
            -- back to what you held, if it's still yours; else empty-handed
            if held and held.Parent==character then
                if tool.Parent==character then pcall(function() tool.Parent=backpack end) end
            elseif held and held.Parent==backpack then pcall(function() humanoid:EquipTool(held) end)
            elseif tool.Parent==character then pcall(function() humanoid:UnequipTools() end) end
            -- (and the jar surely back in the backpack)
            if tool.Parent==character then pcall(function() tool.Parent=backpack end) end
        end
        pcall(function() humanoid:EquipTool(tool) end)
        local deadline=os.clock()+0.6
        while tool.Parent~=character and os.clock()<deadline and not switched do task.wait() end
        if tool.Parent==character and not switched then
            for _,trackObject in ipairs(animator and animator:GetPlayingAnimationTracks() or {}) do
                if trackObject.Priority~=Enum.AnimationPriority.Core then still(trackObject) end
            end
            task.wait(0.05)   -- (its own script sees it in hand first)
            local first=os.clock()
            local function open()
                lastOpen=os.clock()
                jar.usedAt=lastOpen;jar.waitingEnabled=true;jar.enabledBack=false
                pcall(function() tool:Activate() end)
            end
            open()
            while tool.Parent==character and not out() and os.clock()-first<HOLD and not switched do
                if not opened then
                    if os.clock()-first>(isMMV and 2.4 or 1.5) then break end
                    if os.clock()-lastOpen>=0.35 then open() end
                end
                task.wait(0.03)
            end
            if out() or opened then
                if out() then diagnostics.jarUses=diagnostics.jarUses+1 end
                -- (its cooldown counts from the opening that worked; if it was tried too early
                -- first, the jar's real cooldown is about the time since it last opened, so
                -- next time it's tried right then)
                local openedTime=openedAt or lastOpen or os.clock()
                if jar.lastSuccessAt and (jar.failures or 0)>0 then
                    jar.cooldown=math.clamp(openedTime-jar.lastSuccessAt-0.15,4,40)
                end
                jar.lastSuccessAt=openedTime
                diagnostics.jarCooldown=jar.cooldown or JAR_COOLDOWN
                jar.failures=0;jar.retryAt=nil
                jar.usedAt=openedTime
                if out() then task.wait(0.25) end   -- (all of them out)
            else
                -- it didn't open: tried again very soon, then less often
                jar.failures=(jar.failures or 0)+1
                jar.retryAt=os.clock()+math.min(8,0.6*2^(jar.failures-1))
                jar.usedAt=-math.huge
                -- (MM2: twice in a round (someone has the knife): the game doesn't let the jar be
                -- used during the round, so it isn't tried again until the round's over, and
                -- you're told so, once, as it starts)
                if not isMMV and jar.failures>=2 and roundOn() and not jar.roundBlocked then
                    jar.roundBlocked=true;jar.roundBlockedAt=os.clock()
                    pcall(shared.Notify,"Firefly Protection: the Firefly Jar can't be used during the round. Auto Use Firefly Jar waits until the round is over.",5)
                end
            end
            for trackObject in pairs(stilled) do
                if jarTrack(trackObject) then pcall(function() trackObject:Stop(0) end) end
            end
            putBack()
            -- (and Increase Inventory's Auto Get Tools puts your toys back in their slots, so
            -- the jar never ends up first)
            local tools=runtime.AutoGetTools
            if tools and type(tools.RequestOrder)=="function" then pcall(tools.RequestOrder) end
        else
            -- (it came out late, or not at all: whatever happens it doesn't stay in your hand)
            local late=os.clock()+1
            while tool.Parent~=character and os.clock()<late and not switched do task.wait() end
            if tool.Parent==character then putBack() end
        end
        if watcher then watcher:Disconnect() end
        disabled:Disconnect()
        switchWatch:Disconnect()
        for part,value in pairs(hidden) do pcall(function() part.LocalTransparencyModifier=value end) end
        jar.busy=false
    end)
end

-- ---------------------------------------------------------------- walls and attackers
local rayParams=RaycastParams.new()
rayParams.FilterType=Enum.RaycastFilterType.Exclude
-- (what the wall checks look through: everyone's character, the fireflies, the bombs kept out,
-- the camera; only rebuilt when one of those changes, or once a second, not every frame. The
-- bombs too: one in the shield is right in the way of the one it shields from, so they were
-- taken for out of sight behind it, and the shield turned away from them)
local filterKey,filterAt="",-math.huge
local function refreshFilter()
    local ignore={}
    local key={}
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr.Character then ignore[#ignore+1]=plr.Character;key[#key+1]=tostring(plr.Character) end
    end
    key[#key+1]=tostring(#list);key[#key+1]=tostring(list[#list])
    for part in pairs(caps) do key[#key+1]=tostring(part) end
    for index,slot in ipairs(SLOTS) do if slot.part then key[#key+1]="b"..index end end
    key=table.concat(key,"|")
    if key==filterKey and os.clock()-filterAt<1 then return end
    filterKey,filterAt=key,os.clock()
    for _,part in ipairs(list) do ignore[#ignore+1]=part end
    for part in pairs(caps) do ignore[#ignore+1]=part end
    for _,slot in ipairs(SLOTS) do
        local part=slot.part
        if part then
            ignore[#ignore+1]=part
            -- (a bomb in several pieces, as a model of its own)
            local holder=part.Parent
            if holder and holder~=workspace and (holder:IsA("Model") or holder:IsA("Tool")) and holder.Name:lower():find("bomb",1,true) then
                ignore[#ignore+1]=holder
            end
        end
    end
    local camera=workspace.CurrentCamera
    if camera then ignore[#ignore+1]=camera end
    rayParams.FilterDescendantsInstances=ignore
end
local function clear(from,to)
    local direction=to-from
    if direction.Magnitude<0.01 then return true end
    return workspace:Raycast(from,direction,rayParams)==nil
end
-- a spot behind a wall comes in to just in front of it
local function inFront(from,point)
    local direction=point-from
    if direction.Magnitude<0.01 then return point end
    local hit=workspace:Raycast(from,direction,rayParams)
    return hit and hit.Position-direction.Unit*0.4 or point
end
local function flat(vector)
    local v=Vector3.new(vector.X,0,vector.Z)
    return v.Magnitude>0.05 and v.Unit or nil
end
local function frameFacing(center,facing)
    local right=facing:Cross(Vector3.yAxis)
    right=right.Magnitude>0.01 and right.Unit or Vector3.xAxis
    return CFrame.fromMatrix(center,right,right:Cross(facing).Unit)
end

-- ---------------------------------------------------------------- thrown knives
local function knifePart(object)
    if object:IsA("BasePart") then return object end
    return object:FindFirstChild("KnifeVisual",true) or object:FindFirstChildWhichIsA("BasePart",true)
end
local function considerKnife(object)
    if knives[object] or not object.Parent then return end
    local name=object.Name:lower()
    if name:sub(1,9)=="visualsv2" then return end
    if name~="throwingknife" and name~="knifevisual" and not (object.Parent==workspace and name:find("knife",1,true)) then return end
    if object.Parent and object.Parent.Name:lower()=="throwingknife" then object=object.Parent end
    if knives[object] or inCharacterOrTool(object) then return end
    local part=knifePart(object)
    if not part then return end
    local now=os.clock()
    knives[object]={part=part,last=part.Position,at=now,lastMove=now}
end
-- (a knife that hit a firefly can end up stuck to it and carried along: that's no throw)
local function riding(part,position)
    local ok,attached=pcall(function()
        local assembly=part.AssemblyRootPart
        if assembly and assembly~=part and fireflies[assembly] then return true end
        for _,joint in ipairs(part:GetJoints()) do
            local other=joint.Part0==part and joint.Part1 or joint.Part0
            if other and fireflies[other] then return true end
        end
        return false
    end)
    if ok and attached then return true end
    -- (or kept right next to one that's back in its place round you; the ones put across a
    -- knife's path on purpose don't count)
    for _,firefly in ipairs(list) do
        if not blocking[firefly] and (firefly.Position-position).Magnitude<1 then return "near" end
    end
    return false
end
-- Every thrown knife followed, once a frame. A knife counts only while it flies: once it has
-- stopped moving (stuck in something, or blocked) for 0.3 s (0.6 s while the game still
-- gives it its speed), sat on a firefly for a moment, or flown longer than any throw, it's
-- done with, so the fireflies are back in place and ready for the next throw. (One that
-- later flies off again by itself is watched again.)
local function updateKnives(dt)
    for _,record in pairs(knives) do record.flying=false end
    local now=os.clock()
    for object,record in pairs(knives) do
        local part=record.part
        if not object.Parent or not part.Parent then knives[object]=nil
        else
            local position=part.Position
            -- (how it really moves, frame to frame, and the speed the game gives it, unless
            -- it's fixed in place: a stuck knife can still report the speed it was thrown with)
            local measured=dt>0 and (position-record.last)/math.max(dt,1/240) or Vector3.zero
            local reported=Vector3.zero
            pcall(function() if not part.Anchored then reported=part.AssemblyLinearVelocity end end)
            record.last=position
            local moving=measured.Magnitude>5
            if moving then record.lastMove=now end
            -- (the way it flies: the speed the game gives it when that agrees with how it
            -- moves (it's smoother), else as it moves, else the speed the game gives it; a little
            -- smoothed so the line across its path holds still; a sharp turn is taken at once)
            local raw=nil
            if moving and reported.Magnitude>5 then
                raw=reported.Unit:Dot(measured.Unit)>0.7 and reported.Unit or measured.Unit
            elseif moving then raw=measured.Unit
            elseif reported.Magnitude>5 then raw=reported.Unit end
            -- (MM2 puts the way a thrown knife flies on it, exactly, from the moment it leaves the
            -- hand: its Direction. Then that's the path, never a guess)
            local given=nil
            pcall(function()
                local value=part:GetAttribute("Direction")
                if typeof(value)=="Vector3" and value.Magnitude>0.5 then given=value.Unit end
            end)
            if given then
                if not record.heading or record.heading:Dot(given)<0.999 then record.length=nil end
                record.heading=given;record.headingAt=now;record.exact=true
            elseif raw then
                if record.heading and record.heading:Dot(raw)>0.9 then
                    local blended=record.heading:Lerp(raw,0.35)
                    record.heading=blended.Magnitude>0.01 and blended.Unit or raw
                else
                    record.heading=raw;record.length=nil
                end
                record.headingAt=now
            end
            local speed=math.max(measured.Magnitude,reported.Magnitude)
            local onFirefly=riding(part,position)
            if onFirefly then record.ridingSince=record.ridingSince or now else record.ridingSince=nil end
            local stuck=onFirefly==true or (record.ridingSince~=nil and now-record.ridingSince>0.2)
            -- (no movement seen for a moment: done with; out in the open with the game still
            -- giving it its speed, a short gap in its updates is waited out a little longer,
            -- but not up against a firefly put in its way: that's it blocked)
            local stillFor=now-record.lastMove
            local againstOne=false
            if reported.Magnitude>5 and stillFor>0.3 then
                for _,firefly in ipairs(list) do
                    if blocking[firefly] and (firefly.Position-position).Magnitude<1.2 then againstOne=true;break end
                end
            end
            if record.done then
                if moving and speed>40 and not onFirefly and now-record.done>0.2 then
                    record.done=nil;record.at=now;record.lastMove=now;record.length=nil;record.origin=position
                end
            elseif stuck or stillFor>((reported.Magnitude>5 and not againstOne) and 0.6 or 0.3) or now-record.at>2.5 then
                record.done=now
                diagnostics.knivesDone=diagnostics.knivesDone+1
            end
            record.flying=not record.done and speed>5
            record.position=position
            -- (where it was first seen: where it was thrown from, if nobody was by it)
            record.origin=record.origin or position
            record.direction=speed>5 and record.heading or nil
            if record.thrower==nil then
                -- (where the player it appeared right next to stood: thrown from their hand)
                record.thrower=false
                for _,plr in ipairs(Players:GetPlayers()) do
                    if plr~=LocalPlayer then
                        local other=aliveRoot(plr)
                        if other and (other.Position-position).Magnitude<7 then record.thrower=other.Position;break end
                    end
                end
            end
        end
    end
end
-- (another player with their knife raised to throw: MM2's ThrowCharge / ThrowHold playing on them)
local THROW_POSE={["1957618848"]=true,["15478370930"]=true}
local function aimingToThrow(plr)
    local character=plr and plr.Character
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return false end
    local animator=humanoid:FindFirstChildOfClass("Animator")
    local ok,tracks=pcall(function() return (animator or humanoid):GetPlayingAnimationTracks() end)
    if not ok or type(tracks)~="table" then return false end
    for _,track in ipairs(tracks) do
        local name,id="",nil
        pcall(function() name=tostring(track.Name):lower() end)
        if name:find("throwcharge",1,true) or name:find("throwhold",1,true) then return true end
        pcall(function() id=track.Animation and tostring(track.Animation.AnimationId):match("(%d+)%s*$") end)
        if id and THROW_POSE[id] then return true end
    end
    return false
end
-- (where their knife would leave from: the knife in their hand, else about their shoulder)
local function throwOrigin(threat)
    local character=threat.player.Character
    local held=character and character:FindFirstChildOfClass("Tool")
    local handle=held and held.Name:lower():find("knife",1,true) and held:FindFirstChild("Handle")
    if handle and handle:IsA("BasePart") and (handle.Position-threat.root.Position).Magnitude<6 then return handle.Position end
    return threat.root.Position+Vector3.new(0,1.5,0)
end
-- (their knife out, in their hand)
local function knifeInHand(plr)
    local character=plr and plr.Character
    local held=character and character:FindFirstChildOfClass("Tool")
    return held~=nil and held.Name:lower():find("knife",1,true)~=nil
end
-- How long before the game sees a firefly where it's just been moved: a thrown knife reaches
-- your screen your ping late and the firefly moved then reaches the game late again, so
-- about your ping (and a little for the frames in between). A knife thrown from closer than
-- it flies in that time (about 100 studs a second: the game gives it 96, on your screen it's a
-- bit more) gets there first, however quickly they're moved.
local KNIFE_SPEED=110
local ping={at=-math.huge,value=nil}
local function reactTime()
    local now=os.clock()
    if now-ping.at>0.5 then
        ping.at=now
        local ok,value=pcall(function() return LocalPlayer:GetNetworkPing() end)
        if ok and type(value)=="number" and value>0 and value<5 then
            ping.value=ping.value and ping.value+(value-ping.value)*0.5 or value
        end
    end
    return math.clamp(ping.value or 0.15,0.02,1.5)*1.2+0.06
end
local function pingText() return ("%d ms"):format(math.floor((ping.value or 0.15)*1000+0.5)) end
-- the knives flying at one body (yours, or someone in Knife Interception's area), nearest
-- first; seen from 60 studs off (Knife Interception: from 107)
local function knifeThreats(root,reach,guessAim)
    if guessAim==nil then guessAim=true end
    local farthest=math.clamp(60*(reach or 1),60,300)
    local center=root.Position+LIFT
    local threats={}
    local now=os.clock()
    for object,record in pairs(knives) do
        local part=record.part
        local position=record.position
        if not record.done and position and object.Parent and part.Parent then
            -- the way it flies: as measured; else the speed the game gives it; a knife just
            -- out of the hand of someone close by, not moving yet, is taken as aimed at the
            -- one protected (close up there's no time to wait and see); else the way it points
            local fromHand=guessAim and not record.exact and record.thrower and (record.thrower-center).Magnitude<25
            local direction
            if record.heading and now-(record.headingAt or 0)<0.3 then direction=record.heading
            elseif fromHand and now-record.at<0.2 and (center-position).Magnitude>0.5 then direction=(center-position).Unit
            else direction=part.CFrame.LookVector end
            local toMe=center-position
            local distance=toMe.Magnitude
            if distance<=farthest and distance>0.5 then
                local along=toMe:Dot(direction)
                local heading=along/distance
                if along>0 and heading>0.55 then
                    local closest=position+direction*along
                    if (center-closest).Magnitude<6 then
                        threats[#threats+1]={position=position,closest=closest,direction=direction,along=along,record=record,root=root}
                    end
                end
            end
        end
    end
    table.sort(threats,function(a,b) return a.along<b.along end)
    return threats
end
-- (Knife Interception: everyone in its area, you and every other player alive within the
-- 6 studs of you who doesn't have the knife; each knife once, for the first of them
-- it's on its way to)
local function areaThreats(me,radius,reach)
    local byRecord={}
    for _,threat in ipairs(knifeThreats(me,reach,true)) do byRecord[threat.record]=threat end
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LocalPlayer and role(plr)~="murderer" and not hasTool(plr,"knife") then
            local other=aliveRoot(plr)
            if other and (other.Position-me.Position).Magnitude<=radius then
                for _,threat in ipairs(knifeThreats(other,reach,false)) do
                    threat.player=plr
                    local first=byRecord[threat.record]
                    if not first or threat.along<first.along then byRecord[threat.record]=threat end
                end
            end
        end
    end
    local list={}
    for _,threat in pairs(byRecord) do list[#list+1]=threat end
    table.sort(list,function(a,b) return a.along<b.along end)
    return list
end
-- (how far out Knife Interception's rows go for a knife: 10 studs, for whoever it's at; and how
-- far off knives are seen for it: 60 studs)
local function threatReach() return settings.interceptStop end
local function interceptReach() return math.max(settings.interceptStop,INTERCEPT_STUDS)/INTERCEPT_STUDS end

-- ---------------------------------------------------------------- formations
-- the shield's rectangle (as before fixes-23): just enough columns and rows for the
-- fireflies there are, filled from the middle out
local function gridOffsets(count,width,height)
    local cells={}
    local columns=math.max(1,math.ceil(math.sqrt(count*width/height)))
    local rows=math.max(1,math.ceil(count/columns))
    local stepX=columns>1 and width/(columns-1) or 0
    local stepY=rows>1 and height/(rows-1) or 0
    for row=0,rows-1 do
        for column=0,columns-1 do
            cells[#cells+1]=Vector3.new(-width/2+column*stepX,-height/2+row*stepY+0.4,0)
        end
    end
    table.sort(cells,function(a,b) return a.Magnitude<b.Magnitude end)
    return cells
end
-- the rectangle's spots, then spare ones round it (used only where a wall takes a spot)
local function wallSpots(count,width,height)
    local spots={}
    for index,cell in ipairs(gridOffsets(count,width,height)) do
        if index>count then break end
        spots[#spots+1]=cell
    end
    for _,cell in ipairs(gridOffsets(count+10,width+1.2,height+1.2)) do
        local taken=false
        for index=1,count do if spots[index] and (spots[index]-cell).Magnitude<0.35 then taken=true;break end end
        if not taken then spots[#spots+1]=cell end
    end
    return spots
end
-- the ring aura (the idle orbit of before fixes-23): round you, each firefly rising and
-- falling on its own wave as they circle
local function orbitSpots(count,radius,speed,time)
    local spots={}
    for index=1,count do
        local angle=(index/math.max(count,1))*math.pi*2+time*speed
        -- (the wave keeps pace with the circling: speed 0 holds them still)
        local height=math.sin(time*speed*1.25+index)*1.2
        spots[#spots+1]=Vector3.new(math.cos(angle)*radius,height,math.sin(angle)*radius)
    end
    return spots
end
-- spots on rings round the body; gap = half-angle (radians) left open in front
local function ringSpots(count,radius,heights,spin,lookYaw,gap)
    gap=gap or 0
    local spots={}
    local perRing=math.max(1,math.ceil(count/#heights))
    local arc=2*math.pi-2*gap
    for ringIndex,height in ipairs(heights) do
        for index=1,perRing do
            -- measured from the way you face; an open gap is centred on it (then they sway
            -- to and fro instead of going round, so none ever crosses the open front)
            local around
            if gap>0 then
                around=arc*((index-0.5)/perRing)+math.sin(spin+ringIndex*0.7)*(arc/perRing)*0.45
            else
                around=arc*((index-0.5)/perRing)+spin+ringIndex*0.7
            end
            local yaw=lookYaw+gap+around
            spots[#spots+1]=Vector3.new(-math.sin(yaw)*radius,height,-math.cos(yaw)*radius)
        end
    end
    return spots
end
-- MMV: the original shield's square grid, facing the way the shot would come from
-- (facing: a unit vector, tilted up or down), right against your body. How far your body
-- reaches that way comes from your HumanoidRootPart (as wide as your arms, as deep as your
-- torso, scaled with you), so it's close on every side. Always a square (or as near as the
-- number of fireflies allows: 9 make 3 x 3, 12 make 4 x 3, 16 make 4 x 4, 25 the full
-- 5 x 5; a short last row is the corners left out, never a diamond); past 25, a second layer
-- just behind it, staggered so it covers the first one's gaps. (Offsets from your middle,
-- LIFT up.)
local shieldCellsFor={}
local function squareCells(count)
    local cached=shieldCellsFor[count]
    if cached then return cached end
    local columns=math.clamp(math.ceil(math.sqrt(count)),1,SHIELD.columns)
    local rows=math.clamp(math.ceil(count/columns),1,SHIELD.rows)
    local cells={}
    local width=(columns-1)*SHIELD.spacing
    local height=(rows-1)*SHIELD.spacing
    for row=0,rows-1 do
        for column=0,columns-1 do
            cells[#cells+1]=Vector2.new(column*SHIELD.spacing-width/2,row*SHIELD.spacing-height/2)
        end
    end
    -- (the middle first, the corners last: those are the ones left out of a short grid)
    table.sort(cells,function(a,b) return a.Magnitude<b.Magnitude end)
    shieldCellsFor[count]=cells
    return cells
end
-- (with the Fake Bomb in the middle of the shield: every firefly in a closed frame right round
-- its broad side, just clear of its edges, in the same plane as it: one on each corner, the
-- rest spread evenly along the sides (the long sides get more), as close together as there
-- are fireflies for. As many as fit a frame that tightly (no two closer than FRAME_GAP), the
-- rest in a second frame round that, and so on)
local FRAME_MARGIN=0.16     -- from the bomb's edge to a firefly's middle
local FRAME_GAP=0.22        -- the closest two fireflies in a frame come
local function frameCells(count,halfWidth,halfHeight)
    local cells={}
    if count<4 then
        local middles={Vector2.new(0,halfHeight),Vector2.new(0,-halfHeight),Vector2.new(halfWidth,0),Vector2.new(-halfWidth,0)}
        for index=1,count do cells[index]=middles[index] end
        return cells
    end
    local corners={Vector2.new(-halfWidth,halfHeight),Vector2.new(halfWidth,halfHeight),Vector2.new(halfWidth,-halfHeight),Vector2.new(-halfWidth,-halfHeight)}
    for _,corner in ipairs(corners) do cells[#cells+1]=corner end
    -- (the rest shared between the sides by how long they are: top, bottom, right, left; any
    -- left over to the side with the most room per firefly, the top first)
    local rest=count-4
    local lengths={2*halfWidth,2*halfWidth,2*halfHeight,2*halfHeight}
    local perimeter=4*(halfWidth+halfHeight)
    local shares,given={},0
    for index,length in ipairs(lengths) do shares[index]=math.floor(rest*length/perimeter);given=given+shares[index] end
    while given<rest do
        local best,bestRoom=1,-math.huge
        for index,length in ipairs(lengths) do
            local room=length/(shares[index]+1)
            if room>bestRoom+1e-6 then best,bestRoom=index,room end
        end
        shares[best]=shares[best]+1;given=given+1
    end
    local function along(from,to,n)
        for k=1,n do cells[#cells+1]=from:Lerp(to,k/(n+1)) end
    end
    along(corners[1],corners[2],shares[1])
    along(corners[4],corners[3],shares[2])
    along(corners[2],corners[3],shares[3])
    along(corners[1],corners[4],shares[4])
    return cells
end
local aroundCellsFor={}
local function aroundCells(count,width,height)
    local key=count..":"..math.floor(width*100+0.5)..":"..math.floor(height*100+0.5)
    local cached=aroundCellsFor[key]
    if cached then return cached end
    local cells={}
    local frame,left=0,count
    while left>0 do
        local halfWidth=width/2+FRAME_MARGIN+frame*SHIELD.spacing
        local halfHeight=height/2+FRAME_MARGIN+frame*SHIELD.spacing
        local fits=math.max(4,math.floor(4*(halfWidth+halfHeight)/FRAME_GAP))
        local here=math.min(left,fits)
        for _,cell in ipairs(frameCells(here,halfWidth,halfHeight)) do cells[#cells+1]=cell end
        left=left-here
        frame=frame+1
    end
    aroundCellsFor[key]=cells
    return cells
end
-- (round every bomb in the shield: the frame round all of them together (as wide as the widest,
-- or the pair side by side, from the lowest one's bottom to the highest one's top), a row across
-- each gap between one and the next too, if there's room for one just clear of both, and with
-- bombs side by side (three in a triangle) a few in the corners of the frame no bomb covers)
local holeCellsFor={}
local function holeCells(count,holes)
    local keys={tostring(count)}
    for _,hole in ipairs(holes) do keys[#keys+1]=string.format("%.2f,%.2f,%.2f,%.2f",hole.width,hole.height,hole.y,hole.x or 0) end
    local key=table.concat(keys,"|")
    local cached=holeCellsFor[key]
    if cached then return cached end
    local left,right,low,high=math.huge,-math.huge,math.huge,-math.huge
    local sideBySide=false
    for _,hole in ipairs(holes) do
        local x=hole.x or 0
        if math.abs(x)>0.01 then sideBySide=true end
        left=math.min(left,x-hole.width/2);right=math.max(right,x+hole.width/2)
        low=math.min(low,hole.y-hole.height/2);high=math.max(high,hole.y+hole.height/2)
    end
    local halfWidth=(right-left)/2
    local midX,mid=(left+right)/2,(low+high)/2
    -- (the gaps between one bomb and the next, each with room for a row just clear of both)
    local sorted=table.clone(holes)
    table.sort(sorted,function(a,b) return a.y<b.y end)
    local gaps={}
    for k=1,#sorted-1 do
        local gapLow,gapHigh=sorted[k].y+sorted[k].height/2,sorted[k+1].y-sorted[k+1].height/2
        if gapHigh-gapLow>=2*FRAME_MARGIN then gaps[#gaps+1]=(gapLow+gapHigh)/2 end
    end
    -- (side by side: the spots inside the frame just clear of every bomb (each taken as round), on a
    -- small grid; for three in a triangle, the two lower corners beside the one under the pair)
    local pockets={}
    if sideBySide then
        local step=SHIELD.spacing*0.6
        for y=low+FRAME_MARGIN,high-FRAME_MARGIN+1e-6,step do
            for x=left+FRAME_MARGIN,right-FRAME_MARGIN+1e-6,step do
                local free=true
                for _,hole in ipairs(holes) do
                    local dx=(x-(hole.x or 0))/(hole.width/2+FRAME_MARGIN)
                    local dy=(y-hole.y)/(hole.height/2+FRAME_MARGIN)
                    if dx*dx+dy*dy<1 then free=false;break end
                end
                if free then pockets[#pockets+1]=Vector2.new(x,y) end
            end
        end
    end
    local frameWidth=2*(halfWidth+FRAME_MARGIN)
    local inFrame,inGap,inPocket=count,0,0
    if #gaps>0 and count>=8 then
        local perimeter=2*(2*halfWidth+(high-low))+8*FRAME_MARGIN
        inGap=math.floor(count*frameWidth*#gaps/(perimeter+frameWidth*#gaps)+0.5)
        inFrame=count-inGap
        if inFrame<4 then inFrame=math.min(count,4);inGap=count-inFrame end
    end
    -- (about a fifth of the frame's to the corners, the frame keeping 4 at least)
    if #pockets>0 and count>=8 then
        inPocket=math.min(#pockets,math.floor(inFrame*0.2+0.5),math.max(inFrame-4,0))
        inFrame=inFrame-inPocket
    end
    local cells={}
    for _,cell in ipairs(aroundCells(inFrame,2*halfWidth,high-low)) do cells[#cells+1]=Vector2.new(cell.X+midX,cell.Y+mid) end
    -- (the rest shared between the gaps, as evenly as they go)
    for index,gapY in ipairs(gaps) do
        local here=math.floor(inGap/#gaps)+(index<=inGap%#gaps and 1 or 0)
        for k=1,here do cells[#cells+1]=Vector2.new(midX-frameWidth/2+frameWidth*k/(here+1),gapY) end
    end
    -- (and the corners' share spread evenly over their spots)
    for k=1,inPocket do cells[#cells+1]=pockets[math.floor((k-0.5)*#pockets/inPocket)+1] end
    holeCellsFor[key]=cells
    return cells
end
-- (minOut: at least that far out, as the bombs on their own are when they face much the same
-- way as the fireflies' grid, so they're past it and never in it)
local function shieldSpots(count,root,facing,time,holes,minOut)
    local shieldCells=holes and holeCells(count,holes) or squareCells(math.min(count,SHIELD.rows*SHIELD.columns))
    -- how far your body reaches toward them, measured in your own facing
    local size=root.Size
    local halfWidth,halfDepth=math.clamp(size.X,1,4),math.clamp(size.Z/2,0.3,1.5)
    local flatFacing=Vector3.new(facing.X,0,facing.Z)
    flatFacing=flatFacing.Magnitude>0.01 and flatFacing.Unit or root.CFrame.LookVector
    local localFacing=root.CFrame:VectorToObjectSpace(flatFacing)
    local reach=math.abs(localFacing.X)*halfWidth+math.abs(localFacing.Z)*halfDepth
    -- (closer than that with Shield Distance under 2, but never inside your torso itself)
    local character=root.Parent
    local torso=character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))
    local torsoSize=torso and torso:IsA("BasePart") and torso.Size or size
    local torsoReach=math.abs(localFacing.X)*torsoSize.X/2+math.abs(localFacing.Z)*torsoSize.Z/2
    local halfGrid=(SHIELD.rows-1)*SHIELD.spacing/2
    -- (round the bombs, as tall as they and their frames are)
    if holes then
        for index=1,math.min(count,#shieldCells) do halfGrid=math.max(halfGrid,math.abs(shieldCells[index].Y)) end
        for _,hole in ipairs(holes) do halfGrid=math.max(halfGrid,math.abs(hole.y)+hole.height/2) end
    end
    -- (tilted, the grid's top or bottom leans in: moved out just enough to stay off you)
    local tilt=math.abs(facing.Y)*halfGrid
    local right=facing:Cross(Vector3.yAxis)
    right=right.Magnitude>0.01 and right.Unit or Vector3.xAxis
    local up=right:Cross(facing).Unit
    local base=math.max(reach+settings.shieldGap,math.min(reach,torsoReach))+tilt
    -- (round the bombs: as far out as keeps their backs off you, tilted or not, the fireflies
    -- round them going with them)
    if holes then
        local thick,tall=0,0
        for _,hole in ipairs(holes) do thick=math.max(thick,hole.thick);tall=math.max(tall,math.abs(hole.y)+hole.height/2) end
        base=math.max(base,math.max(reach,torsoReach)+thick/2+math.abs(facing.Y)*tall+0.05)
    end
    if minOut then base=math.max(base,minOut) end
    local spots={}
    for index=1,count do
        local cell=shieldCells[(index-1)%#shieldCells+1]
        local layer=math.floor((index-1)/#shieldCells)
        local stagger=layer%2==1 and SHIELD.spacing/2 or 0
        local jiggle=Vector3.new(math.sin(time*7+index*1.7),math.cos(time*6.3+index*2.3),math.sin(time*5.1+index*0.9))*0.03
        local out=flatFacing*(base+layer*0.3)
        spots[#spots+1]=out+right*(cell.X+stagger)+up*(cell.Y+stagger)+Vector3.new(0,SHIELD.height,0)-LIFT+jiggle
    end
    -- (and its middle, where the bombs go, which ways are up and across in it, and how far out it is)
    return spots,flatFacing*base+Vector3.new(0,SHIELD.height,0)-LIFT,up,right,base
end
-- (each bomb in the shield: its broad side's size as it looks (its mesh's scale counted, so the
-- fireflies go round all of it), and where it goes from your middle: one alone at your middle;
-- two, the first at your upper body and the other at your legs, never overlapping; three, an
-- upside-down triangle: two side by side at your chest, the third nested in close under the
-- middle of them at your waist. None of them ever down in the ground)
local function bombLook(part)
    local size=part.Size
    pcall(function()
        local mesh=part:FindFirstChildOfClass("SpecialMesh")
        if mesh and mesh.MeshType==Enum.MeshType.FileMesh then
            local scale=mesh.Scale
            size=Vector3.new(size.X*math.clamp(scale.X,1,2),size.Y*math.clamp(scale.Y,1,2),size.Z*math.clamp(scale.Z,1,2))
        end
    end)
    local sides={size.X,size.Y,size.Z}
    table.sort(sides)
    return sides[3],sides[2],sides[1]
end
local function bombHoles(slots,root)
    local holes={}
    for _,slot in ipairs(slots) do
        local width,height,thick=bombLook(slot.part)
        holes[#holes+1]={width=width,height=height,thick=thick,x=0,y=0}
    end
    if #holes>=2 then
        local character=root.Parent
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        local torso=character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))
        local upper=0.6
        if torso and torso:IsA("BasePart") then upper=math.clamp(torso.Position.Y-root.Position.Y,-0.5,1.5) end
        local drop=3
        pcall(function() if humanoid and humanoid.RigType==Enum.HumanoidRigType.R15 then drop=root.Size.Y/2+humanoid.HipHeight end end)
        if #holes==3 then
            -- (three: an upside-down triangle, close together (0.04 apart): the first two side by
            -- side, the third under the middle of them, nested in as round things stack, the
            -- whole of it centred a little over your torso's middle)
            local a,b,c=holes[1],holes[2],holes[3]
            local spread=(a.width+b.width)/2+0.04
            a.x,b.x=-spread/2,spread/2
            local apart=(math.max(a.width+a.height,b.width+b.height)+c.width+c.height)/4+0.04
            local rise=math.sqrt(math.max(apart*apart-(spread/2)^2,(apart/2)^2))
            local middle=math.clamp(upper*0.5,0,0.8)+0.2
            a.y,b.y,c.y=middle+rise/2,middle+rise/2,middle-rise/2
        else
            local top,bottom=holes[1],holes[#holes]
            top.y,bottom.y=upper,-(drop+root.Size.Y/2)/2
            -- (never overlapping: spread apart evenly round their middle when they would)
            local need=0
            for k=1,#holes-1 do need=need+(holes[k].height+holes[k+1].height)/2+0.05 end
            if top.y-bottom.y<need then
                local middle=(top.y+bottom.y)/2
                top.y,bottom.y=middle+need/2,middle-need/2
            end
        end
        -- (never down in the ground: all of them raised together if the lowest would be)
        local lowest=math.huge
        for _,hole in ipairs(holes) do lowest=math.min(lowest,hole.y-hole.height/2) end
        local floor=-drop+0.15
        if lowest<floor then for _,hole in ipairs(holes) do hole.y=hole.y+(floor-lowest) end end
    end
    return holes
end
-- Follow Mouse follows only where you point on purpose: a tap on the screen, a finger held
-- still on it, or the mouse clicked / held and dragged. A finger that moves off at once is
-- turning the camera, and the joystick and jump button are moving you: neither counts.
-- The fireflies stay at the last spot until 4 s after the last tap or drag.
local pointer={touches={},mouseDown=false,lastAt=-math.huge,lastWorld=nil,pendingTap=nil,connections={}}
do
local LINGER=4
local TAP_MOVE=12       -- pixels a finger may move and still be a tap / a held finger
local HOLD_STILL=0.35   -- a finger held still this long follows (and may then move)
local TAP_TIME=0.45     -- a quick touch, let go within this, is a tap
local function onTouchControls(position)
    local ok,inside=pcall(function()
        local playerGui=LocalPlayer:FindFirstChildOfClass("PlayerGui")
        local touchGui=playerGui and playerGui:FindFirstChild("TouchGui")
        if not touchGui then return false end
        for _,name in ipairs({"DynamicThumbstickFrame","ThumbstickFrame","JumpButton"}) do
            local frame=touchGui:FindFirstChild(name,true)
            if frame and frame:IsA("GuiObject") and frame.Visible then
                local at,size=frame.AbsolutePosition,frame.AbsoluteSize
                if position.X>=at.X and position.X<=at.X+size.X and position.Y>=at.Y and position.Y<=at.Y+size.Y then return true end
            end
        end
        return false
    end)
    return ok and inside==true
end
local function watchPointer()
    if #pointer.connections>0 then return end
    local touchType,mouseType=Enum.UserInputType.Touch,Enum.UserInputType.MouseButton1
    pointer.connections[1]=UserInput.InputBegan:Connect(function(input,processed)
        if input.UserInputType==touchType then
            local position=Vector2.new(input.Position.X,input.Position.Y)
            -- (the joystick, the jump button and the menus are left alone)
            if processed or onTouchControls(position) then return end
            pointer.touches[input]={start=position,position=position,at=os.clock(),drag=false,held=false}
        elseif input.UserInputType==mouseType and not processed then
            -- (not the add-on's own tap on the screen, throwing the Fake Bomb)
            if os.clock()<(fakeBomb.tappingUntil or 0) then return end
            pointer.mouseDown=true;pointer.lastAt=os.clock()
        end
    end)
    pointer.connections[2]=UserInput.InputChanged:Connect(function(input)
        local touch=pointer.touches[input]
        if not touch then return end
        touch.position=Vector2.new(input.Position.X,input.Position.Y)
        -- (moving off before it was held still: turning the camera)
        if not touch.held and (touch.position-touch.start).Magnitude>TAP_MOVE then touch.drag=true end
    end)
    pointer.connections[3]=UserInput.InputEnded:Connect(function(input)
        local touch=pointer.touches[input]
        if touch then
            pointer.touches[input]=nil
            if not touch.drag then
                if touch.held then pointer.lastAt=os.clock()
                elseif os.clock()-touch.at<=TAP_TIME then pointer.pendingTap={position=touch.position,at=os.clock()} end
            end
