        if part and (not bombAlive(part) or not slotWanted(slot) or not bombsActive() or not bombAllowed() or bombFlinging()) then
            releaseBomb(slot);part=nil
        end
        if part then
            if owned(part) then slot.notOursSince=nil;slot.owned=true
            else
