                if os.clock()-slot.notOursSince>0.6 then slot.owned=false end
            end
            -- (never solid on your screen: they can't push you, or each other)
            if part.CanCollide then pcall(function() part.CanCollide=false end) end
            bombs[#bombs+1]=slot
