    diagnostics.fakeBomb=fakeBomb.part~=nil
    diagnostics.goldBomb=goldOut>0;diagnostics.goldBombs=goldOut
    -- (no bomb is one of the formation, so it never takes a firefly's place: where each goes,
    -- and which way it faces, is worked out on its own as the formation is. The first of them
    -- (the Fake Bomb, if it's out) is the one that goes to a knife)
    local bomb=bombs[1] and bombs[1].part or nil
    local knifeStack=nil
    local bombPlaces={}
    diagnostics.bombMiddle=false
    local lookYaw=math.atan2(-root.CFrame.LookVector.X,-root.CFrame.LookVector.Z)
    -- (a spot in a knife's way goes to the nearest firefly)
    local function take(point)
        local best,bestIndex,bestDistance=nil,nil,math.huge
        for index,part in ipairs(free) do
            local distance=(part.Position-point).Magnitude
            if distance<bestDistance then best,bestIndex,bestDistance=part,index,distance end
        end
        if best then targets[best]=point;solid[best]=true;table.remove(free,bestIndex) end
        return best
    end
    local close={}
    if not isMMV then
        for _,threat in ipairs(near) do
            if threat.seen or threat.distance<=NEAR then close[#close+1]=threat end
        end
    end
    local needed=#close>0
    -- thrown knives first
    local kind=nil
    local active=false
    local watchKnives=(mode.shield or mode.intercept or mode.sky or mode.murderer) and (isMMV or #near>0)
    if watchKnives and #knivesComing>0 then
        local threat=knivesComing[1]
        if isMMV then
            -- the original MMV shield: all of them onto the knife itself
            local count=#free
            for n=1,count do
                local angle=(2*math.pi/count)*(n-1)
                take(threat.position+Vector3.new(math.cos(angle)*0.15,math.sin(angle)*0.15,0))
            end
            -- (every bomb out waiting where it would hit you, right on its line, one just behind
            -- another, their broad sides to it, still, as Knife Shield's fireflies wait for it)
            local miss=(center-threat.closest).Magnitude
            local body=1.6*settings.blockScale
            local depth=math.sqrt(math.max(0,body*body-miss*miss))
            knifeStack={impact=threat.closest-threat.direction*(depth+0.8*settings.blockScale),direction=threat.direction}
            diagnostics.lastImpact=knifeStack.impact
            kind="on the knife"
        else
            -- Knife Shield: every firefly to the spot it would hit (whoever it's at)
            local spots,impact=nil,nil
            local threatCenter=threat.root and threat.root.Position+LIFT or center
            if mode.shield then spots,impact=clusterSpots(threat,threatCenter,#free) end
            if spots then
                for _,point in ipairs(spots) do if #free==0 then break end;take(point) end
                diagnostics.lastImpact=impact
                kind="blocking a knife"
            else
                -- Knife Interception: every one of them along its path, between it and the one it's
                -- at, out to 10 studs. They stay put while it comes, so it flies into them. (Hidden
                -- Knife Interception: every one of them, at a fixed range round you: the Firefly
                -- Distance, twice over, out to 2.6 studs further)
                local studs=threatReach(threat)
                local fixedAt=mode.sky and settings.distance*settings.blockScale or nil
                local count=#free
                local rows=interceptPoints(threat,count,studs,fixedAt)
                for _,point in ipairs(rows) do take(point) end
                kind=mode.shield and "blocking a knife" or (threat.player and ("intercepting a knife at "..threat.player.Name) or "intercepting a knife")
            end
        end
        if kind then
            active=true
            diagnostics.intercepts=diagnostics.intercepts+1
        end
    end

    -- (every MM2 mode: a murderer in sight with the knife raised to throw, facing the one
    -- protected, gets the fireflies put where the knife would come before it's thrown, so the
    -- game already has them there when it flies: what the game sees of a firefly is a moment
    -- behind your screen, and a knife from close by is faster than that)
    -- (Hidden Knife Interception stays up high until the knife is thrown)
    local aimer=nil
    if not isMMV and not active and (mode.shield or mode.intercept) and not mode.sky and not mineKnife then
        for _,threat in ipairs(near) do
            if threat.seen and threat.distance<=80 and aimingToThrow(threat.player) then
                local look=flat(threat.root.CFrame.LookVector)
                local toward=flat(center-threat.root.Position)
                if look and toward and look:Dot(toward)>0.5 then aimer=threat;break end
            end
        end
    end
    -- (and Knife Shield and Knife Interception: anyone in sight with their knife out who's too
    -- close for the fireflies to get there in time once they throw, at your ping: they wait on
    -- its way already, wound up or not)
    local tooClose=false
    if not aimer and not isMMV and not active and (mode.shield or mode.intercept) and not mineKnife then
        local need=reactTime()
        local blockAt=(mode.shield and 2.4 or 2.2)*settings.blockScale
        diagnostics.readyRange=blockAt+need*KNIFE_SPEED
        for _,threat in ipairs(near) do
            if threat.seen and knifeInHand(threat.player) then
                local from=throwOrigin(threat)
                if ((center-from).Magnitude-blockAt)/KNIFE_SPEED<need then aimer=threat;tooClose=true;break end
            end
        end
    end
    diagnostics.ping=ping.value
    diagnostics.aimer=aimer and aimer.player.Name or nil
    local function readyLabel()
        if tooClose then return "ready for "..aimer.player.Name.." (too close to react at "..pingText().." ping)" end
        return "ready for a throw from "..aimer.player.Name
    end
    -- (the path a throw from them would take: from the knife in their hand to the one
    -- protected, a knife's path before there is one)
    local virtualThrow=nil
    local function readyFor(threat)
        if virtualThrow==nil then
            virtualThrow=false
            local from=throwOrigin(threat)
            local toward=center-from
            if toward.Magnitude>0.5 then
                virtualThrow={position=from,direction=toward.Unit,along=toward.Magnitude,closest=center,root=root}
            end
        end
        return virtualThrow or nil
    end
    -- (Follow Mouse: only while you point, and never while they're needed to defend: an
    -- attacker in sight or near, or a knife on its way, takes them back at once, and the
    -- spot you tapped is forgotten, so afterwards they're back as they were, not at that spot)
    local defending=watchKnives and #knivesComing>0
    if isMMV then
        local gunHolder=mode.shield and near[1]
        defending=defending or (gunHolder~=nil and gunHolder~=false and (gunHolder.seen or gunHolder.distance<MMV_FAR))
        -- (Protect Against Murderer: the murderer in sight, or near even behind a wall)
        local murderer=mode.murderer and murderersNear[1]
        defending=defending or (murderer~=nil and murderer~=false and (murderer.seen or murderer.distance<NEAR))
    else
        defending=defending or ((mode.shield or mode.intercept) and #close>0)
    end
    diagnostics.defending=defending
    -- (Follow Mouse comes after the protection modes: while one is on and someone who could
    -- hurt you is within 200 studs, the fireflies stay on guard, so you know you're
    -- protected; it's only for when there's nobody to protect you from)
    local guarded=((mode.shield or mode.intercept or mode.sky) and #near>0) or (mode.murderer and #murderersNear>0)
    local pointAt=nil
    if defending or guarded then pointer.cancel()
    elseif settings.mouse then pointAt=pointer.world(center) end
    -- the rest: the formation for the situation
    local spots=nil
    local grid=false
    local count=#free
    local orbit=false
    local swarm=false
    local sky=false
    local ready=false
    local function idle(radius,speed,label)
        if pointAt then
            swarm=true
            kind=kind or "following the mouse"
            return swarmSpots(count,pointAt,center,clock)
        end
        orbit=true
        kind=kind or label
        return orbitSpots(count,radius,speed,clock)
    end
    -- (nothing for them to do: they circle you only with Firefly Ring Aura on, or standing by
    -- while a protection mode is on and someone who could hurt you is within 200 studs (MM2:
    -- not once you're dead and out in the lobby); otherwise they wait high up over you, hidden,
    -- as Hidden Knife Interception's do. Follow Mouse while you point, as ever)
    local function rest(radius,speed,label)
        local standby=guarded
        if standby and not isMMV and type(roundData)=="table" then
            local mine=roundData[LocalPlayer.Name]
            if type(mine)=="table" and (mine.Dead==true or mine.Killed==true) and not roundArea.inMap(me.Position) then standby=false end
        end
        if pointAt or settings.ring or standby then return idle(radius,speed,label) end
        sky=true
        kind=kind or "waiting up high"
        return skySpots(count,clock)
    end
    -- (hidden and far: round you, as Knife Shield does)
    local function roundYou()
        kind=kind or "behind a wall (far, all round you)"
        return ringSpots(count+8,settings.distance,{1.2,0,-1},clock*1.6,lookYaw)
    end
    if isMMV then
        -- who the shield turns to: the murderer (Protect Against Murderer) first, then the one
        -- with the gun (Gun Shield), while they're after you: in sight (the murderer from up to
        -- 250 studs), or near even behind a wall (40 studs for the knife, 80 for the gun). Both
        -- after you, it's split: the bombs (they stop knives) turn to the murderer on their own,
        -- and the fireflies (they only stop shots) keep their usual grid on the one with the gun.
        local gunHolder=mode.shield and near[1] or nil
        local gunPressing=gunHolder~=nil and (gunHolder.seen or gunHolder.distance<MMV_FAR)
        local murderer=mode.murderer and murderersNear[1] or nil
        local murdererPressing=murderer~=nil and (murderer.seen or murderer.distance<NEAR)
        local split=murdererPressing and gunPressing
        local from=nil
        if split then from=gunHolder
        elseif murdererPressing then from=murderer
        elseif gunPressing then from=gunHolder end
        -- (the way to them from you, tilted up or down to them, 60 degrees at most)
        local function facingTo(threat)
            local direction=threat.root.Position+Vector3.new(0,1.5,0)-center
            local horizontal=flat(direction) or root.CFrame.LookVector
            local pitch=math.clamp(math.atan2(direction.Y,Vector3.new(direction.X,0,direction.Z).Magnitude),math.rad(-60),math.rad(60))
            return (horizontal*math.cos(pitch)+Vector3.new(0,math.sin(pitch),0)).Unit
        end
        if from then
            -- the grid turned to them, wherever they are, following them smoothly, right against
            -- your body on that side
            local facing=facingTo(from)
            smoothDirection=smoothDirection and smoothDirection:Lerp(facing,math.clamp(FOLLOW*dt,0,1)) or facing
            if smoothDirection.Magnitude<0.01 then smoothDirection=facing end
            -- (the bombs out in the middle of the shield the whole time it's up, their broad
            -- sides to them, still: one alone at your middle; two, at your upper body and your
            -- legs; three, an upside-down triangle at your chest and waist; every firefly in a
            -- closed frame round them in the same plane (and across the gaps between them), none
            -- in front of them or behind. Split, the bombs are a shield of their own on the
            -- murderer's side (past the grid if that's much the same side), the fireflies the
            -- usual grid. A knife at you: all of them where it would hit you)
            local holes=#bombs>0 and bombHoles(bombs,root) or nil
            local bombMiddle,bombUp,bombRight,bombFacing=nil,nil,nil,smoothDirection.Unit
            if split then
                local gridSpots,_,_,_,gridBase=shieldSpots(count,root,smoothDirection.Unit,clock,nil)
                spots=gridSpots
                if holes then
                    local toMurderer=facingTo(murderer)
                    smoothBombDirection=(smoothBombDirection or smoothDirection):Lerp(toMurderer,math.clamp(FOLLOW*dt,0,1))
                    if smoothBombDirection.Magnitude<0.01 then smoothBombDirection=toMurderer end
                    bombFacing=smoothBombDirection.Unit
                    local minOut=nil
                    local bombsWay,gridWay=flat(bombFacing),flat(smoothDirection)
                    if bombsWay and gridWay and bombsWay:Dot(gridWay)>0.5 then
                        local thick=0
                        for _,hole in ipairs(holes) do thick=math.max(thick,hole.thick) end
                        minOut=gridBase+thick/2+0.3
                    end
                    _,bombMiddle,bombUp,bombRight=shieldSpots(0,root,bombFacing,clock,holes,minOut)
                else
                    smoothBombDirection=nil
                end
                kind=kind or ("bombs on the murderer, "..murderer.player.Name..", fireflies on "..gunHolder.player.Name)
            else
                smoothBombDirection=nil
                spots,bombMiddle,bombUp,bombRight=shieldSpots(count,root,smoothDirection.Unit,clock,holes)
                if holes then diagnostics.bombMiddle=true end
                kind=kind or ((from==murderer and "shielding from the murderer, " or "shielding from ")..from.player.Name)
            end
            if holes and bombMiddle and not knifeStack then
                for index,slot in ipairs(bombs) do
                    local hole=holes[index]
                    bombPlaces[slot]={at=center+bombMiddle+bombUp*hole.y+bombRight*hole.x,facing=bombFacing}
                end
            end
            grid=true
            active=true
        elseif gunHolder and count>0 then
            if pointAt then
                -- (hidden and far: not needed, so Follow Mouse while you point)
                spots=idle(settings.ringDistance,settings.ringSpeed*0.6,"ring aura")
            else
                -- (hidden and far: the ring aura round you)
                orbit=true
                spots=orbitSpots(count,settings.ringDistance,settings.ringSpeed*0.6,clock)
                kind=kind or "behind a wall (far): ring aura"
            end
        elseif count>0 then
            spots=rest(settings.ringDistance,settings.ringSpeed*0.6,"ring aura")
        end
    elseif count>0 then
        if mode.shield and #near>0 and (needed or not pointAt) then
            local murderer=near[1]
            active=true
            if mineKnife then
                -- Assassin: round you, your front left open for your own knife
                spots=ringSpots(count+8,settings.distance,{1.5,0.3,-1.2},clock*1.8,lookYaw,math.rad(55))
                kind=kind or "assassin (front open)"
            elseif #near>=2 then
                spots=ringSpots(count+8,settings.distance,{1.5,0.3,-1.2},clock*1.8,lookYaw)
                kind=kind or (#near.." knives (all round you)")
            elseif aimer and readyFor(aimer) then
                -- (the murderer winding up a throw: every firefly where the knife would hit,
                -- as for a knife in the air, already there when it's thrown)
                local virtual=readyFor(aimer)
                spots={}
                for _,point in ipairs((clusterSpots(virtual,center,count))) do spots[#spots+1]=point-center end
                ready=true
                kind=kind or readyLabel()
            else
                local aim=murderer.root.Position+Vector3.new(0,1,0)
                if murderer.seen or murderer.distance<=NEAR then
                    -- in front of you, facing them, tilted up or down to where they are
                    local direction=(aim-center)
                    local horizontal=flat(direction) or root.CFrame.LookVector
                    local pitch=math.clamp(math.atan2(direction.Y,Vector3.new(direction.X,0,direction.Z).Magnitude),math.rad(-60),math.rad(60))
                    local facing=(horizontal*math.cos(pitch)+Vector3.new(0,math.sin(pitch),0)).Unit
                    smoothDirection=smoothDirection and smoothDirection:Lerp(facing,math.clamp(FOLLOW*dt,0,1)) or facing
                    if smoothDirection.Magnitude<0.01 then smoothDirection=facing end
                    local frame=frameFacing(center,smoothDirection.Unit)
                    spots={}
                    local away=direction.Magnitude
                    -- (where the wall stays yours: in front of you, pulled in when they're near
                    -- enough to take it)
                    local wallAt=settings.distance*settings.blockScale
                    local out=smoothDirection.Unit
                    if not own.mine(center+out*wallAt) then
                        while wallAt>0.8 and not own.mine(center+out*wallAt) do wallAt=wallAt-0.2 end
                        wallAt=math.max(wallAt,0.8)
                    end
                    -- (sized to what of you they can aim at from there: the closer they are,
                    -- the smaller and denser, so close up there are no gaps to throw through)
                    local scale=math.clamp((away-wallAt)/math.max(away,0.1),0.45,1)
                    for _,cell in ipairs(wallSpots(count,3.2*scale,5*scale)) do
                        spots[#spots+1]=frame:PointToWorldSpace(Vector3.new(cell.X,cell.Y,-wallAt))-center
                    end
                    grid=true
                    kind=kind or (murderer.seen and "in sight" or "behind a wall (near)")
                else
                    spots=roundYou()
                end
            end
        elseif aimer and not mode.shield then
            -- (rows across the way the knife would come, from the one protected out toward the
            -- murderer's hand, as Knife Interception puts them for a knife in the air)
            local virtual=readyFor(aimer)
            if virtual then
                local studs=settings.interceptStop
                local wanted=count
                spots={}
                for _,point in ipairs(interceptPoints(virtual,wanted,studs)) do spots[#spots+1]=point-center end
                ready=true
                active=true
                kind=kind or readyLabel()
            else
                spots=rest(settings.distance,settings.mm2RingSpeed*0.8,"idle")
            end
        elseif mode.sky and not pointAt then
            -- (Hidden Knife Interception: up high the whole time, until a knife is thrown at you)
            spots=skySpots(count,clock)
            sky=true
            kind=kind or "hidden up high"
        else
            spots=rest(settings.distance,settings.mm2RingSpeed*0.8,"idle")
        end
    end
    kind=kind or "idle"
    if not grid then smoothDirection=nil;smoothBombDirection=nil end
    -- The bombs (MMV): over your head, turning as fast as Fake Bomb Spin Speed says (two or three
    -- side by side round it), whatever the fireflies are doing, until a knife is thrown at you
    -- (every bomb out waiting where it would hit you, on its line, one just behind another) or
    -- the shield is up (in its middle); once it's over, back over your head.
    diagnostics.bombMode=nil;diagnostics.goldMode=nil;diagnostics.bombError=nil
    for index,slot in ipairs(bombs) do
        local part=slot.part
        local at,facing,snap=nil,nil,false
        if knifeStack then
            at,facing,snap=knifeStack.impact-knifeStack.direction*((index-1)*0.7),-knifeStack.direction,true
        elseif bombPlaces[slot] then at,facing=bombPlaces[slot].at,bombPlaces[slot].facing end
        local how
        if at then
            -- (kept where it stays yours: brought in toward you if it would be nearer someone else)
            if not own.mine(at) then
                local toward=at-center
                local share=1
                while share>0.3 and not own.mine(center+toward*share) do share=share-0.1 end
                at=center+toward*math.max(share,0.3)
            end
            how="shielding"
            local ok,err=pcall(placeBomb,slot,part,at,facing,me,dt,snap)
            if not ok then diagnostics.bombError=tostring(err) end
        else
            how="over your head"
            local head=me.Position+LIFT+Vector3.new(0,BOMB_HEAD+math.sin(clock*2.4+(index-1)*1.5)*0.25,0)
            if #bombs>1 then
                -- (round over your head: two side by side, three in a little triangle)
                local right=flat(me.CFrame.RightVector) or Vector3.xAxis
                local forward=flat(me.CFrame.LookVector) or Vector3.new(0,0,-1)
                local angle=math.pi+(index-1)*2*math.pi/#bombs
                local radius=#bombs==2 and 1.3 or 1.6
                head=head+right*(math.cos(angle)*radius)+forward*(math.sin(angle)*radius)
            end
            local ok,err=pcall(spinBomb,slot,part,head,me,dt,settings.bombSpin*2*math.pi)
            if not ok then diagnostics.bombError=tostring(err) end
        end
        if slot==fakeBomb then diagnostics.bombMode=how elseif not diagnostics.goldMode then diagnostics.goldMode=how end
    end
    diagnostics.threat=kind;diagnostics.mode=kind;diagnostics.active=active
    if spots then
        local points={}
        for _,offset in ipairs(spots) do points[#points+1]=center+offset end
        -- (a spot nearer someone else than you would become theirs, and the firefly in it
        -- would be lost to you: brought in toward you until it's yours. Not the mouse swarm)
        if not swarm then
            for index,point in ipairs(points) do
                if not own.mine(point) then
                    local toward=point-center
                    -- (up high: brought in over your head first, keeping its height; never
                    -- brought down toward you, so they stay hidden up there)
                    local fixed=nil
                    if sky then
                        local flatOut=Vector3.new(toward.X,0,toward.Z)
                        for _,keep in ipairs({0.6,0.25,0}) do
                            local candidate=center+Vector3.new(0,toward.Y,0)+flatOut*keep
                            if own.mine(candidate) then fixed=candidate;break end
                        end
                        fixed=fixed or point
                    end
                    if not fixed then
                        local share=1
                        while share>0.3 and not own.mine(center+toward*share) do share=share-0.15 end
                        fixed=center+toward*math.max(share,0.3)
                    end
                    points[index]=fixed
                end
            end
        end
        if orbit or (isMMV and grid) then
            -- (each one keeps its own spot; one behind a wall comes in front of it)
            for index,point in ipairs(points) do
                if not clear(center,point) then points[index]=inFront(center,point) end
            end
        elseif not swarm and not sky then
            points=usable(center,points,count)
        end
        -- (swapping places now and then: MM2's grid with the ring aura on; MMV's shield keeps
        -- every firefly on its own spot, as in the original)
        local order=grid and not isMMV and settings.ring and shuffled(#free) or nil
        -- (when fireflies join or leave, or the formation changes, each one takes the nearest
        -- free spot instead of all of them moving round one place: no jolt as more come out)
        local key=(grid and "g" or orbit and "o" or swarm and "s" or sky and "k" or ready and "a" or "r")..#points..":"..#free
        local stable=not order and assignSlots(free,points,key)
        for index,part in ipairs(free) do
            local slot=order and order[index] or stable and stable[part] or index
            local point=points[(slot-1)%#points+1]
            if point then
                if slot>#points and not isMMV then point=point+Vector3.new(0,0.35*math.floor((slot-1)/#points),0) end
                targets[part]=point
            end
        end
    end
    for _,part in ipairs(list) do setBlocking(part,solid[part]==true) end
    -- Each firefly keeps a place relative to the one protected that only glides when the
    -- formation changes, so moving about carries them along at once with nothing trailing
    -- behind. (One on a knife's path stays put in the world instead.) They carry that
    -- player's speed as well, so for everyone else they move along between updates too.
    local alpha=math.clamp(1-math.exp(-dt*18),0,1)
    for part,target in pairs(targets) do
        pcall(function()
            local anchor=anchorOf[part] or root
            local base=anchor.Position+LIFT
            local wanted=target-base
            local current=offsets[part]
            if offsetAnchor[part]~=anchor or not current then current=part.Position-base end
            local snap=solid[part] and not anchorOf[part]
            if snap or (wanted-current).Magnitude>14 then current=wanted
            else current=current:Lerp(wanted,alpha) end
            offsets[part]=current;offsetAnchor[part]=anchor
            pinned[part]=snap or nil
            part.CFrame=CFrame.new(base+current)
            part.AssemblyLinearVelocity=snap and Vector3.zero or anchor.AssemblyLinearVelocity
            part.AssemblyAngularVelocity=Vector3.zero
        end)
    end
    for part in pairs(offsets) do
        if not targets[part] then offsets[part]=nil;offsetAnchor[part]=nil;pinned[part]=nil end
    end
end
-- just before each frame is drawn: every firefly put exactly where it belongs on you, so
-- whatever moved it in between (the jar's own scripts) doesn't show
local function holdInPlace()
    local held={}
    for _,slot in ipairs(SLOTS) do if slot.part then held[slot.part]=true end end
    for part,offset in pairs(offsets) do
        if not pinned[part] and not held[part] and (fireflies[part] or caps[part]) then
            local anchor=offsetAnchor[part]
            if anchor and anchor.Parent then
                pcall(function() part.CFrame=CFrame.new(anchor.Position+LIFT+offset) end)
            end
        end
    end
    -- (the bombs too, as they were put)
    for _,slot in ipairs(SLOTS) do
        local bomb,pose=slot.part,slot.pose
        if bomb and pose and not pose.pinned and pose.anchor and pose.anchor.Parent and pose.rotation then
            pcall(function() bomb.CFrame=CFrame.new(pose.anchor.Position+LIFT+pose.offset)*pose.rotation end)
        end
    end
end

local statusAt=0
-- (the jar lets its fireflies out over a few seconds, and the game may only hand one to
-- you a moment after it appears: every half second the ones near you are looked at again,
-- so none is left out)
local sweepAt=0
local sweepParams=OverlapParams.new()
sweepParams.FilterType=Enum.RaycastFilterType.Exclude
local function sweep()
    -- (often in the seconds after the jar opens, when fireflies are coming out; otherwise
    -- only now and then, close by: looking over everything nearby every half second made
    -- the game hitch)
    local busy=os.clock()-math.max(jar.usedAt,jar.spawnedAt)<12
    if os.clock()-sweepAt<(busy and (isMMV and 0.5 or 0.25) or 3) then return end
    sweepAt=os.clock()
    local root,character=myRoot()
    if not root then return end
    sweepParams.FilterDescendantsInstances={character}
    local radius=busy and 30 or 20
    local ok,parts=pcall(function() return workspace:GetPartBoundsInRadius(root.Position,radius,sweepParams) end)
    if not ok or type(parts)~="table" then return end
    for _,part in ipairs(parts) do
        if not fireflies[part] then pcall(consider,part);pcall(considerCap,part) end
    end
end
local function refreshClutchTimer()
    local root=myRoot()
    local now=computeBlocksClutch(root)
    if now==blocksClutch then return end
    blocksClutch=now
    local clutch=runtime.FireflyClutch
    if clutch and type(clutch.RefreshTimer)=="function" then pcall(clutch.RefreshTimer) end
end
local function statusText()
    if not active() then return "Off" end
    -- (a bomb the game keeps to itself is still held, but then it only moves on your screen)
    local fakeText,goldText="",""
    if fakeBomb.part then
        fakeText=" + Fake Bomb"..(fakeBomb.owned==false and " (only on your screen)" or "")
            ..(fakeBomb.guess and (" (not sure it's the bomb: "..fakeBomb.guess..")") or "")
    end
    local golds,screenOnly=0,false
    for _,slot in ipairs(goldBombs) do
        if slot.part then golds=golds+1;if slot.owned==false then screenOnly=true end end
    end
    if golds>0 then goldText=" + "..(golds==1 and "Gold Bomb" or (golds.." Gold Bombs"))..(screenOnly and " (only on your screen)" or "") end
    local text=string.format("Fireflies: %d%s%s | %s",diagnostics.fireflies,fakeText,goldText,diagnostics.active and "Active" or "Idle")
    -- (MMV's Protect Against Murderer without a bomb: it needs one)
    if isMMV and settings.murdererShield and not murdererGuard() then text=text.." | Protect Against Murderer: needs a bomb as particle helper" end
    -- (each bomb on: why it isn't out; the Gold Bombs once)
    local goldWhy=nil
    if slotWanted(fakeBomb) and not fakeBomb.part and fakeBomb.why then text=text.." | Fake Bomb: "..fakeBomb.why end
    for _,slot in ipairs(goldBombs) do
        if slotWanted(slot) and not slot.part and slot.why then goldWhy=slot.why;break end
    end
    if goldWhy then text=text.." | Gold Bomb: "..goldWhy end
    -- (an error in throwing or finding the bombs, in moving them, or in the fireflies, in short)
    local problem=diagnostics.helperError or diagnostics.bombError or diagnostics.error
    if problem then text=text.." | Error: "..(tostring(problem):gsub("^[^\n:]*:(%d+): ","line %1: ")):sub(1,140) end
    return text
end
-- Use Fake Bomb As Particle Helper (and MMV's Use Gold Bomb As Particle Helper, the same way
-- with its own toy, up to three bombs out at once in all). The bomb is thrown one way after
-- another until one brings it: MM2, its Remote told to put it right in front of your feet
-- (Bomb Jump's way: you're the nearest one, so the game hands it to you), then the toy pressed
-- and let go in your hand; MMV the other way round; a tap on the screen last, never on a touch
-- screen. The toy is in your hand only while it's thrown (a moment), then put back with what
-- you held back in your hand. The bomb that turns up is the one kept, and so is one you throw
-- yourself, and any Fake Bomb that's yours to move within 300 studs (the game is asked to
-- simulate everything 1000 studs round you). One the game keeps to itself is held all the same
-- (it then only moves on your screen: the status says so). Auto Use Firefly Jar goes first: no
-- bomb is thrown in the 2 s before the jar is due (5 s at most), so the jar is never late. A
-- bomb at a time is thrown. The Fake Bomb is ready again 22 s after a throw, the Gold Bomb 5 s
-- after; a try that doesn't work is tried again soon (1, 2, 4, then every 6 s). MMV: only while
-- the Gun Shield or Protect Against Murderer is on. Why it isn't out is in the status.
local helper={}
do
local function bombWhy(slot,text)
    slot.why=text
    if slot==fakeBomb then diagnostics.fakeBombWhy=text elseif slot==goldBombs[1] then diagnostics.goldBombWhy=text end
end
-- (in someone's character, a hat, a backpack, or one of the add-on's own things)
local function insideSomeone(object)
    local current=object.Parent
    for _=1,8 do
        if not current or current==workspace then return false end
        if current:IsA("Accessory") or current:IsA("Backpack") or current:FindFirstChildOfClass("Humanoid") then return true end
        local name=current.Name:lower()
        if name=="weapondisplays" or name=="throwingknife" or name:sub(1,9)=="visualsv2" then return true end
        current=current.Parent
    end
    return false
end
-- (a thrown bomb: a loose part that looks like that toy's own Handle (its size, its sounds),
-- or one with "bomb" in its name or in the name of one of the two things it's in (a Tool thrown
-- into the map counts), or a loose Handle, the way Fun Bomb finds it)
local function bombPartLike(part,kit)
    if not part:IsA("BasePart") or fireflies[part] or caps[part] or insideSomeone(part) then return false end
    local finder=runtime.ThrownBomb
    if finder and type(finder.Score)=="function" then
        local ok,score=pcall(finder.Score,part,(kit or FAKE_KIT).signature)
        if ok and type(score)=="number" then return score>=3 end
    end
    local named=part.Name:lower()=="handle"
    local current=part
    for _=1,3 do
        if named or not current or current==workspace then break end
        if current.Name:lower():find("bomb",1,true) then named=true end
        current=current.Parent
    end
    return named
end
-- (a bomb in several pieces is moved as one)
local function wholeBomb(part)
    local ok,assembly=pcall(function() return part.AssemblyRootPart end)
    if ok and typeof(assembly)=="Instance" and not assembly.Anchored then return assembly end
    return part
end
-- (the toy itself, in your hand or backpack, and what its thrown bomb looks like)
local function bombTool(kit)
    for _,container in ipairs({LocalPlayer.Character,LocalPlayer:FindFirstChildOfClass("Backpack")}) do
        if container then
            for _,tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and tool.Name:lower():gsub("%s","")==kit.toolName then
                    local finder=runtime.ThrownBomb
                    if finder and type(finder.Signature)=="function" and kit.signatureOf~=tool then
                        local ok,signature=pcall(finder.Signature,tool)
                        if ok and type(signature)=="table" and signature.size then kit.signature=signature;kit.signatureOf=tool end
                    end
                    return tool
                end
            end
        end
    end
end
-- (MMV: a bomb that looks more like the Gold Bomb toy than the Fake Bomb toy is never taken for
-- the Fake Bomb; only once both toys' looks are known)
local function goldLooking(part)
    if not isMMV or not GOLD_KIT.signature or not FAKE_KIT.signature then return false end
    local finder=runtime.ThrownBomb
    if not finder or type(finder.Score)~="function" then return false end
    local okGold,gold=pcall(finder.Score,part,GOLD_KIT.signature)
    local okFake,fake=pcall(finder.Score,part,FAKE_KIT.signature)
    return okGold and okFake and type(gold)=="number" and type(fake)=="number" and gold>fake
end
-- (which bomb a toy you're holding would be: the first of its bombs that isn't out)
local function heldSlot(tool)
    if not tool then return nil end
    local name=tool.Name:lower():gsub("%s","")
    local first=nil
    for _,slot in ipairs(SLOTS) do
        if name==slot.kit.toolName and slotWanted(slot) then
            if not slot.part then return slot end
            first=first or slot
        end
    end
    return first
end
local FIND_RADIUS=60
-- (a spot on the screen with nothing on it that could take a tap: no button, text box or other
-- active, visible piece of any menu over it; nil if there's none)
local function blocksTap(object)
    if not object.Visible then return false end
    return object:IsA("GuiButton") or object:IsA("TextBox") or object.Active==true
end
local function freeScreenSpot()
    local camera=workspace.CurrentCamera
    if not camera then return nil end
    local size=camera.ViewportSize
    local inset=Vector2.zero
    pcall(function() inset=game:GetService("GuiService"):GetGuiInset() end)
    local containers={LocalPlayer:FindFirstChildOfClass("PlayerGui")}
    pcall(function() containers[#containers+1]=game:GetService("CoreGui") end)
    -- (the executor's own hidden menus, ODH's among them, checked by hand)
    local hidden=nil
    pcall(function() hidden=type(gethui)=="function" and gethui() or (type(env.gethui)=="function" and env.gethui()) or nil end)
    for _,fraction in ipairs({Vector2.new(0.5,0.4),Vector2.new(0.5,0.28),Vector2.new(0.32,0.38),Vector2.new(0.68,0.38),Vector2.new(0.5,0.55)}) do
        local x,y=size.X*fraction.X,size.Y*fraction.Y
        local blocked=false
        for _,container in ipairs(containers) do
            for _,atY in ipairs({y,y-inset.Y}) do
                local ok,objects=pcall(function() return container:GetGuiObjectsAtPosition(x,atY) end)
                if ok and type(objects)=="table" then
                    for _,object in ipairs(objects) do if blocksTap(object) then blocked=true;break end end
                end
                if blocked then break end
            end
            if blocked then break end
        end
        if not blocked and typeof(hidden)=="Instance" then
            pcall(function()
                for _,object in ipairs(hidden:GetDescendants()) do
                    if object:IsA("GuiObject") and blocksTap(object) then
                        local gui=object:FindFirstAncestorWhichIsA("LayerCollector")
                        if not gui or gui.Enabled~=false then
                            local at,extent=object.AbsolutePosition,object.AbsoluteSize
                            for _,atY in ipairs({y,y-inset.Y}) do
                                if x>=at.X and x<=at.X+extent.X and atY>=at.Y and atY<=at.Y+extent.Y then blocked=true end
                            end
                        end
                    end
                    if blocked then break end
                end
            end)
        end
        if not blocked then return x,y end
    end
    return nil
end
-- (a tap on the screen there, with the toy in your hand: what a finger does when you throw it)
local function screenTap()
    local ok,input=pcall(function() return game:GetService("VirtualInputManager") end)
    if not ok or typeof(input)~="Instance" then return false end
    local typing=nil
    pcall(function() typing=UserInput:GetFocusedTextBox() end)
    if typing then return false end
    local x,y=freeScreenSpot()
    if not x then return false end
    fakeBomb.tappingUntil=os.clock()+0.6
    local sent=pcall(function() input:SendMouseButtonEvent(x,y,0,true,game,0) end)
    task.wait(0.06)
    pcall(function() input:SendMouseButtonEvent(x,y,0,false,game,0) end)
    return sent
end
local function throwBomb(slot)
    local kit=slot.kit
    local root,character=myRoot()
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid then return nil,"no character" end
    local tool=bombTool(kit)
    if not tool then
        -- (fetched, as Bomb Jump and Auto Get Tools do)
        pcall(function() game:GetService("ReplicatedStorage").Remotes.Extras.ReplicateToy:InvokeServer(kit.toy) end)
        local deadline=os.clock()+1.5
        repeat task.wait(0.05);tool=bombTool(kit) until tool or os.clock()>deadline
    end
    if not tool then return nil,"you don't have the "..kit.name.." toy" end
    local remote=tool:FindFirstChild("Remote")
    if not (remote and remote:IsA("RemoteEvent")) then remote=tool:FindFirstChildWhichIsA("RemoteEvent",true) end
    local backpack=LocalPlayer:FindFirstChildOfClass("Backpack")
    local held=nil
    for _,child in ipairs(character:GetChildren()) do
        if child:IsA("Tool") and child~=tool then held=child;break end
    end
    -- (right in front of your feet)
    local position=root.Position+(flat(root.CFrame.LookVector) or Vector3.zAxis)*4-Vector3.new(0,3,0)
    slot.found=nil;slot.anyNew=nil;slot.throwFrom=position;slot.throwAt=os.clock()
    -- (pieces that turned up and were gone again by the time they'd have been kept: never taken)
    local skip={}
    slot.skip=skip
    local finder=runtime.ThrownBomb
    local thrownWatch=nil
    if finder and type(finder.Begin)=="function" then
        local ok,value=pcall(finder.Begin,tool,position)
        if ok then thrownWatch=value end
    end
    if type(thrownWatch)=="table" then thrownWatch.skip=skip end
    local function lookNow()
        if not slot.found and thrownWatch then
            local ok,found=pcall(finder.Find,thrownWatch,FIND_RADIUS)
            if ok and typeof(found)=="Instance" and not otherBomb(slot,found) then slot.found=found end
        end
        return slot.found
    end
    -- (the Remote as the way that last brought this toy's bomb: fired the moment the toy is in your
    -- hand and the toy put straight back, the way Gold Bomb Jump throws it, the bomb then looked
    -- for with your hands free; if that ever doesn't bring one, it's given its moment from then on)
    local order=throwOrder(kit)
    local quick=remote~=nil and kit.way=="remote" and order[1]=="remote" and not kit.patient
    slot.quick=nil
    pcall(function() tool.Parent=character end)
    RunService.Heartbeat:Wait()
    if not quick then
        -- (a moment in your hand first, as when you take it out to throw it (a shorter one with a
        -- way that has worked); MM2's toys say they're not enabled while they're put away, so
        -- until the game has it enabled in your hand, half a second at most)
        task.wait(kit.way and 0.05 or 0.1)
        local enabledBy=os.clock()+0.5
        while tool.Enabled==false and os.clock()<enabledBy do task.wait(0.03) end
    end
    -- (the ways in turn, each given a moment to bring a bomb, until one does; the toy kept in
    -- your hand meanwhile, as the game wants it for a throw, and put away the moment it's out)
    local thrownBy=nil
    for _,name in ipairs(order) do
        if lookNow() or tool.Parent~=character then break end
        local tried=false
        if name=="tap" then
            tried=true
            pcall(function() tool:Activate() end)
            task.wait(0.12)
            pcall(function() tool:Deactivate() end)
        elseif name=="screen" then
            tried=screenTap()
        elseif remote then
            tried=true
            pcall(function() remote:FireServer(CFrame.new(position),50) end)
        end
        if tried then
            thrownBy=name
            if quick and name=="remote" then slot.quick=true;RunService.Heartbeat:Wait();break end
            local deadline=os.clock()+(name=="tap" and 1 or name=="remote" and 0.8 or 1.2)
            while os.clock()<deadline and not lookNow() do task.wait(0.03) end
            if lookNow() then break end
        end
    end
    if tool.Parent==character then pcall(function() tool.Parent=backpack or tool.Parent end) end
    if held and held.Parent and held.Parent~=character then pcall(function() humanoid:EquipTool(held) end) end
    if not thrownBy then return nil,"no way of throwing it worked" end
    -- (your hands are free again: the jar can be used while the bomb is looked for; Auto Get
    -- Tools puts your toys back in their slots)
    slot.deploying=false;slot.searching=true
    local tools=runtime.AutoGetTools
    if tools and type(tools.RequestOrder)=="function" then pcall(tools.RequestOrder) end
    -- (what was found is looked at again before it's kept: one that's gone again (removed, moved
    -- out of the map, or fallen out of it) is noted, never taken, and the real one looked for:
    -- 3 s more once one has gone)
    local vanished=nil
    local function stillThere()
        local current=slot.found
        if not current then return false end
        if bombAlive(wholeBomb(current)) then return true end
        vanished=vanished or (describeBomb(current).." turned up, but "..bombGoneWhy(wholeBomb(current)))
        skip[current]=true;slot.found=nil
        return false
    end
    local deadline,extended=os.clock()+2,false
    while true do
        lookNow()
        if stillThere() then break end
        if os.clock()>=deadline then
            if vanished and not extended then extended=true;deadline=os.clock()+3 else break end
        end
        task.wait(0.05)
    end
    if not slot.found then
        -- (looked for round you and round where it went)
        local params=OverlapParams.new()
        params.FilterType=Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances={character}
        for _,from in ipairs({position,root.Position}) do
            local ok,parts=pcall(function() return workspace:GetPartBoundsInRadius(from,FIND_RADIUS,params) end)
            if ok and type(parts)=="table" then
                for _,part in ipairs(parts) do
                    if not skip[part] and bombPartLike(part,kit) and bombAlive(wholeBomb(part)) and not otherBomb(slot,part) then slot.found=part;break end
                end
            end
            if slot.found then break end
        end
    end
    local found=slot.found
    -- (nothing that looks like the bomb: the new piece right where it was thrown, a guess, said so
    -- in the status with what it is)
    local guess=nil
    local anyNew=slot.anyNew
    if not found and anyNew and not skip[anyNew] and bombAlive(wholeBomb(anyNew)) and not otherBomb(slot,anyNew) then
        found=anyNew
        guess=describeBomb(anyNew)
    end
    slot.found=nil;slot.anyNew=nil;slot.throwAt=nil;slot.skip=nil
    if not found then
        if vanished then return nil,vanished..", and no other bomb came",thrownBy end
        local seen=finder and finder.lastSeen
        return nil,"the thrown bomb wasn't found"..(seen and (" (near you: "..tostring(seen)..")") or ""),thrownBy
    end
    -- (the toy ready again after its own wait)
    kit.readyAt=os.clock()+kit.cooldown
    -- (for 4 s, what this throw brings is still watched: if the one kept goes again (a stand-in
    -- the game puts out for the throw, say), the one that turns up in its place is taken)
    skip[found]=nil
    slot.follow=type(thrownWatch)=="table" and {watch=thrownWatch,untilAt=os.clock()+4} or nil
    return wholeBomb(found),nil,thrownBy,guess
end
-- a part that has just turned up in the map, while a bomb was just thrown (by the add-on, or
-- by you with that toy in your hand)
local function bombLanded(slot,object,ours)
    if not object.Parent or not object:IsDescendantOf(workspace) or not slotWanted(slot) or not bombAllowed() or not bombsActive() or not protecting() then return end
    local root=myRoot()
    local from=ours and slot.throwFrom or (root and root.Position)
    if not from then return end
    local ok,away=pcall(function() return (object.Position-from).Magnitude end)
    if not ok then return end
    if otherBomb(slot,object) then return end
    if ours then
        if slot.found or (slot.skip and slot.skip[object]) then return end
        if away<FIND_RADIUS and bombPartLike(object,slot.kit) then slot.found=object
        elseif away<10 and not slot.anyNew and not object.Anchored and not insideSomeone(object)
            and not fireflies[object] and not caps[object] and not object.Name:lower():find("firefl",1,true)
            and math.max(object.Size.X,object.Size.Y,object.Size.Z)<=3 then
            -- (a new piece right where it was thrown, whatever it's called: kept in case nothing
            -- named like a bomb shows up)
            slot.anyNew=object
        end
    elseif away<30 and not slot.part and not slot.deploying and not slot.searching and bombPartLike(object,slot.kit) and not murdererMe(root) then
        -- (one you threw yourself: kept the same way)
        adoptBomb(slot,wholeBomb(object))
        slot.kit.readyAt=os.clock()+slot.kit.cooldown
        bombWhy(slot,nil)
    end
end
-- (none out, the toy ready, nothing else using your hands, Auto Get Tools done (3 s at most):
-- one thrown out, looked at every tenth of a second)
-- (the jar first: no bomb thrown out (holding the toy up) when Auto Use Firefly Jar is about
-- to use the jar, so the fireflies are never left to run out)
local function jarDueSoon()
    if jar.busy then return true end
    if not settings.autoJar or jar.roundBlocked then return false end
    local tool=jarTool()
    if not tool then return false end
    local readyAt=math.max(jar.usedAt+(jar.cooldown or JAR_COOLDOWN),jar.retryAt or -math.huge)
    local readyIn=readyAt-os.clock()
    if readyIn>2 then jar.bombWaitSince=nil;return false end
    -- (ready but not wanted right now: not in the way)
    if readyIn<=0 and diagnostics.jarIdle then return false end
    -- (a jar that isn't used for a while all the same doesn't hold the bomb up past 5 s)
    jar.bombWaitSince=jar.bombWaitSince or os.clock()
    return os.clock()-jar.bombWaitSince<5
end
-- (whatever loose part is near enough, the game may hand you: asked for as far round you as
-- it goes, the way part-control scripts do, so a Fake Bomb further off can become yours too)
local BOMB_REACH=1000
local reachAt=-math.huge
local function askForReach()
    if type(setHidden)~="function" or os.clock()-reachAt<2 then return end
    reachAt=os.clock()
    pcall(setHidden,LocalPlayer,"SimulationRadius",BOMB_REACH)
    pcall(setHidden,LocalPlayer,"MaximumSimulationRadius",BOMB_REACH)
end
local function slotStep(slot,now,character,inHand)
    local kit=slot.kit
    if not slotWanted(slot) or not runtimeAlive then releaseBomb(slot);return end
    -- (not with MM2's Hidden Knife Interception: left alone, never thrown, so Bomb Jump works)
    if not bombAllowed() then
        releaseBomb(slot);slot.manualWatch=nil
        bombWhy(slot,"not used with Hidden Knife Interception")
        return
    end
    -- (MMV: only while the Gun Shield or Protect Against Murderer is on)
    if not bombsActive() then
        releaseBomb(slot);slot.manualWatch=nil
        bombWhy(slot,"turn on Gun Shield or Protect Against Murderer")
        return
    end
    -- (and only while something moves the fireflies: a protection mode, the ring aura or Follow
    -- Mouse)
    if not protecting() then
        releaseBomb(slot);slot.manualWatch=nil
        bombWhy(slot,"turn on a protection mode or the ring aura")
        return
    end
    local holdingBomb=heldSlot(inHand)==slot
    if holdingBomb and not slot.deploying then slot.heldAt=now end
    -- (your own throw: while you have it in hand, and for 3 s after, what's new near you is
    -- looked at a few times a second, so a bomb you throw is kept however it turns up)
    local finder=runtime.ThrownBomb
    if finder and not slot.deploying and not slot.searching and not slot.part then
        if holdingBomb and not slot.manualWatch then
            local root=character and character:FindFirstChild("HumanoidRootPart")
            local ok,value=pcall(finder.Begin,inHand,root and root.Position)
            if ok then slot.manualWatch=value end
        end
        local watching=slot.manualWatch
        if watching and slot.heldAt and now-slot.heldAt>3 then slot.manualWatch=nil;watching=nil end
        if watching and now>=(slot.manualCheckAt or 0) then
            slot.manualCheckAt=now+0.2
            local root=character and character:FindFirstChild("HumanoidRootPart")
            if root then watching.from=root.Position end
            local ok,found=pcall(finder.Find,watching)
            if ok and typeof(found)=="Instance" and bombAlive(found) and not otherBomb(slot,found) and not murdererMe(root) then
                slot.manualWatch=nil
                adoptBomb(slot,wholeBomb(found))
                kit.readyAt=now+kit.cooldown
                bombWhy(slot,nil)
                return
            end
        end
    elseif slot.part then
        slot.manualWatch=nil
    end
    -- (Bomb Fling first: while it flings, whichever bomb it flings with is its, so all are let go)
    if bombFlinging() then releaseBomb(slot);bombWhy(slot,slot==fakeBomb and "Bomb Fling is using it" or "waiting for Bomb Fling");return end
    if slot.part and not bombAlive(slot.part) then releaseBomb(slot) end
    if slot.part then
        -- (held but only on your screen: a Fake Bomb that's yours to move, found near, is taken
        -- instead, so it blocks for everyone)
        if slot==fakeBomb and slot.owned==false and now>=(slot.betterAt or 0) then
            slot.betterAt=now+0.5
            local fling=runtime.BombFling
            if fling and type(fling.NearestOwnedBomb)=="function" then
                local ok,own=pcall(fling.NearestOwnedBomb,300)
                if ok and typeof(own)=="Instance" and bombAlive(own) and not insideSomeone(own) then
                    own=wholeBomb(own)
                    if own~=slot.part and not otherBomb(slot,own) and not goldLooking(own) then adoptBomb(slot,own) end
                end
            end
        end
        bombWhy(slot,nil)
        return
    end
    if slot.deploying or slot.searching then return end
    if now<(slot.checkAt or 0) then return end
    slot.checkAt=now+0.1
    local root=character and character:FindFirstChild("HumanoidRootPart")
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health<=0 then bombWhy(slot,"no character");return end
    -- (as the MM2 murderer, protection is paused: the bomb is left alone, so Bomb Jump works)
    if murdererMe(root) then bombWhy(slot,"left alone while you're the murderer");return end
    if clutchBusy() then bombWhy(slot,"waiting for Firefly Clutch");return end
    -- (the one out before, back from Bomb Fling or switched back on and still out: taken back;
    -- or the one Bomb Fling threw and still has out)
    if slot.last and bombAlive(slot.last) and not otherBomb(slot,slot.last) then adoptBomb(slot,slot.last);bombWhy(slot,nil);return end
    -- (the one kept went again within 4 s of its throw: the one that turned up in its place is
    -- looked for and taken, instead of waiting for the toy to be ready again)
    local follow=slot.follow
    if follow and now>=follow.untilAt then slot.follow=nil;follow=nil end
    if follow and finder and type(finder.Find)=="function" then
        follow.watch.skip=follow.watch.skip or {}
        if slot.last and not bombAlive(slot.last) then follow.watch.skip[slot.last]=true end
        local ok,found=pcall(finder.Find,follow.watch,FIND_RADIUS)
        if ok and typeof(found)=="Instance" and not otherBomb(slot,found) and not goldLooking(found) then
            local whole=wholeBomb(found)
            if bombAlive(whole) then slot.follow=nil;adoptBomb(slot,whole);bombWhy(slot,nil);return end
        end
        bombWhy(slot,"the bomb kept went again a moment after it was thrown; looking for the one in its place")
        return
    end
    if slot==fakeBomb then
        local fling=runtime.BombFling
        if fling and type(fling.OwnBomb)=="function" then
            local ok,own=pcall(fling.OwnBomb)
            if ok and typeof(own)=="Instance" and bombAlive(own) and not otherBomb(slot,own) and not goldLooking(own) then adoptBomb(slot,own);bombWhy(slot,nil);return end
        end
        -- (and any Fake Bomb that's yours to move, however it got there and however far off: one
        -- you threw yourself, or one of the add-on's the game has handed you after all)
        if fling and type(fling.NearestOwnedBomb)=="function" then
            local ok,own=pcall(fling.NearestOwnedBomb,300)
            if ok and typeof(own)=="Instance" and bombAlive(own) and not insideSomeone(own) then
                own=wholeBomb(own)
                if not otherBomb(slot,own) and not goldLooking(own) then adoptBomb(slot,own);bombWhy(slot,nil);return end
            end
        end
    end
    if jarDueSoon() then bombWhy(slot,"waiting for the jar");return end
    if now<(kit.readyAt or 0) then
        -- (after a try that brought nothing, why, until the next try)
        local wait=math.ceil(kit.readyAt-now)
        bombWhy(slot,slot.lastFail and ("trying again in %ds; last try: %s"):format(wait,slot.lastFail) or ("ready in %ds"):format(wait))
        return
    end
    -- (one bomb thrown at a time, each until it's found, so a bomb landing is always the right one's)
    for _,other in ipairs(SLOTS) do
        if other~=slot and (other.deploying or other.searching) then bombWhy(slot,"waiting for the other bomb");return end
    end
    -- (Auto Get Tools fetching your toys or putting them in order: waited for, 3 s at most)
    local tools=runtime.AutoGetTools
    if tools and type(tools.Busy)=="function" then
        local ok,busy=pcall(tools.Busy)
        if ok and busy then
            slot.busySince=slot.busySince or now
            if now-slot.busySince<3 then bombWhy(slot,"waiting for Auto Get Tools");return end
        else
            slot.busySince=nil
        end
    end
    -- (in your hand: thrown by you, it's kept)
    if holdingBomb then bombWhy(slot,"in your hand (throw it and it's kept)");return end
    slot.deploying=true
    bombWhy(slot,slot.lastFail and ("throwing it out again; last try: "..slot.lastFail) or "throwing it out")
    task.spawn(function()
        local ok,part,reason,thrownBy,guess=pcall(throwBomb,slot)
        slot.deploying=false;slot.searching=false
        slot.throwAt=nil
        local quick=slot.quick;slot.quick=nil
        if not kit.wayKey then
            -- (the Fake Bomb: its ways always in the same order)
        elseif ok and typeof(part)=="Instance" and thrownBy and kit.way~=thrownBy then
            -- (the way that brought it goes first from now on, kept for next time too)
            kit.way=thrownBy;SetCfg(kit.wayKey,thrownBy)
        elseif ok and typeof(part)~="Instance" and thrownBy and thrownBy==kit.way then
            -- (the way that worked before brought nothing: put straight back, it's given its
            -- moment from now on; given its moment, the ways are tried in turn again)
            if quick then kit.patient=true else kit.way=nil;SetCfg(kit.wayKey,nil) end
        end
        if ok and typeof(part)=="Instance" and bombAlive(part) and slotWanted(slot) and bombsActive() and runtimeAlive and not bombFlinging() then
            kit.failures=0
            if slot==fakeBomb then diagnostics.bombThrownBy=thrownBy else diagnostics.goldThrownBy=thrownBy end
            slot.lastFail=nil
            adoptBomb(slot,part)
            slot.guess=guess
            bombWhy(slot,nil)
        else
            kit.failures=(kit.failures or 0)+1
            -- (thrown but not found, or not thrown: tried again soon, then every 6 s; why stays in
            -- the status until a try works)
            local retry=os.clock()+math.min(6,2^(kit.failures-1))
            if (kit.readyAt or 0)<retry then kit.readyAt=retry end
            local why=ok and tostring(reason or "no bomb") or ("error: "..tostring(part))
            if ok and typeof(part)=="Instance" then
                -- (found, and still not kept: which of the checks it failed)
                if not bombAlive(part) then why=describeBomb(part).." was found, but "..bombGoneWhy(part)
                elseif not slotWanted(slot) then why="it was found, but its toggle is off"
                elseif not bombsActive() then why="it was found, but Gun Shield and Protect Against Murderer are off"
                elseif bombFlinging() then why="it was found, but Bomb Fling took it"
                else why="it was found, but the add-on was closed" end
            end
            slot.lastFail=(thrownBy and (why.." (thrown by "..thrownBy..")") or why):sub(1,160)
            bombWhy(slot,slot.lastFail)
        end
    end)
end
local function bombStep()
    local anyOn=false
    for _,slot in ipairs(SLOTS) do if slotWanted(slot) then anyOn=true end end
    if anyOn and runtimeAlive and bombAllowed() and bombsActive() then askForReach() end
    local now=os.clock()
    local character=LocalPlayer.Character
    local inHand=character and character:FindFirstChildOfClass("Tool")
    for _,slot in ipairs(SLOTS) do slotStep(slot,now,character,inHand) end
end
helper.step,helper.landed=bombStep,bombLanded
end
local function stopWatching()
    if loop then loop:Disconnect();loop=nil end
    if placeLoop then placeLoop:Disconnect();placeLoop=nil end
end
-- (the fireflies and knives are looked out for from the first time protection is on until
-- the add-on is closed, so switching a mode off and another on keeps every firefly)
local function watch()
    if watchAdded then return end
    for _,object in ipairs(workspace:GetChildren()) do considerKnife(object) end
    watchAdded=workspace.DescendantAdded:Connect(function(object)
        if object:IsA("BasePart") then
            task.delay(0.05,function() if object.Parent then consider(object);considerCap(object) end end)
            -- (Use Fake Bomb As Particle Helper, Use Gold Bomb As Particle Helper: a bomb landing where it was
            -- just thrown, by the add-on or by you)
            for _,slot in ipairs(SLOTS) do
                if slotWanted(slot) then
                    local now=os.clock()
                    local ours=slot.throwAt~=nil and now-slot.throwAt<3
                    local yours=not ours and not slot.deploying and not slot.searching and slot.heldAt~=nil and now-slot.heldAt<3
                    -- (when it turned up, while a bomb is being thrown: see otherBomb)
                    if ours then appeared[object]=now end
                    if ours or yours then task.defer(helper.landed,slot,object,ours) end
                end
            end
        end
        local name=object.Name:lower()
        if name=="throwingknife" or name=="knifevisual" or (object.Parent==workspace and name:find("knife",1,true)) then
            task.defer(considerKnife,object)
        end
    end)
    watchRemoved=workspace.DescendantRemoving:Connect(function(object)
        if fireflies[object] then forget(object) end
        if caps[object] then forgetCap(object) end
        if knives[object] then knives[object]=nil end
    end)
end
local function start()
    if loop then return end
    watch()
    for _,part in ipairs(list) do pcall(function() part.CanCollide=false end) end
    -- fireflies already out (right after using the jar) are picked up too
    local root=myRoot()
    if root then
        local params=OverlapParams.new()
        params.FilterType=Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances={LocalPlayer.Character}
        local ok,parts=pcall(function() return workspace:GetPartBoundsInRadius(root.Position,30,params) end)
        if ok then for _,part in ipairs(parts) do consider(part) end end
    end
    jarTool()
    -- (after the physics step, so they're placed where you are this very frame)
    loop=RunService.Heartbeat:Connect(function(dt)
        if not runtimeAlive then return end
        pcall(sweep)
        -- (an error in the bombs or the fireflies goes in the status, not only away silently)
        local okBombs,bombProblem=pcall(helper.step)
        diagnostics.helperError=not okBombs and tostring(bombProblem) or nil
        local ok,err=pcall(step,tonumber(dt) or 1/60)
        diagnostics.error=not ok and tostring(err) or nil
        if os.clock()-statusAt>0.5 then pcall(refreshClutchTimer) end
        if status and os.clock()-statusAt>0.5 then
            statusAt=os.clock()
            pcall(function() status:SetValue(statusText()) end)
        end
    end)
    pointer.watch()
    placeLoop=RunService.RenderStepped:Connect(function()
        if runtimeAlive then holdInPlace() end
    end)
end
local function stop()
    stopWatching()
    pointer.unwatch()
    letGo()
    -- (still known, just left alone: their own collision back)
    for _,part in ipairs(list) do
        local saved=fireflies[part]
        if saved and part.Parent then pcall(function() part.CanCollide=saved.collide end) end
    end
    smoothDirection=nil;smoothBombDirection=nil
    for part in pairs(caps) do forgetCap(part) end
    if status then pcall(function() status:SetValue("Off") end) end
end
-- the fireflies are of use: a protection mode on with someone who could hurt you within
-- 200 studs, or the ring aura / mouse swarm on (wanted everywhere)
local function jarNeeded(root)
    if #list>=MAX_FIREFLIES then return false end
    if settings.ring or settings.mouse then return true end
    -- (just spawned, or the round just started: wanted straight away, before anyone has
    -- their knife or gun out)
    local sinceChange=os.clock()-math.max(jar.respawnAt or -math.huge,jar.teleportAt or -math.huge)
    if sinceChange<20 and protecting() then return true end
    for _,threat in ipairs(attackers(root)) do
        if threat.distance<=RANGE then return true end
    end
    -- (MMV's Protect Against Murderer: whoever has the knife, within 200 studs, too)
    if isMMV and settings.murdererShield then
        for _,plr in ipairs(Players:GetPlayers()) do
            if plr~=LocalPlayer and (role(plr)=="murderer" or hasTool(plr,"knife")) then
                local other=aliveRoot(plr)
                if other and (other.Position-root.Position).Magnitude<=RANGE then return true end
            end
        end
    end
    return false
end
-- the jar, used again the moment it's ready (not while you're the murderer in MM2, or
-- while Firefly Clutch is in the middle of a clutch)
local function autoStep()
    if not settings.autoJar or not runtimeAlive or jar.busy or bombThrowing() then return end
    local root,character=myRoot()
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health<=0 then return end
    -- (a jump of over 50 studs is a teleport: the round starting or ending, when the game
    -- hands out and takes back tools)
    local now=os.clock()
    if jar.lastRootPosition and (root.Position-jar.lastRootPosition).Magnitude>50 then jar.teleportAt=now end
    jar.lastRootPosition=root.Position
    -- (MM2: the jar can't be used during this round: left until it's over, or you're back in
    -- the lobby, respawned or teleported)
    if jar.roundBlocked then
        local moved=math.max(jar.respawnAt or -math.huge,jar.teleportAt or -math.huge)>(jar.roundBlockedAt or 0)
        if moved or not roundOn() then
            jar.roundBlocked=false;jar.failures=0;jar.retryAt=nil
        else
            diagnostics.jarRound=true
            return
        end
    end
    diagnostics.jarRound=false
    local tool=jarTool()
    if not jarReady(tool) then return end
    refreshRound()
    if murdererMe(root) then return end
    if clutchBusy() then return end
    -- After a respawn or a teleport, and whenever Increase Inventory's Auto Get Tools is
    -- fetching your toys or putting them in their slots, the jar waits for it; the moment
    -- it's done (every chosen toy in place) the jar goes. (Never held up for good by a toy
    -- that won't come: 12 s at most.)
    local sinceChange=now-math.max(jar.respawnAt or -math.huge,jar.teleportAt or -math.huge)
    if sinceChange<0.3 then return end
    local tools=runtime.AutoGetTools
    if tools and type(tools.Busy)=="function" then
        local ok,busy=pcall(tools.Busy)
        if ok and busy then
            jar.toolsBusySince=jar.toolsBusySince or now
            jar.toolsBusyAt=now
            if now-jar.toolsBusySince<12 then return end
        else
            jar.toolsBusySince=nil
        end
    end
    if now-(jar.toolsBusyAt or -math.huge)<0.1 and not jar.toolsBusySince then return end
    if not jarNeeded(root) then diagnostics.jarIdle=true;return end
    diagnostics.jarIdle=false
    useJar()
end
local function refresh()
    if active() then start() else stop() end
    pcall(refreshClutchTimer)
    if settings.autoJar and not autoLoop then
        local elapsed=0
        autoLoop=RunService.Heartbeat:Connect(function(dt)
            elapsed=elapsed+dt
            if elapsed<0.05 then return end
            elapsed=0
            pcall(autoStep)
        end)
    elseif not settings.autoJar and autoLoop then
        autoLoop:Disconnect();autoLoop=nil
    end
end
local controls={}
local KEYS={shield=MMV_OWN.key("shield"),intercept="fireflyProtectIntercept",sky="fireflyProtectHidden",fakeBomb=MMV_OWN.key("fakeBomb"),
    ring=MMV_OWN.key("ring"),mouse=MMV_OWN.key("mouse"),autoJar=MMV_OWN.key("autoJar"),
    goldBomb="fireflyMMV_GoldBomb",murdererShield="fireflyMMV_MurdererShield"}
-- (one of each group at a time: turning one on turns the one that was on off)
local GROUPS=isMMV and {} or {{"shield","intercept","sky"}}
local function groupOf(field)
    for _,group in ipairs(GROUPS) do if table.find(group,field) then return group end end
end
for _,group in ipairs(GROUPS) do
    local seen=false
    for _,field in ipairs(group) do
        if settings[field] then
            if seen then settings[field]=false;SetCfg(KEYS[field],false) end
            seen=true
        end
    end
end
-- The one that was on is switched off at once in the add-on, and in the menu on the next
-- frame, outside the click on the new one; the menu can ignore a toggle switched while it
-- is still busy with a click, so that's tried again over the next few seconds until it
-- shows off (unless you've turned it back on yourself).
local RETRIES={0,0.15,0.4,0.8,1.5,2.5,4}
local function switchOff(other)
    local controller=controls[other]
    if controller and not settings[other] then pcall(function() controller:Set(false) end) end
end
local function add(name,field,after)
    controls[field]=addToggle(section,name,settings[field],function(value)
        settings[field]=value;SetCfg(KEYS[field],value)
        if after then pcall(after,value) end
        if value then
            for _,other in ipairs(groupOf(field) or {}) do
                if other~=field then
                    settings[other]=false;SetCfg(KEYS[other],false)
                    for _,delay in ipairs(RETRIES) do
                        if delay==0 then task.defer(switchOff,other) else task.delay(delay,switchOff,other) end
                    end
                end
            end
        end
        refresh()
    end)
end
if isMMV then
    add("Gun Shield (MMV)","shield")
    -- (Protect Against Murderer works with the bombs: turned on without one, you're told)
    add("Protect Against Murderer","murdererShield",function(value)
        if value and not (settings.fakeBomb or settings.goldBomb) and runtimeAlive then
            pcall(shared.Notify,"Firefly Protection: Protect Against Murderer needs Use Fake Bomb As Particle Helper or Use Gold Bomb As Particle Helper on",4)
        end
    end)
    pcall(function()
        section:AddParagraph("Murderer First","Protect Against Murderer is prioritized: with the murderer in sight within 250 studs (or within 40 behind a wall), the bombs turn to the murderer while the fireflies keep their grid on the sheriff or hero. It needs Use Fake Bomb As Particle Helper or Use Gold Bomb As Particle Helper on.")
    end)
    pcall(function() section:AddLabel("Firefly Options") end)
    add("Firefly Ring Aura","ring")
    add("Follow Mouse","mouse")
else
    add("Knife Shield (for yourself)","shield")
    add("Knife Interception","intercept")
    add("Hidden Knife Interception (Least effective)","sky")
    pcall(function()
        section:AddParagraph("Only One At A Time","You can only use one of three functions at a time. Turning one on will disable the previously enabled function.")
    end)
    pcall(function() section:AddLabel("Firefly Options") end)
    add("Firefly Ring Aura","ring")
    add("Follow Mouse","mouse")
end
add("Auto Use Firefly Jar","autoJar")
if isMMV then
    add("Use Fake Bomb As Particle Helper","fakeBomb")
    add("Use Gold Bomb As Particle Helper","goldBomb")
end
if isMMV then
    section:AddSlider("Ring Distance",1,8,settings.ringDistance,function(value)
        settings.ringDistance=math.clamp(tonumber(value) or MMV_OWN.default("ringDistance"),1,8);SetCfg(MMV_OWN.key("ringDistance"),settings.ringDistance)
    end)
    section:AddSlider("Ring Speed",0,10,settings.ringSpeed,function(value)
        settings.ringSpeed=math.clamp(tonumber(value) or MMV_OWN.default("ringSpeed"),0,10);SetCfg(MMV_OWN.key("ringSpeed"),settings.ringSpeed)
    end)
    -- (how far the shield sits off your body while it's shielding: 2 is right against you, 1
    -- up to a stud closer still, 3 a stud off; in thousandths)
    section:AddSlider("Shield Distance",1.001,SHIELD_MAX,math.max(settings.shieldDistance,1.001),function(value)
        local distance=math.clamp(tonumber(value) or 2,1,SHIELD_MAX)
        if distance<1.0015 then distance=1 end
        settings.shieldDistance=distance
        settings.shieldGap=distance-2
        SetCfg("fireflyMMV_ShieldDistance",distance)
    end)
else
    -- (1 to 4 studs, in steps of a hundredth)
    section:AddSlider("Firefly Distance",1.01,4,settings.distance,function(value)
        settings.distance=math.clamp(tonumber(value) or 2.2,1,4);SetCfg("fireflyProtectDistance",settings.distance)
    end)
    -- (how fast the fireflies go round you: 1 to 5, 2 as before)
    section:AddSlider("Firefly Ring Speed",1,5,settings.mm2RingSpeed,function(value)
        settings.mm2RingSpeed=math.clamp(tonumber(value) or 2,1,5);SetCfg("fireflyMM2RingSpeed",settings.mm2RingSpeed)
    end)
end
-- (how fast the Fake Bomb turns over your head: 1 to 5 turns a second; MMV only)
if isMMV then
    section:AddSlider("Fake Bomb Spin Speed",1,5,settings.bombSpin,function(value)
        settings.bombSpin=math.clamp(tonumber(value) or 1,1,5)
        SetCfg("fireflyMMV_FakeBombSpin",settings.bombSpin)
    end)
end
runtime.FireflyProtection={
    Active=active,
    DisableAll=function()
        for _,field in ipairs({"shield","intercept","sky","ring","mouse","autoJar","fakeBomb","goldBomb","murdererShield"}) do
            if controls[field] then controls[field]:Set(false) end
            settings[field]=false
        end
        refresh()
    end,
    UseJar=useJar,
    -- (Bomb Jump Clutch is off while the Fake Bomb is a particle helper: MMV only)
    UsesFakeBomb=function() return settings.fakeBomb==true and bombAllowed() and not murdererMe(myRoot()) end,
    -- (MMV's Use Gold Bomb As Particle Helper: Gold Bomb Jump is off while it keeps the Gold Bomb out)
    UsesGoldBomb=function() return isMMV and settings.goldBomb==true end,
    -- (the bomb it keeps out as a particle helper: Bomb Fling flings with it first)
    CurrentBomb=function() return fakeBomb.part end,
    -- (Firefly Clutch can't be used while protection is working: not while you're the
    -- MM2 murderer, when it's paused)
    BlocksClutch=function() return computeBlocksClutch(myRoot()) end,
    GetDiagnostics=function()
        local copy=table.clone(diagnostics)
        copy.running=loop~=nil;copy.autoJar=autoLoop~=nil;copy.jarBusy=jar.busy
        copy.status=statusText();copy.jarUsedAt=jar.usedAt
        return copy
    end,
}
local respawn=LocalPlayer.CharacterAdded:Connect(function()
    for _,part in ipairs(table.clone(list)) do forget(part) end
    smoothDirection=nil;smoothBombDirection=nil
    jar.busy=false
    jar.respawnAt=os.clock()
end)
runtime.RegisterReset(function()
    for _,controller in pairs(controls) do pcall(function() controller:Set(false) end) end
    settings.shield,settings.intercept,settings.autoJar,settings.ring,settings.mouse=false,false,false,false,false
    settings.sky=false
    settings.fakeBomb,settings.goldBomb,settings.murdererShield=false,false,false
    releaseBomb()
    settings.distance=2.2
    settings.bombSpin=1
    settings.ringDistance,settings.ringSpeed=MMV_OWN.default("ringDistance"),MMV_OWN.default("ringSpeed")
    settings.mm2RingSpeed=2
    settings.shieldDistance,settings.shieldGap=2,0
    if autoLoop then autoLoop:Disconnect();autoLoop=nil end
    stop()
    for _,part in ipairs(table.clone(list)) do forget(part) end
    table.clear(knives)
    if not runtimeAlive then
        respawn:Disconnect()
        if watchAdded then watchAdded:Disconnect();watchAdded=nil end
        if watchRemoved then watchRemoved:Disconnect();watchRemoved=nil end
    end
end)
if active() then task.defer(refresh) end
end,"Section \"Firefly Protection\"")

;vv2Section(function()
-- GGsign Glide: holding the GGSign toy under a roof, you stick to it, spin, and move the way
-- you walk. Smooth now: you are held a steady distance under the roof (no more bouncing
-- into it), the spin keeps a fixed heading, and while gliding the camera follows a point
-- that doesn't spin with you, so it no longer shakes. The roof is looked for 6 studs up.
local section=mainTab:AddSection("GGsign Glide","Utilities")
local DEFAULTS={spin=65,force=50}
local DETECTION=6
local HANG=1.1
local spinSpeed=math.clamp(tonumber(C("ggsignSpinSpeed",DEFAULTS.spin)) or DEFAULTS.spin,0,150)
local moveForce=math.clamp(tonumber(C("ggsignMoveForce",DEFAULTS.force)) or DEFAULTS.force,10,100)
local connection
local angle=0
local gliding=false
local heading=0
local focus,savedSubject
local rayParams=RaycastParams.new()
rayParams.FilterType=Enum.RaycastFilterType.Exclude
local FRAME="VisualsV2_GGsignGlide"

-- spin: turns a second = slider / 20 (65 = 3.25 turns a second, 150 = 7.5), the same at
-- any frame rate (the old one went past what a frame can show, so most of the slider looked
-- the same); move force is your speed in studs a second
local function turnsPerSecond() return spinSpeed/20 end

local function cameraFollow(root)
    local camera=workspace.CurrentCamera
    if not camera then return end
    if not focus or not focus.Parent then
        focus=Instance.new("Part")
        focus.Name="VisualsV2_GlideCameraFocus"
        focus.Anchored=true;focus.CanCollide=false;focus.CanQuery=false;focus.CanTouch=false
        focus.Transparency=1;focus.Size=Vector3.new(0.2,0.2,0.2)
        focus.CFrame=CFrame.new(root.Position+Vector3.new(0,1.5,0))
        focus.Parent=workspace.CurrentCamera
    end
    if camera.CameraSubject~=focus then
        savedSubject=camera.CameraSubject
        camera.CameraSubject=focus
    end
end
local function cameraRelease()
    local camera=workspace.CurrentCamera
    if camera and focus and camera.CameraSubject==focus then
        local character=LocalPlayer.Character
        local humanoid=character and character:FindFirstChildOfClass("Humanoid")
        camera.CameraSubject=(savedSubject and savedSubject.Parent and savedSubject) or humanoid or camera.CameraSubject
    end
    savedSubject=nil
    if focus then focus:Destroy();focus=nil end
end
-- (only undoes its own glide: another feature's physics state is left alone)
local function release(humanoid)
    angle=0
    if not gliding then return end
    gliding=false
    cameraRelease()
    if humanoid and humanoid:GetState()==Enum.HumanoidStateType.Physics then
        humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
    end
end
local function stop()
    if connection then connection:Disconnect();connection=nil end
    pcall(function() RunService:UnbindFromRenderStep(FRAME) end)
    local character=LocalPlayer.Character
    release(character and character:FindFirstChildOfClass("Humanoid"))
end
local function step(deltaTime)
    if not runtimeAlive then stop();return end
    local character=LocalPlayer.Character
    local root=character and character:FindFirstChild("HumanoidRootPart")
    local humanoid=character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health<=0 then if gliding then release(humanoid) end;return end
    local tool=character:FindFirstChildOfClass("Tool")
    local hit=nil
    if tool and tool.Name=="GGSign" then
        rayParams.FilterDescendantsInstances={character}
        hit=workspace:Raycast(root.Position,Vector3.new(0,DETECTION+HANG,0),rayParams)
        if hit and not gliding and hit.Distance>DETECTION then hit=nil end
    end
    if not hit then
        if gliding then release(humanoid) end
        return
    end
    if not gliding then
        gliding=true
        local look=workspace.CurrentCamera and workspace.CurrentCamera.CFrame.LookVector or root.CFrame.LookVector
        heading=math.atan2(-look.X,-look.Z)
    end
    -- the way you walk (heading follows the camera, so turning the camera steers)
    local camera=workspace.CurrentCamera
    if camera then
        local look=camera.CFrame.LookVector
        if Vector3.new(look.X,0,look.Z).Magnitude>0.1 then heading=math.atan2(-look.X,-look.Z) end
    end
    local move=humanoid.MoveDirection
    local horizontal=Vector3.new(move.X,0,move.Z)
    if horizontal.Magnitude>1 then horizontal=horizontal.Unit end
    local velocity=horizontal*moveForce
    -- held a steady distance under the roof, eased there instead of pushed into it
    local goalY=hit.Position.Y-HANG
    local position=root.Position+velocity*deltaTime
    local y=position.Y+(goalY-position.Y)*math.clamp(deltaTime*12,0,1)
    angle=(angle+turnsPerSecond()*360*deltaTime)%360
    root.CFrame=CFrame.new(position.X,y,position.Z)*CFrame.Angles(0,heading,0)
        *CFrame.Angles(math.rad(90),0,math.rad(angle))
    root.AssemblyLinearVelocity=Vector3.new(velocity.X,0,velocity.Z)
    root.AssemblyAngularVelocity=Vector3.zero
    if humanoid:GetState()~=Enum.HumanoidStateType.Physics then humanoid:ChangeState(Enum.HumanoidStateType.Physics) end
    cameraFollow(root)
    if focus then
        local target=root.Position+Vector3.new(0,1.5,0)
        focus.CFrame=CFrame.new(focus.Position:Lerp(target,math.clamp(deltaTime*20,0,1)))
    end
end
local function start()
    if connection then return end
    -- before the camera updates, so it always sees where you really are this frame
    local ok=pcall(function()
        RunService:BindToRenderStep(FRAME,Enum.RenderPriority.Camera.Value-1,function(deltaTime)
            local fine,err=pcall(step,deltaTime)
            if not fine then env.VisualsV2Runtime.GGsignError=tostring(err) end
        end)
    end)
    connection=ok and {Disconnect=function() pcall(function() RunService:UnbindFromRenderStep(FRAME) end) end}
        or RunService.RenderStepped:Connect(step)
end
local glideToggle=addToggle(section,"GGsign Glide",C("ggsignGlideEnabled",false),function(state)
    SetCfg("ggsignGlideEnabled",state)
    if state then start() else stop() end
end)
local sliders={}
sliders.spin=section:AddSlider("Spin Speed",0,150,spinSpeed,function(value)
    spinSpeed=math.clamp(tonumber(value) or DEFAULTS.spin,0,150)
    SetCfg("ggsignSpinSpeed",spinSpeed)
end)
sliders.force=section:AddSlider("Move Force",10,100,moveForce,function(value)
    moveForce=math.clamp(tonumber(value) or DEFAULTS.force,10,100)
    SetCfg("ggsignMoveForce",moveForce)
end)
-- (the sliders follow when the hub lets them be set, on Restore Defaults)
local function setSlider(slider,value)
    if type(slider)~="table" then return false end
    for _,name in ipairs({"SetValue","Set","Update"}) do
        if type(slider[name])=="function" and pcall(slider[name],slider,value) then return true end
    end
    return false
end
local removing=LocalPlayer.CharacterRemoving:Connect(function() angle=0;gliding=false;cameraRelease() end)
env.VisualsV2Runtime.GGsignGlide={IsGliding=function() return gliding end,Step=step,GetSettings=function() return spinSpeed,moveForce,DETECTION end}
env.VisualsV2Runtime.RegisterReset(function()
    glideToggle:Set(false)
    stop()
    if not runtimeAlive then removing:Disconnect();return end
    -- (Restore Defaults: the sliders go back too)
    spinSpeed,moveForce=DEFAULTS.spin,DEFAULTS.force
    setSlider(sliders.spin,spinSpeed);setSlider(sliders.force,moveForce)
end)
end,"Section \"GGsign Glide\"")

