;vv2Section(function()
-- Minecraftizer (by Gato): Minecraft-style textures on the map, by each part's material
local Minecraftizer=mainTab:AddSection("Minecraftizer","World")

local materialTextures = {
    [Enum.Material.Asphalt] = "rbxassetid://10777285622",
    [Enum.Material.Basalt] = "rbxassetid://10777285622",
    [Enum.Material.Brick] = "rbxassetid://10777285622",
    [Enum.Material.Carpet] = "rbxassetid://18699165714",
    [Enum.Material.Fabric] = "rbxassetid://18699165714",
    [Enum.Material.CeramicTiles] = "rbxassetid://82688463827095",
    [Enum.Material.Cobblestone] = "rbxassetid://112006332656762",
    [Enum.Material.Concrete] = "rbxassetid://76434845888896",
    [Enum.Material.CrackedLava] = "rbxassetid://6072514670",
    [Enum.Material.DiamondPlate] = "rbxassetid://121527765592383",
    [Enum.Material.Glacier] = "rbxassetid://138703197443219",
    [Enum.Material.Glass] = "rbxassetid://11384458772",
    [Enum.Material.Granite] = "rbxassetid://84691298982406",
    [Enum.Material.Grass] = "rbxassetid://129412557796389",
    [Enum.Material.LeafyGrass] = "rbxassetid://129412557796389",
    [Enum.Material.Ground] = "rbxassetid://114241584338245",
    [Enum.Material.Ice] = "rbxassetid://11413423466",
    [Enum.Material.Marble] = "rbxassetid://71371694781487",
    [Enum.Material.Metal] = "rbxassetid://8677286748",
    [Enum.Material.Mud] = "rbxassetid://5104022863",
    [Enum.Material.Pavement] = "rbxassetid://76838016906118",
    [Enum.Material.Rock] = "rbxassetid://92531008905854",
    [Enum.Material.Salt] = "rbxassetid://112438351210604",
    [Enum.Material.Sand] = "rbxassetid://9277770677",
    [Enum.Material.Sandstone] = "rbxassetid://120884186339230",
    [Enum.Material.Slate] = "rbxassetid://92531008905854",
    [Enum.Material.Snow] = "rbxassetid://11108881974",
    [Enum.Material.Wood] = "rbxassetid://8676581022",
    [Enum.Material.WoodPlanks] = "rbxassetid://8676581022",
}
-- Every other material gets the nearest of those (most of a map is plastic), so no visible
-- part is left plain; force fields are an effect and stay as they are.
local CONCRETE = "rbxassetid://76434845888896"
local otherTextures = {
    Plastic = CONCRETE, SmoothPlastic = CONCRETE, Neon = CONCRETE, Plaster = CONCRETE, Rubber = CONCRETE,
    Foil = "rbxassetid://8677286748", CorrodedMetal = "rbxassetid://8677286748",
    Limestone = "rbxassetid://120884186339230", Pebble = "rbxassetid://112006332656762",
    Cardboard = "rbxassetid://8676581022", Leather = "rbxassetid://18699165714", Clay = "rbxassetid://114241584338245",
}
local SKIPPED = {ForceField = true}

local faces = Enum.NormalId:GetEnumItems()
local enabled = false
local connection = nil
local made = setmetatable({}, {__mode = "k"})
local hidden = setmetatable({}, {__mode = "k"})
-- (looked up by the material's name)
local texturesByName = {}
for material, id in pairs(materialTextures) do texturesByName[material.Name] = id end
-- a texture that doesn't load is swapped for one that does
local replaced = {}
local function textureFor(part)
    local name = part.Material.Name
    if SKIPPED[name] then return nil end
    local id = texturesByName[name] or otherTextures[name] or CONCRETE
    return replaced[id] or id
end
-- (the other materials only go on plain parts: characters and what they carry, meshes with
-- a texture of their own and parts with decals keep their look)
local function keepsOwnLook(part)
    if part:IsA("MeshPart") and part.TextureID ~= "" then return true end
    if part:FindFirstChildWhichIsA("SurfaceAppearance") or part:FindFirstChildWhichIsA("Decal") then return true end
    return false
end
-- Only the map is textured: nothing on a player (what they hold or wear), no weapon anywhere
-- (the ones on players' backs, a knife flying through the air, a dropped gun) and nothing of
-- Visuals V2's own. (A map is built of anchored parts; weapons and bodies aren't anchored.)
local WEAPON_WORDS = {"knife", "gun", "weapon", "throw", "projectile", "display"}
local function partOfMap(part)
    if not part.Anchored then return false end
    local node = part
    while node and node ~= workspace do
        if node:IsA("Tool") or node:IsA("Accessory") or node:FindFirstChildOfClass("Humanoid") then return false end
        if node:GetAttribute("VisualsV2_ClientWeaponSkin") or node.Name:sub(1, 9) == "VisualsV2" then return false end
        if node.Parent == workspace or node.Parent == workspace.CurrentCamera then
            local name = node.Name:lower()
            for _, word in ipairs(WEAPON_WORDS) do if name:find(word, 1, true) then return false end end
        end
        node = node.Parent
    end
    return true
end

local function applyTexture(part)
    if not enabled or not part.Parent or not part:IsA("BasePart") then return end
    if part.Transparency >= 0.99 then hidden[part] = true;return end
    hidden[part] = nil
    if part:FindFirstChild("MCTexture") or not partOfMap(part) then return end
    if not texturesByName[part.Material.Name] and keepsOwnLook(part) then return end
    local id = textureFor(part)
    if not id then return end

    for _, face in ipairs(faces) do
        local texture = Instance.new("Texture")
        texture.Name = "MCTexture"
        texture.Texture = id
        texture.Face = face
        texture.StudsPerTileU = 4
        texture.StudsPerTileV = 4
        texture.Color3 = part.Color
        texture.Parent = part
        made[texture] = true
    end
end
-- (a map's worth of parts is textured a slice at a time, so turning it on or a new map
-- loading doesn't freeze the game)
local batch = env.VisualsV2Runtime.MakeBatcher(applyTexture, 0.002, 100)

-- Each texture is loaded once to see that it works; one that fails is replaced (also on the
-- parts it is already on).
local checked = false
local function checkTextures()
    if checked then return end
    checked = true
    task.spawn(function()
        local list, seen = {}, {}
        for _, id in pairs(texturesByName) do if not seen[id] then seen[id] = true;list[#list + 1] = id end end
        for _, id in pairs(otherTextures) do if not seen[id] then seen[id] = true;list[#list + 1] = id end end
        local failed = {}
        pcall(function()
            game:GetService("ContentProvider"):PreloadAsync(list, function(contentId, status)
                local state = tostring(status)
                if state:find("Failure", 1, true) or state:find("TimedOut", 1, true) then
                    local digits = tostring(contentId):match("%d+")
                    if digits then failed["rbxassetid://" .. digits] = true end
                end
            end)
        end)
        if not runtimeAlive or not next(failed) then return end
        local working
        for _, id in ipairs({CONCRETE, "rbxassetid://112006332656762", "rbxassetid://92531008905854"}) do
            if not failed[id] then working = id;break end
        end
        if not working then for _, id in ipairs(list) do if not failed[id] then working = id;break end end end
        if not working then return end
        for id in pairs(failed) do replaced[id] = working end
        for texture in pairs(made) do
            local swap = replaced[texture.Texture]
            if swap then texture.Texture = swap end
        end
    end)
end

-- (only the textures it made come off: the map's own textures stay)
local function removeTextures()
    for texture in pairs(made) do
        made[texture] = nil
        pcall(texture.Destroy, texture)
    end
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("Texture") and obj.Name == "MCTexture" then obj:Destroy() end
    end
end

local sweep
local function start()
    enabled = true
    checkTextures()
    for _, part in ipairs(workspace:GetDescendants()) do
        if part:IsA("BasePart") then batch.Push(part) end
    end
    if not connection then
        connection = workspace.DescendantAdded:Connect(function(part)
            if enabled and part:IsA("BasePart") then batch.Push(part) end
        end)
    end
    -- parts that were invisible get theirs once they show up
    if not sweep then
        sweep = task.spawn(function()
            while enabled and runtimeAlive do
                task.wait(3)
                for part in pairs(hidden) do
                    if part.Parent and part.Transparency < 0.99 then batch.Push(part) end
                end
            end
            sweep = nil
        end)
    end
end

local function stop()
    enabled = false
    batch.Clear()
    table.clear(hidden)
    if connection then
        connection:Disconnect()
        connection = nil
    end
    if sweep then pcall(task.cancel, sweep);sweep = nil end
    removeTextures()
end

-- (off until you turn it on; a new setting name, so it starts off also where the earlier
-- version had it on by default)
local toggle = addToggle(Minecraftizer, "Minecraftizer", C("vv2MinecraftizerEnabled", false), function(state)
    SetCfg("vv2MinecraftizerEnabled", state)
    if state then
        start()
    else
        stop()
    end
end)

env.VisualsV2Runtime.RegisterReset(function()
    toggle:Set(false)
    stop()
end)
end,"Section \"Minecraftizer\"")

;vv2Section(function()
local section=mainTab:AddSection("Increase Inventory","Utilities")
section:AddParagraph(
    "Increase Inventory",
    "Increases the number of tools you can carry, up to 10."
)

local inventoryEnabled=C("inventoryUnlimiterEnabled",false)
local inventoryLimit=math.clamp(tonumber(C("inventoryMaxItems",10)) or 10,3,10)
local autoGetTools=C("autoGetTools",false)
local selectedToys={
    C("autoToySlot1","None"), C("autoToySlot2","None"),
    C("autoToySlot3","None"), C("autoToySlot4","None"),
}
if tonumber(C("autoToySelectionVersion",0))<1 then
    if selectedToys[1]=="RCCar26" and selectedToys[2]=="RCCar26" then
        selectedToys[2]="SprayPaint"
        SetCfg("autoToySlot2","SprayPaint")
    end
    SetCfg("autoToySelectionVersion",1)
end
local getgc=getgc or env.getgc
local getupvalues=(debug and debug.getupvalues) or getupvalues or env.getupvalues
local setupvalue=(debug and debug.setupvalue) or setupvalue or env.setupvalue
local getinfo=(debug and debug.getinfo) or getinfo or env.getinfo
local getconstants=(debug and debug.getconstants) or getconstants or env.getconstants
local iscclosure=iscclosure or env.iscclosure
local getfenv=getfenv or env.getfenv
local debugInfo=debug and debug.info
-- the add-on's own functions mention the hotbar's names too; never treat them as the hotbar
local selfSource=nil
if type(debugInfo)=="function" then
    -- level 1 must be a function of this script (through pcall directly it would be pcall)
    local ok,value=pcall(function() return debugInfo(1,"s") end)
    if ok and type(value)=="string" and value~="[C]" then selfSource=value end
end
local targetFunctions={}
local nameOnlyScans=false
local targetsScanned=false
local scanningTargets=false
local targetEpoch=0
local lastTargetScan=-math.huge
local slotReferences={}
local observedGui=nil
local perf={targetScans=0,guiScans=0,slotVisits=0,scanYields=0,targets=0,patchedLimits=0}
local alive=true
local recoveryToken=0
local recoveryRunning=false
local recoveryCharacter=nil
local removingCharacter=nil
local recoveryDeadline=0
local rescanRequested=false
local toyAttempts={}
local activeToyRequest=nil
local toyOrderDirty=true
local orderingBackpack=false
local originalSlotOrders=setmetatable({}, {__mode="k"})
local observedBackpack=nil
local backpackConnections={}
local characterConnections={}
local toyConnections={}
local guiConnections={}
local lifecycleConnections={}
local dropdowns={}
local refreshingDropdowns=false
local guiRefreshToken=0
local requestRecovery,refreshToyDropdowns

local function disconnectAll(connections)
    for _,connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
    table.clear(connections)
end

-- Patched closures belong to a GUI script; when the game rebuilds its hotbar (round
-- start, respawn) the old script is destroyed but its closures linger, so applying the
-- limit to them "works" without changing the live inventory. Detect that and rescan.
local function targetsStale()
    if #targetFunctions==0 or type(getfenv)~="function" then return false end
    for _,f in ipairs(targetFunctions) do
        local ok,context=pcall(getfenv,f)
        local script=ok and type(context)=="table" and rawget(context,"script")
        if typeof(script)~="Instance" then return false end
        local inGame,attached=pcall(function() return script:IsDescendantOf(game) end)
        if not inGame or attached then return false end
    end
    return true
end

-- The hotbar keeps its size as a plain number: 3 on phones, 10 on computers. Every one
-- of those numbers held by the hotbar functions is set to the chosen limit (3-10), the
-- same way Better ODH does it, and each one remembers its original so turning the
-- feature off puts it back.
local originalLimits=setmetatable({}, {__mode="k"})
local function patchTargets()
    if not inventoryEnabled then return 0 end
    local patched=0
    for _,f in ipairs(targetFunctions) do
        local ok,upvalues=pcall(getupvalues,f)
        if ok and type(upvalues)=="table" then
            for index,value in pairs(upvalues) do
                if type(index)=="number" and type(value)=="number" then
                    local records=originalLimits[f]
                    local record=records and records[index]
                    if value==3 or value==10 or (record and value==record.applied) then
                        if not record then
                            if not records then records={};originalLimits[f]=records end
                            record={original=value};records[index]=record
                        end
                        if value==inventoryLimit or pcall(setupvalue,f,index,inventoryLimit) then
                            local verified,current=pcall(function() return getupvalues(f)[index] end)
                            if verified and current==inventoryLimit then record.applied=inventoryLimit;patched=patched+1 end
                        end
                    end
                end
            end
        end
    end
    perf.patchedLimits=patched
    targetsScanned=patched>0
    perf.error=patched==0 and (#targetFunctions>0 and "The hotbar was found but its size could not be changed"
        or "The hotbar has not been found yet") or nil
    return patched
end
local function restoreInventoryLimits()
    for f,records in pairs(originalLimits) do
        for index,record in pairs(records) do
            local ok,upvalues=pcall(getupvalues,f)
            if ok and type(upvalues)=="table" and record.applied~=nil and upvalues[index]==record.applied
                and record.applied~=record.original then
                pcall(setupvalue,f,index,record.original)
            end
        end
    end
    table.clear(originalLimits)
end

-- Finds MM2's hotbar the way Better ODH does (that check finds it every time): a function
-- called updateItemFrame or onItemEquipped, or one that works with both the TouchBinding
-- and the EquipButton of a hotbar slot. Every Lua function in memory is checked; the old
-- scan skipped most functions by name and by script (the hotbar's module included), which
-- is why the extra slots only showed up some of the time. The scan is spread over frames
-- so it never freezes the game.
local function discoverTargets()
    if scanningTargets or os.clock()-lastTargetScan<2 then return end
    if type(getgc)~="function" or type(getupvalues)~="function" or type(setupvalue)~="function" then
        perf.error="This executor does not expose inventory inspection";return
    end
    scanningTargets=true
    lastTargetScan=os.clock()
    local epoch=targetEpoch
    -- listing everything in memory is one long step: never on top of the execute itself
    local settle=4-(os.clock()-bootStarted)
    if settle>0 then
        task.wait(settle)
        if not alive or not runtimeAlive or targetEpoch~=epoch or not inventoryEnabled then scanningTargets=false;return end
        lastTargetScan=os.clock()
    end
    perf.targetScans=perf.targetScans+1
    local okGc,objects=pcall(getgc)
    if not okGc or type(objects)~="table" then scanningTargets=false;return end
    local found={}
    local byName,byConstants=0,0
    local useConstants=not nameOnlyScans and type(getconstants)=="function"
    local function inspect(f)
        if type(iscclosure)=="function" then
            local ok,native=pcall(iscclosure,f)
            if ok and native then return end
        end
        local name,source=nil,nil
        if type(debugInfo)=="function" then
            local ok,s,n=pcall(debugInfo,f,"sn")
            if ok then source,name=s,n end
        elseif type(getinfo)=="function" then
            local ok,info=pcall(getinfo,f)
            if ok and type(info)=="table" then source,name=info.source,info.name end
        end
        if source=="[C]" or (selfSource and source==selfSource) then return end
        -- Roblox's own menus (CoreGui / CorePackages) are never the game's hotbar
        if type(source)=="string" and (source:sub(1,12)=="CorePackages" or source:sub(1,7)=="CoreGui") then return end
        if type(name)=="string" then
            local lowered=name:lower()
            if lowered=="updateitemframe" or lowered=="onitemequipped" then found[#found+1]=f;byName=byName+1;return end
        end
        if not useConstants then return end
        local ok,constants=pcall(getconstants,f)
        if not ok or type(constants)~="table" then return end
        local touch,equip=false,false
        for _,value in pairs(constants) do
            if value=="TouchBinding" then touch=true elseif value=="EquipButton" then equip=true end
        end
        if touch and equip then found[#found+1]=f;byConstants=byConstants+1 end
    end
    local slice=os.clock()
    local checked=0
    for _,f in pairs(objects) do
        if not alive or not runtimeAlive or targetEpoch~=epoch or not inventoryEnabled then scanningTargets=false;return end
        if type(f)=="function" then inspect(f) end
        checked=checked+1
        if checked%16==0 and os.clock()-slice>=bootBudget(0.004) then
            perf.scanYields=perf.scanYields+1
            local log=env.VisualsV2Runtime.Perf
            if log then log.Add("Increase Inventory scan",os.clock()-slice) end
            task.wait()
            slice=os.clock()
        end
    end
    -- When every hotbar function was found by its name, the next scans (one per life) only
    -- look at names, which is far quicker on phones; a scan that then misses goes back to
    -- the full check.
    if useConstants then nameOnlyScans=byName>0 and byConstants==0
    elseif #found==0 then nameOnlyScans=false end
    targetFunctions=found
    perf.targets=#found
    perf.scansDone=(perf.scansDone or 0)+1
    perf.nameOnlyScans=nameOnlyScans
    scanningTargets=false
    patchTargets()
end
-- The scan runs on its own so a long one never holds up the toy requests. Returns false
-- when a requested scan has to wait (one ran less than 2 seconds ago), so it is retried.
local function applyInventoryLimit(force)
    if not inventoryEnabled then return true end
    local started=true
    if force or not targetsScanned then
        if not scanningTargets and os.clock()-lastTargetScan>=2 then task.spawn(discoverTargets)
        elseif force and not scanningTargets then started=false end
    end
    if #targetFunctions>0 then patchTargets() end
    return started
end
local function getBackpack()
    if observedBackpack and observedBackpack.Parent==player then return observedBackpack end
    return player:FindFirstChildOfClass("Backpack")
end

local function findToyFolder()
    local backpack=getBackpack()
    return backpack and backpack:FindFirstChild("Toys") or nil
end

local function getToyNames()
    local names={"None"}
    local folder=findToyFolder()
    if folder then
        for _,toy in ipairs(folder:GetChildren()) do
            if not table.find(names,toy.Name) then names[#names+1]=toy.Name end
        end
    end
    table.sort(names,function(a,b)
        if a==b then return false end
        if a=="None" then return true end
        if b=="None" then return false end
        return a:lower()<b:lower()
    end)
    return names
end

local function hasSelectedTool(name,char,backpack)
    local inCharacter=char and char:FindFirstChild(name)
    local inBackpack=backpack and backpack:FindFirstChild(name)
    return (inCharacter and inCharacter:IsA("Tool")) or (inBackpack and inBackpack:IsA("Tool")) or false
end

local function toyRemote()
    local rs=game:GetService("ReplicatedStorage")
    local remotes=rs:FindFirstChild("Remotes")
    local extras=remotes and remotes:FindFirstChild("Extras")
    local remote=extras and extras:FindFirstChild("ReplicateToy")
    if remote and remote:IsA("RemoteFunction") then return remote end
end

local function isNativeSlot(reference)
    local slot=reference.Parent
    if not slot or not slot:IsA("GuiObject") or not slot.Parent then return false end
    local current=slot
    while current and current~=observedGui do
        if current.Name:sub(1,10)=="VisualsV2_" or current:GetAttribute("VisualsV2_InventoryVisual") then return false end
        if current.Name=="Inventory" or current.Name=="Inventory2" then
            local main=current:FindFirstChild("Main") or current
            if main:FindFirstChild("Weapons") or main:FindFirstChild("Effects") or main:FindFirstChild("Pets") then return false end
        end
        current=current.Parent
    end
    return current==observedGui and slot.Parent:FindFirstChildOfClass("UIListLayout")~=nil
end
local function cacheReference(reference)
    if slotReferences[reference] or not reference:IsA("ObjectValue") or not isNativeSlot(reference) then return end
    slotReferences[reference]=reference:GetPropertyChangedSignal("Value"):Connect(function()
        toyOrderDirty=true
        requestRecovery(false)
    end)
    toyOrderDirty=true
end
local function clearReferences()
    for _,connection in pairs(slotReferences) do connection:Disconnect() end
    table.clear(slotReferences)
end
local function scanSlotReferences(gui)
    perf.guiScans=perf.guiScans+1
    local pending={gui}
    local count=0
    local sliceStart=os.clock()
    while #pending>0 and alive and runtimeAlive and observedGui==gui do
        local object=table.remove(pending)
        local skip=object~=gui and (object.Name:sub(1,10)=="VisualsV2_" or object:GetAttribute("VisualsV2_InventoryVisual"))
        if not skip and (object.Name=="Inventory" or object.Name=="Inventory2") then
            local main=object:FindFirstChild("Main") or object
            skip=main:FindFirstChild("Weapons") or main:FindFirstChild("Effects") or main:FindFirstChild("Pets")
        end
        if not skip then
            cacheReference(object)
            for _,child in ipairs(object:GetChildren()) do pending[#pending+1]=child end
        end
        count=count+1
        if count%64==0 and os.clock()-sliceStart>=bootBudget(0.003) then task.wait();sliceStart=os.clock() end
    end
end
-- The order is kept for every life: the game builds new hotbar slots after a respawn, so
-- when not every chosen toy's slot is known yet the hotbar is looked through again, and a
-- slot the game re-orders on its own is put back straight away. The order is only set
-- once every chosen toy's slot is known (setting some of them early put a later toy
-- first), and a slot that the game has since given another toy is never forced.
local orderedSlots=setmetatable({}, {__mode="k"})
local slotOrderWatch=setmetatable({}, {__mode="k"})
local lastReferenceRescan=-math.huge
-- (none of the chosen toys' hotbar slots can be told apart at all: there's nothing to put in
-- order, so it's no reason to wait, and the hotbar is only looked through again now and then)
local orderUnavailable=false
-- (whether a slot put in order still holds that toy: by the value in it, or for MM2's own
-- hotbar by the toy's picture in it)
local function holdsStill(slot,desired)
    if desired.kind=="picture" then
        local icon=desired.icon
        return icon.Parent~=nil and icon:IsDescendantOf(slot) and icon.Image==desired.picture
    end
    return desired.reference.Parent==slot and desired.reference.Value==desired.tool
end
-- MM2's own hotbar (PlayerGui.BackpackUI, a BackpackItem for each tool): nothing in a slot
-- says which tool it holds, but each shows its tool's picture (its ToolIcon), so a chosen
-- toy's slot is the one with its picture. (Two chosen toys with the same picture: can't tell.)
local function pictureSlots(order)
    local gui=observedGui
    local ui=gui and gui:FindFirstChild("BackpackUI")
    local frame=ui and (ui:FindFirstChild("BackpackFrame") or ui:FindFirstChild("BackpackFrame",true))
    if not frame then return nil end
    local byPicture={}
    for tool in pairs(order) do
        local ok,picture=pcall(function() return tool.TextureId end)
        if not ok or type(picture)~="string" or picture=="" or byPicture[picture] then return nil end
        byPicture[picture]=tool
    end
    local found,seen={},{}
    for _,item in ipairs(frame:GetChildren()) do
        if item:IsA("GuiObject") then
            local icon=item:FindFirstChild("ToolIcon",true)
            local tool=icon and (icon:IsA("ImageLabel") or icon:IsA("ImageButton")) and byPicture[icon.Image]
            if tool and not seen[tool] then
                seen[tool]=true
                found[#found+1]={slot=item,icon=icon,picture=icon.Image,tool=tool,index=order[tool]}
            end
        end
    end
    return found
end
local function watchSlotOrder(slot)
    if slotOrderWatch[slot] then return end
    local burstAt,burst=0,0
    slotOrderWatch[slot]=slot:GetPropertyChangedSignal("LayoutOrder"):Connect(function()
        local desired=orderedSlots[slot]
        if not desired or slot.LayoutOrder==desired.order or not autoGetTools then return end
        if not holdsStill(slot,desired) then
            orderedSlots[slot]=nil;toyOrderDirty=true;requestRecovery(false);return
        end
        local now=os.clock()
        if now-burstAt>1 then burstAt=now;burst=0 end
        burst=burst+1
        if burst>6 then return end
        slot.LayoutOrder=desired.order
    end)
    guiConnections[#guiConnections+1]=slotOrderWatch[slot]
end
local function orderSelectedTools(char,backpack,token)
    if not backpack or player.Character~=char or token~=recoveryToken then return false end
    local order={}
    local wanted=0
    for slot=1,4 do
        local name=selectedToys[slot]
        if name and name~="None" then
            local tool=char:FindFirstChild(name) or backpack:FindFirstChild(name)
            if not tool or not tool:IsA("Tool") then return false end
            if not order[tool] then order[tool]=slot;wanted=wanted+1 end
        end
    end

    local matched,count={},0
    local chosen,others={},{}
    for reference,connection in pairs(slotReferences) do
        perf.slotVisits=perf.slotVisits+1
        if not reference.Parent or not isNativeSlot(reference) then
            connection:Disconnect();slotReferences[reference]=nil
        else
            local slot=reference.Parent
            local index=order[reference.Value]
            if index then
                chosen[#chosen+1]={slot=slot,reference=reference,index=index}
                if not matched[reference.Value] then matched[reference.Value]=true;count=count+1 end
            else
                others[#others+1]=slot
            end
        end
    end
    -- MM2's own hotbar: the chosen toys' slots found by their pictures, and put in your order
    -- in the places those slots already have between them (nothing else on the hotbar moves;
    -- each slot keeps its own number, so a number key still takes out the toy it shows)
    if count==0 and wanted>0 then
        local pictured=pictureSlots(order)
        if pictured and #pictured>=wanted then
            local places={}
            for _,entry in ipairs(pictured) do places[#places+1]=entry.slot.LayoutOrder end
            table.sort(places)
            table.sort(pictured,function(a,b) return a.index<b.index end)
            for position,entry in ipairs(pictured) do
                local slot=entry.slot
                if originalSlotOrders[slot]==nil then originalSlotOrders[slot]=slot.LayoutOrder end
                orderedSlots[slot]={order=places[position],kind="picture",icon=entry.icon,picture=entry.picture,tool=entry.tool}
                if slot.LayoutOrder~=places[position] then slot.LayoutOrder=places[position] end
                watchSlotOrder(slot)
            end
            orderUnavailable=false
            perf.pictureOrders=(perf.pictureOrders or 0)+1
            return true
        elseif pictured and #pictured>0 then
            -- (the rest not shown yet: waited for, and it's still worth waiting for)
            orderUnavailable=false
            return false
        end
    end
    orderUnavailable=count==0 and wanted>0
    if count<wanted then
        perf.orderMisses=(perf.orderMisses or 0)+1
        if observedGui and os.clock()-lastReferenceRescan>(orderUnavailable and 8 or 1.5) then
            lastReferenceRescan=os.clock()
            local gui=observedGui
            task.spawn(function() if observedGui==gui then scanSlotReferences(gui) end end)
        end
        return false
    end
    -- every chosen toy's slot is known: all of them at once, 1 first and 4 last
    for _,entry in ipairs(chosen) do
        local slot=entry.slot
        if originalSlotOrders[slot]==nil then originalSlotOrders[slot]=slot.LayoutOrder end
        orderedSlots[slot]={order=entry.index-100,reference=entry.reference,tool=entry.reference.Value}
        if slot.LayoutOrder~=entry.index-100 then slot.LayoutOrder=entry.index-100 end
        watchSlotOrder(slot)
    end
    for _,slot in ipairs(others) do
        if orderedSlots[slot] or (originalSlotOrders[slot]~=nil and slot.LayoutOrder<0) then
            orderedSlots[slot]=nil
            local original=originalSlotOrders[slot]
            originalSlotOrders[slot]=nil
            -- (a slot now holding another toy goes back behind the chosen ones)
            if original~=nil and original>=0 then slot.LayoutOrder=original
            elseif slot.LayoutOrder<0 then slot.LayoutOrder=0 end
        end
    end
    return true
end
-- The hotbar only re-reads its capacity when its tool list changes, which is why the
-- extra slots appeared when the Sheriff gun was handed out. After patching, nudge it
-- once by re-adding a toy locally (no weapon is touched; nothing is sent to the server).
local nudgedEpoch,nudgedCharacter,lastNudge=nil,nil,-math.huge
local function nudgeHotbar()
    if not alive or not runtimeAlive or not inventoryEnabled or os.clock()-lastNudge<3 then return end
    local backpack=getBackpack()
    if not backpack then return end
    local skins=env.VisualsV2Runtime.ClientWeaponSkins
    local candidate
    for _,tool in ipairs(backpack:GetChildren()) do
        if tool:IsA("Tool") and not (skins and skins.GetKind(tool)) then candidate=tool end
    end
    if not candidate then return end
    lastNudge=os.clock()
    orderingBackpack=true
    pcall(function() candidate.Parent=nil;candidate.Parent=backpack end)
    orderingBackpack=false
    toyOrderDirty=true
end
local function cancelToyRequests()
    for _,attempt in pairs(toyAttempts) do
        if attempt.thread and type(task.cancel)=="function" then pcall(task.cancel,attempt.thread) end
    end
    table.clear(toyAttempts)
    activeToyRequest=nil
end

local function cancelRecovery()
    recoveryToken=recoveryToken+1
    recoveryRunning=false
    recoveryCharacter=nil
    recoveryDeadline=0
    rescanRequested=false
    toyOrderDirty=true
    cancelToyRequests()
end

-- How many tools the hotbar is actually showing versus how many the player has.
local function hotbarCounts(char)
    local backpack=getBackpack()
    local shownTools={}
    for reference in pairs(slotReferences) do
        local ok,value=pcall(function() return reference.Value end)
        if ok and typeof(value)=="Instance" and value:IsA("Tool") and (value.Parent==char or value.Parent==backpack)
            and reference.Parent and reference.Parent:IsA("GuiObject") and reference.Parent.Visible then
            shownTools[value]=true
        end
    end
    local shown,owned=0,0
    for _ in pairs(shownTools) do shown=shown+1 end
    for _,container in ipairs({char,backpack}) do
        if container then
            for _,item in ipairs(container:GetChildren()) do if item:IsA("Tool") then owned=owned+1 end end
        end
    end
    return shown,owned
end
local TOY_MAX_ATTEMPTS=8
local TOY_RETRY={0.5,0.6,0.9,1.3,2,2.5,3,3}
local TOY_INTERVAL=0.5
local function isCurrentRecovery(token,char)
    return alive and runtimeAlive and token==recoveryToken
        and player.Character==char and char~=removingCharacter
        and (inventoryEnabled or autoGetTools)
end

requestRecovery=function(forceScan)
    if not alive or not runtimeAlive or not (inventoryEnabled or autoGetTools) then return end
    local char=player.Character
    if not char or char==removingCharacter then return end
    if recoveryCharacter~=char then
        cancelRecovery()
        recoveryCharacter=char
    end
    if forceScan then rescanRequested=true end
    recoveryDeadline=math.max(recoveryDeadline,os.clock()+20)
    if recoveryRunning then return end
    recoveryRunning=true
    local token=recoveryToken
    task.spawn(function()
        local startedAt=os.clock()
        local scanTimes={0,1,3,6,10,15}
        local scanIndex=1
        local nextInventoryApply=0
        local nextToyRequest=0
        local nextStaleCheck=0
        local lastRetryScan=startedAt
        local retryScans=0
        local nextCapacityCheck=startedAt+2
        local shortChecks=0
        local shortNudges=0
        local lastCapacityRescan=-math.huge
        local spawnScanned=false
        while isCurrentRecovery(token,char) and os.clock()<recoveryDeadline do
            local now=os.clock()
            -- keep maintaining the limit for as long as Increase Inventory is on, not
            -- only for 20 seconds after spawning
            if inventoryEnabled then recoveryDeadline=math.max(recoveryDeadline,now+20) end
            local humanoid=char:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.Health>0 then
                local force=rescanRequested
                if scanTimes[scanIndex] and now-startedAt>=scanTimes[scanIndex] then
                    force=force or not targetsScanned
                    repeat scanIndex=scanIndex+1
                    until not scanTimes[scanIndex] or now-startedAt<scanTimes[scanIndex]
                end
                -- the game builds a fresh hotbar for every life, so look for it again a
                -- second after spawning (what Better ODH does) instead of trusting the old one
                if inventoryEnabled and not spawnScanned and now-startedAt>=1 then
                    if lastTargetScan>=startedAt+1 then spawnScanned=true
                    elseif not scanningTargets and os.clock()-lastTargetScan>=2 then spawnScanned=true;force=true end
                end
                if inventoryEnabled then
                    if targetsScanned and now>=nextStaleCheck then
                        nextStaleCheck=now+1
                        if targetsStale() then
                            targetEpoch=targetEpoch+1
                            targetsScanned=false
                            lastTargetScan=-math.huge
                            force=true
                        end
                    elseif not targetsScanned and not scanTimes[scanIndex] and retryScans<6 and now-lastRetryScan>=15 then
                        lastRetryScan=now;retryScans=retryScans+1
                        force=true
                    end
                end
                if inventoryEnabled and targetsScanned and now>=nextCapacityCheck then
                    nextCapacityCheck=now+1
                    local shown,owned=hotbarCounts(char)
                    if shown>=1 and owned>3 and shown<=3 and shown<math.min(owned,inventoryLimit) then
                        shortChecks=shortChecks+1
                    else
                        shortChecks=0
                    end
                    -- the hotbar only re-reads its size when its tools change: try re-adding a
                    -- toy first, and only look for the limit again if that didn't help
                    if shortChecks>=2 and shortNudges<2 and os.clock()-lastNudge>=3 then
                        shortChecks=0;shortNudges=shortNudges+1
                        task.defer(nudgeHotbar)
                    elseif shortChecks>=2 and now-lastCapacityRescan>=12 then
                        shortChecks=0;shortNudges=0;lastCapacityRescan=now
                        targetEpoch=targetEpoch+1
                        targetsScanned=false
                        lastTargetScan=-math.huge
                        force=true
                    end
                end
                -- a memory scan is a heavy single step; never start one while a trade is open
                local trade=env.VisualsV2Runtime.Trade
                local deferScan=force and trade and trade.active
                if deferScan then force=false end
                if inventoryEnabled and (force or (targetsScanned and now>=nextInventoryApply)) then
                    if not applyInventoryLimit(force) then deferScan=true end
                    nextInventoryApply=now+(now-startedAt>20 and 3 or 1)
                    local key=targetEpoch..":"..(perf.scansDone or 0)..":"..inventoryLimit
                    if perf.patchedLimits>0 and (nudgedEpoch~=key or nudgedCharacter~=char) then
                        nudgedEpoch=key;nudgedCharacter=char
                        task.defer(nudgeHotbar)
                    end
                end
                rescanRequested=deferScan and true or false

                if autoGetTools then
                    local backpack=getBackpack()
                    if toyOrderDirty and backpack and orderSelectedTools(char,backpack,token) then
                        toyOrderDirty=false
                    end
                end
                -- Missing toys are asked for one at a time, in slot order, with half a
                -- second between one toy arriving and the next request (retries included).
                if autoGetTools and not activeToyRequest and now>=nextToyRequest then
                    local backpack=getBackpack()
                    local folder=findToyFolder()
                    local remote=toyRemote()
                    if backpack and folder and remote then
                        local seen={}
                        for slot=1,4 do
                            local name=selectedToys[slot]
                            if name and name~="None" and not seen[name] then
                                seen[name]=true
                                if hasSelectedTool(name,char,backpack) then
                                    -- got it; if the game takes it away later, start over
                                    local done=toyAttempts[name]
                                    if done and not done.inFlight then toyAttempts[name]=nil end
                                elseif not activeToyRequest then
                                    local attempt=toyAttempts[name]
                                    if not attempt then
                                        attempt={count=0,nextAt=0,inFlight=false}
                                        toyAttempts[name]=attempt
                                    end
                                    if folder:FindFirstChild(name) and not attempt.inFlight and attempt.count<TOY_MAX_ATTEMPTS and now>=attempt.nextAt then
                                        attempt.count=attempt.count+1
                                        attempt.inFlight=true
                                        local request={name=name}
                                        activeToyRequest=request
                                        attempt.thread=task.spawn(function()
                                            local sent=false
                                            if isCurrentRecovery(token,char) and autoGetTools
                                                and not hasSelectedTool(name,char,getBackpack()) then
                                                sent=true
                                                pcall(function() remote:InvokeServer(name) end)
                                            end
                                            attempt.inFlight=false
                                            attempt.thread=nil
                                            attempt.nextAt=os.clock()+(TOY_RETRY[attempt.count] or 3)
                                            if activeToyRequest==request then activeToyRequest=nil end
                                            if sent then nextToyRequest=os.clock()+TOY_INTERVAL end
                                            if isCurrentRecovery(token,char) and autoGetTools then requestRecovery(false) end
                                        end)
                                    end
                                end
                            end
                        end
                    end
                end
            end
            task.wait(os.clock()-startedAt<8 and 0.1 or 0.2)
        end
        if token==recoveryToken then recoveryRunning=false end
    end)
end

refreshToyDropdowns=function()
    local names=getToyNames()
    refreshingDropdowns=true
    local saved=table.clone(selectedToys)
    for slot,dropdown in ipairs(dropdowns) do
        local selection=saved[slot]
        if dropdown then
            if type(dropdown.Change)=="function" then
                pcall(dropdown.Change,names)
            elseif type(dropdown.ChangeItems)=="function" then
                pcall(function() dropdown:ChangeItems(names) end)
            end
            if type(dropdown.Select)=="function" then
                local ok=pcall(dropdown.Select,selection)
                if not ok then pcall(function() dropdown:Select(selection) end) end
            end
        end
    end
    refreshingDropdowns=false
end

local function watchToyFolder(folder)
    disconnectAll(toyConnections)
    if not folder then return end
    local function changed()
        refreshToyDropdowns()
        requestRecovery(false)
    end
    toyConnections[#toyConnections+1]=folder.ChildAdded:Connect(changed)
    toyConnections[#toyConnections+1]=folder.ChildRemoved:Connect(changed)
end

local function watchBackpack(backpack)
    disconnectAll(backpackConnections)
    disconnectAll(toyConnections)
    observedBackpack=backpack
    toyOrderDirty=true
    if not backpack then return end
    watchToyFolder(backpack:FindFirstChild("Toys"))
    backpackConnections[#backpackConnections+1]=backpack.ChildAdded:Connect(function(child)
        if child.Name=="Toys" then
            watchToyFolder(child)
            refreshToyDropdowns()
            requestRecovery(false)
        elseif child:IsA("Tool") and not orderingBackpack then
            toyOrderDirty=true
            requestRecovery(false)
        end
    end)
    backpackConnections[#backpackConnections+1]=backpack.ChildRemoved:Connect(function(child)
        if child.Name=="Toys" then watchToyFolder(nil)
        elseif child:IsA("Tool") and not orderingBackpack then
            toyOrderDirty=true
            requestRecovery(false)
        end
    end)
    refreshToyDropdowns()
end

local function watchCharacter(char)
    disconnectAll(characterConnections)
    if not char then return end
    local function changed(child)
        if child:IsA("Tool") then
            toyOrderDirty=true
            requestRecovery(false)
        end
    end
    characterConnections[1]=char.ChildAdded:Connect(changed)
    characterConnections[2]=char.ChildRemoved:Connect(changed)
end

local guiForceScan=false
local function queueGuiRecovery(invalidate)
    if invalidate then
        targetEpoch=targetEpoch+1
        targetsScanned=false
        lastTargetScan=-math.huge
        guiForceScan=true
    end
    guiRefreshToken=guiRefreshToken+1
    local token=guiRefreshToken
    task.delay(0.35,function()
        if alive and token==guiRefreshToken then
            local force=guiForceScan
            guiForceScan=false
            requestRecovery(force)
        end
    end)
end

local function watchPlayerGui(gui)
    disconnectAll(guiConnections)
    clearReferences()
    observedGui=gui
    if not gui then return end
    task.defer(function() scanSlotReferences(gui) end)
    guiConnections[#guiConnections+1]=gui.ChildAdded:Connect(function(child)
        if child.Name=="MainGUI" then queueGuiRecovery(true) end
    end)
    guiConnections[#guiConnections+1]=gui.DescendantAdded:Connect(function(child)
        local trade=env.VisualsV2Runtime.Trade
        if trade and trade.active then return end
        local inTrade=trade and type(trade.InWindow)=="function" and trade.InWindow
        if child:IsA("ObjectValue") then
            if not (inTrade and inTrade(child)) then cacheReference(child) end
        elseif child:IsA("UIListLayout") and child.Parent then
            if inTrade and inTrade(child) then return end
            for _,slot in ipairs(child.Parent:GetChildren()) do
                for _,reference in ipairs(slot:GetChildren()) do cacheReference(reference) end
            end
        elseif child.Name=="EquipButton" or child.Name=="TouchBinding" then queueGuiRecovery(false)
        -- (MM2's own hotbar: a slot made or given a tool's picture: the order looked at again)
        elseif child.Name=="ToolIcon" or child.Name=="BackpackItem" then toyOrderDirty=true;queueGuiRecovery(false) end
    end)
end

-- hotbar changes made while a trade was open were skipped; pick them up afterwards
do
    local trade=env.VisualsV2Runtime.Trade
    if trade then
        trade.OnChanged(function(active)
            if active or not alive or not runtimeAlive then return end
            local gui=observedGui
            if gui then task.defer(function() if observedGui==gui then scanSlotReferences(gui) end end) end
            requestRecovery(false)
        end)
    end
end

-- (Firefly Protection's Auto Use Firefly Jar waits for this: every chosen toy fetched and in
-- its slot first)
env.VisualsV2Runtime.AutoGetTools={Busy=function()
    if not autoGetTools or not alive or not runtimeAlive then return false end
    if activeToyRequest~=nil or (toyOrderDirty and not orderUnavailable) then return true end
    local char=player.Character
    local backpack=getBackpack()
    if not char or not backpack then return true end
    for slot=1,4 do
        local name=selectedToys[slot]
        if name and name~="None" and not hasSelectedTool(name,char,backpack) then
            local attempt=toyAttempts[name]
            -- (a toy that can't be had, after every try, holds nothing up)
            if not attempt or attempt.count<TOY_MAX_ATTEMPTS then return true end
        end
    end
    return false
end,
-- (after the jar has been taken out and put back: every chosen toy back in its slot)
RequestOrder=function()
    if not autoGetTools or not alive or not runtimeAlive then return end
    toyOrderDirty=true
    pcall(requestRecovery,false)
end,
-- (for the status: whether the hotbar's slots for the chosen toys could be found)
CanOrder=function() return not orderUnavailable end,
}
-- Chosen toys kept in their places: a few times a second every chosen toy's slot is looked
-- at, and one the game has moved (it re-sorts its hotbar when a tool goes in and out of your
-- hand, as the firefly jar does when it's used) is put straight back; a slot the game has
-- rebuilt or given another toy gets the whole order set again. (This never counts as Auto
-- Get Tools being busy, so it doesn't hold up Auto Use Firefly Jar.)
task.spawn(function()
    local lastKick=-math.huge
    while alive and runtimeAlive do
        task.wait(0.2)
        if autoGetTools then
            pcall(function()
                local trade=env.VisualsV2Runtime.Trade
                if trade and trade.active then return end
                local stale=false
                for slot,desired in pairs(orderedSlots) do
                    if not slot.Parent or not holdsStill(slot,desired) then
                        orderedSlots[slot]=nil
                        stale=true
                    elseif slot.LayoutOrder~=desired.order then
                        slot.LayoutOrder=desired.order
                    end
                end
                if stale then toyOrderDirty=true end
                -- (a slot the game rebuilt is ordered again; a toy that can't be had doesn't
                -- keep this going: at most every 2 s)
                if toyOrderDirty and not recoveryRunning and (stale or os.clock()-lastKick>(orderUnavailable and 8 or 2)) then
                    lastKick=os.clock()
                    requestRecovery(false)
                end
            end)
        end
    end
end)
local inventoryToggle=addToggle(section,"Increase Inventory",inventoryEnabled,function(state)
    inventoryEnabled=state
    SetCfg("inventoryUnlimiterEnabled",state)
    if state then requestRecovery(true)
    else
        restoreInventoryLimits()
        if not autoGetTools then cancelRecovery() end
    end
end)
section:AddSlider("Max Items",3,10,inventoryLimit,function(value)
    inventoryLimit=math.clamp(math.floor(tonumber(value) or 10),3,10)
    SetCfg("inventoryMaxItems",inventoryLimit)
    if inventoryEnabled then
        if targetsScanned then applyInventoryLimit(false) end
        requestRecovery(not targetsScanned)
    end
end)
local autoToggle=addToggle(section,"Auto Get Tools",autoGetTools,function(state)
    local wasEnabled=autoGetTools
    autoGetTools=state
    toyOrderDirty=true
    SetCfg("autoGetTools",state)
    if state then
        if not wasEnabled then cancelToyRequests() end
        requestRecovery(false)
    else
        cancelToyRequests()
        for slot,order in pairs(originalSlotOrders) do pcall(function() slot.LayoutOrder=order end) end
        table.clear(originalSlotOrders)
        if not inventoryEnabled then cancelRecovery() end
    end
end)

local toyNames=getToyNames()
refreshingDropdowns=true
for index=1,4 do
    local slot=index
    dropdowns[slot]=addDropdown(section,"Select Toy Slot "..slot,toyNames,selectedToys[slot],function(selected)
        if refreshingDropdowns then return end
        if type(selected)=="table" then selected=selected[1] or selected.Value or selected.value end
        if type(selected)~="string" or not table.find(getToyNames(),selected) then return false end
        selectedToys[slot]=selected
        SetCfg("autoToySlot"..slot,selected)
        toyOrderDirty=true
        if autoGetTools then
            local previous=toyAttempts[selected]
            if not previous or not previous.inFlight then toyAttempts[selected]=nil end
            requestRecovery(false)
        end
    end)
end
refreshingDropdowns=false
section:AddButton("Refresh Toy List",function() refreshToyDropdowns() end)

lifecycleConnections[#lifecycleConnections+1]=player.CharacterRemoving:Connect(function(char)
    removingCharacter=char
    disconnectAll(characterConnections)
    cancelRecovery()
end)
lifecycleConnections[#lifecycleConnections+1]=player.CharacterAdded:Connect(function(char)
    removingCharacter=nil
    watchCharacter(char)
    watchBackpack(player:FindFirstChildOfClass("Backpack"))
    requestRecovery(false)
    -- (the hotbar of the new life, once the game has built it, and again a little later)
    for _,delay in ipairs({1.5,4}) do
        task.delay(delay,function()
            if alive and runtimeAlive and player.Character==char and observedGui and (autoGetTools or inventoryEnabled) then
                lastReferenceRescan=os.clock()
                scanSlotReferences(observedGui)
                toyOrderDirty=true
                requestRecovery(false)
            end
        end)
    end
end)
lifecycleConnections[#lifecycleConnections+1]=player.ChildAdded:Connect(function(child)
    if child:IsA("Backpack") then
        watchBackpack(child)
        requestRecovery(false)
    elseif child:IsA("PlayerGui") then
        watchPlayerGui(child)
        requestRecovery(true)
    end
end)
local replicatedStorage=game:GetService("ReplicatedStorage")
lifecycleConnections[#lifecycleConnections+1]=replicatedStorage.DescendantAdded:Connect(function(child)
    if child.Name=="Remotes" or child.Name=="Extras" or child.Name=="ReplicateToy" then requestRecovery(false) end
end)
watchBackpack(player:FindFirstChildOfClass("Backpack"))
watchCharacter(player.Character)
watchPlayerGui(player:FindFirstChildOfClass("PlayerGui"))
if inventoryEnabled or autoGetTools then task.defer(function() requestRecovery(false) end) end

env.VisualsV2Runtime.InventoryTools={GetDiagnostics=function() return table.clone(perf) end}
env.VisualsV2Runtime.RegisterReset(function()
    alive=false
    guiRefreshToken=guiRefreshToken+1
    cancelRecovery()
    inventoryToggle:Set(false)
    autoToggle:Set(false)
    inventoryEnabled=false
    autoGetTools=false
    restoreInventoryLimits()
    for slot,order in pairs(originalSlotOrders) do pcall(function() slot.LayoutOrder=order end) end
    table.clear(originalSlotOrders)
    disconnectAll(lifecycleConnections)
    disconnectAll(backpackConnections)
    disconnectAll(characterConnections)
    disconnectAll(toyConnections)
    disconnectAll(guiConnections)
    clearReferences()
end)
end,"Section \"Increase Inventory\"")

