-- shows whether a freeze came from the add-on (its own work) or from the game itself
miscSection:AddButton("VV2 Performance Report",function()
    local perf=env.VisualsV2Runtime.Perf
    if not perf then return end
    local report=perf.Report()
    local parts={}
    for index=1,math.min(3,#report.top) do
        local item=report.top[index]
        parts[#parts+1]=string.format("%s %d ms",item[1],math.floor(item[2]*1000+0.5))
    end
    local text=string.format("Last 30s: add-on work %d ms%s. Longest frame %.2fs%s.",
        math.floor(report.total*1000+0.5),#parts>0 and (" ("..table.concat(parts,", ")..")") or "",
        report.longestFrame,report.trade and " (a trade was open)" or "")
    pcall(shared.Notify,text,3)
    -- and how starting the add-on went (its first 20 seconds)
    if type(perf.BootReport)=="function" then
        local start=perf.BootReport()
        local top={}
        for index=1,math.min(3,#start.top) do
            local item=start.top[index]
            top[#top+1]=string.format("%s %d ms",item[1],math.floor(item[2]*1000+0.5))
        end
        local startText=string.format("Start-up: execute %d ms, then add-on work %d ms%s. Longest frame %.2fs, %d frames over 0.1s.",
            math.floor((start.execute or 0)*1000+0.5),math.floor(start.total*1000+0.5),
            #top>0 and (" ("..table.concat(top,", ")..")") or "",start.longestFrame,start.slowFrames)
        task.delay(0.5,function() pcall(shared.Notify,startText,4) end)
    end
end)
